-- listings: city_id is looked up by city name
INSERT INTO listings (id, host_id, title, description, property_type, city_id, neighborhood, address,
  latitude, longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds,
  bathrooms, price_per_night, cleaning_fee, currency, created_at)
OVERRIDING SYSTEM VALUE
SELECT v.id, v.host_id, v.title, v.description, v.property_type, c.id, v.neighborhood, v.address,
  v.latitude, v.longitude, v.public_location, v.max_guests, v.pets_allowed, v.max_pets, v.bedrooms,
  v.beds, v.bathrooms, v.price_per_night, v.cleaning_fee, v.currency, v.created_at::timestamptz
FROM (VALUES
  (1, 1, 'Bohemian apt with garden near RAI!', 'Cosy house in a quiet street yet close to all the restaurants, bars, Albert Cuyp Market and Rijksmuseum', 'entire_place'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '149 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.34903, 4.89508, ST_SetSRID(ST_MakePoint(4.895391, 52.346505), 4326)::geography, 2, false, 0, 1, 1, 1.5, 226.0, 72.0, 'EUR', '2018-01-01'),
  (2, 1, 'Appartement in de Pijp Amsterdam', 'This cozy, cozy apartment has all the necessary facilities and is located in the heart of the bustling neighborhood of Amsterdam: de Pijp. This is the place to be when you are in Amsterdam. It is a lively and trendy neighborhood with many restaurants, bars, shops, and famous places such as the Albert Cuyp market, Museumplein and Sarphatipark. In addition, there is a tram stop + metro station within a two-minute walk, so there is a great connection to all of Amsterdam.', 'entire_place'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '137 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.35229, 4.88962, ST_SetSRID(ST_MakePoint(4.885114, 52.354293), 4326)::geography, 2, false, 0, 1, 1, 1.0, 327.33, 85.0, 'EUR', '2018-01-01'),
  (3, 1, 'Comfortable double room', 'Basic bedroom in the center of Amsterdam.', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '145 Demo Street, Centrum-West, Amsterdam', 52.36775, 4.89092, ST_SetSRID(ST_MakePoint(4.889293, 52.365886), 4326)::geography, 2, false, 0, 1, 1, 1.0, 97.0, 30.0, 'EUR', '2018-01-01'),
  (4, 6, 'Double penthouse + stunning rooftop terrace', 'Welcome to our beautiful, renovated apartment (136 m2) in the bustling De Pijp district!

Located in the quiet Gerard Doustraat, this luxurious apartment is on the 3rd floor. It is equipped with all comforts and is therefore ideal for a comfortable city trip in Amsterdam!', 'entire_place'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '5 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.35777, 4.89828, ST_SetSRID(ST_MakePoint(4.893871, 52.359402), 4326)::geography, 4, false, 0, 3, 3, 1.5, 804.67, 90.0, 'EUR', '2018-01-01'),
  (5, 7, 'Singel Room, in het hart van Amsterdam', 'From this charming accommodation located in the ''Rosse buurt'', you can easily reach popular shops, restaurants and bars. Just an 8-minute walk from the Central Station. Paid parking garage is 10 minutes away.
We are happy to help our guests with their plans and provide them with all the information for a pleasant stay in our beautiful city.

Breakfast included.', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '167 Demo Street, Centrum-West, Amsterdam', 52.37536, 4.8988, ST_SetSRID(ST_MakePoint(4.894848, 52.37913), 4326)::geography, 1, false, 0, 1, 1, 1.0, 164.0, 34.0, 'EUR', '2018-01-01'),
  (6, 8, 'Cosy studio close to the Amstel', 'A cosy and very light appartment, centrally located.
5 minutes walk from the metro/train station. I would love to give you an explanation about the city and recommend the best spots in the area.', 'entire_place'::property_type, 'Amsterdam', 'Oud-Oost', '43 Demo Street, Oud-Oost, Amsterdam', 52.35105, 4.91299, ST_SetSRID(ST_MakePoint(4.910911, 52.352889), 4326)::geography, 2, false, 0, 0, 1, 1.0, 211.0, 34.0, 'EUR', '2018-01-01'),
  (7, 9, 'Stijllvolle familie woning, 3 verdiepingen sauna', 'This unique accommodation has its own style. Completely renovated as new. In the middle of the nicest neighborhood in Amsterdam. Characteristic old factory that has been transformed into a family home. 3 or 4 bedrooms, 2 bathrooms including 1 bath and a sauna. Living room with open kitchen adjacent to the garden. 1 extra living room.', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '34 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36626, 4.86326, ST_SetSRID(ST_MakePoint(4.863475, 52.365367), 4326)::geography, 5, false, 0, 4, 5, 3.5, 889.75, 246.0, 'EUR', '2018-01-01'),
  (8, 10, 'Beautiful loft at Amstelbeach', 'We provide you a wonderfull stay in our great appartment located in the new Amsterdam hotspot called Amstelkwartier.

Sleeping up to 4 guests. 
The rooms are both with a doublebed.
1 French bed/ 1 kingsize bed
 Luxury bathroom and living room.

The appartment is 300 mtr from the city harbor and a beatiful park by the water. 
Evening shop on the corner of the street as well as a mac donalds.

1 min walk to the metro. 2 stops to Amsterdam RAI and in a few minutes you are in the heart of Amsterdam', 'private_room'::property_type, 'Amsterdam', 'Watergraafsmeer', '34 Demo Street, Watergraafsmeer, Amsterdam', 52.33914, 4.91794, ST_SetSRID(ST_MakePoint(4.921355, 52.335211), 4326)::geography, 4, false, 0, 2, 2, 1.5, 341.5, 104.0, 'EUR', '2018-01-01'),
  (9, 11, '85m² Modern Apartment • Jordaan • Leidseplein', 'APARTMENT HIGHLIGHTS: 
★ 2 bedroom apartment 
★ Modern and light
★ 5 single beds and a comfortable sleeping sofa
★ Fully equipped open kitchen 
★ Modern Island Bar 
★ Bathroom with walk-in shower + bathtub
★ Separate toilet
★ Great view
★ Free Wi-fi and TV
★ Superb location, downtown and close to everything!
★ Linen and Towels provided 
★ Located in the heart of Amsterdam', 'entire_place'::property_type, 'Amsterdam', 'Centrum-West', '36 Demo Street, Centrum-West, Amsterdam', 52.36600112915039, 4.87976598739624, ST_SetSRID(ST_MakePoint(4.877512, 52.367485), 4326)::geography, 6, false, 0, 2, 6, 1.0, 465.0, 58.0, 'EUR', '2018-01-01'),
  (10, 12, 'great family house only suitable for fam with kids', '* Our house is only suitable for families with children (up to 3 or 4) and not for adults groups *', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '167 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.3606, 4.85739, ST_SetSRID(ST_MakePoint(4.857634, 52.363401), 4326)::geography, 4, false, 0, 4, 5, 2.0, 513.67, 70.0, 'EUR', '2018-01-01'),
  (11, 13, 'Unique! Whole private new houseboat. Families kids', 'Please first write us a message to confirm the houserules and a description of the family before making a bookings request. 

This houseboat is unique to rent. Whole houseboat to stay (maximum of 30 days a year, only to rent a few days in April, May and June). Bright, safe, big floating house boat. Please confirm the houserules before making a request! We are welcoming families with or without kids, retirees like me and my wife, couples, business people, but everyone nonsmoking please.', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '36 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36559, 4.87184, ST_SetSRID(ST_MakePoint(4.870177, 52.366927), 4326)::geography, 4, true, 2, 2, 4, 1.5, 819.0, 172.0, 'EUR', '2018-01-01'),
  (12, 14, 'Amsterdam oost Privat room', 'The appartment is located in the east side of Amsterdam. Its a nice area with a lot of shops, restaurants, bars, Park, outdoor swimming pool, Zoo and more... in 2024 the whole appartement was renovated with floor heatning and fishbone pfc.', 'private_room'::property_type, 'Amsterdam', 'Oostelijk Havengebied - Indische Buurt', '142 Demo Street, Oostelijk Havengebied - Indische Buurt, Amsterdam', 52.36307, 4.9367, ST_SetSRID(ST_MakePoint(4.938266, 52.364704), 4326)::geography, 2, false, 0, 1, 1, 1.0, 125.0, 17.0, 'EUR', '2018-01-01'),
  (13, 15, 'Luxery apartment with terrace by canal', 'The space
The apartment is very light and fully furnished and has everything you need.
In the building is a private parking place.

Registration Details
0363 031D 2696 9F6F D528', 'entire_place'::property_type, 'Amsterdam', 'Bos en Lommer', '78 Demo Street, Bos en Lommer, Amsterdam', 52.37558, 4.83907, ST_SetSRID(ST_MakePoint(4.833649, 52.373433), 4326)::geography, 2, false, 0, 1, 1, 1.5, 299.67, 82.0, 'EUR', '2018-01-01'),
  (14, 16, 'Prachtige woning met tuin in Amsterdam', 'In this centrally located ground floor accommodation, everything for your family is within reach. 
There are 3 bedrooms:
- 1 king size (2 persons)
- 1 person adult size single bed in the kids room
- 1 bunk bed with 2 adult size single beds

TV, WiFi, Netflix available. Beautiful garden.
Bathroom with bath, toilet and separate shower. 

Dining area with children''s chairs available, kitchen with cooking island.
Separate toilet available. RAI around the corner & tram 20 meters from here! City center easily accessible by tram next door', 'entire_place'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '99 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.34284, 4.90037, ST_SetSRID(ST_MakePoint(4.906495, 52.343091), 4326)::geography, 4, false, 0, 4, 4, 1.5, 665.0, 197.0, 'EUR', '2018-01-01'),
  (15, 17, 'B&B Reijgershof - The Barok lounge', 'Welcome to Guesthouse Reijgershof 🌿

Guesthouse Reijgershof is a charming retreat with 5 private suites, each featuring its own bathroom and access to the large garden. Located on the edge of Amsterdam, this accommodation combines the peace of nature with the vibrant energy of the city. Whether for one night or a longer stay, it’s the perfect place where both body and mind can come to rest.', 'private_room'::property_type, 'Amsterdam', 'Gaasperdam - Driemond', '100 Demo Street, Gaasperdam - Driemond, Amsterdam', 52.31026, 5.00069, ST_SetSRID(ST_MakePoint(5.003973, 52.309369), 4326)::geography, 2, false, 0, 1, 1, 1.0, 116.0, 12.0, 'EUR', '2018-01-01'),
  (16, 18, 'Parkview for two', 'This 1888 building is located next to the Sarphatipark, just outside the Singelgracht, so near the old town, close to the river Amstel and within walking distance of the major museums. It is a nice neighborhood, where there is a lot of living, working, shopping, with restaurants and cafes and a daily market around the corner. Almost everything is within walking distance, but also well connected by public transportation.', 'private_room'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '19 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.35506, 4.89888, ST_SetSRID(ST_MakePoint(4.898544, 52.357643), 4326)::geography, 2, false, 0, 1, 1, 1.0, 205.5, 29.0, 'EUR', '2018-01-01'),
  (17, 19, 'Zeeburg Apartment', 'Stylish and bright apartment with unobstructed views over old historic warehouses. Recently renovated and decorated with a mix of Scandinavia, modern elements, lots of green and design. The open kitchen and living room form an inviting living space. Apartment has three bedrooms and is very efficiently furnished. In short, an ideal base to explore Amsterdam with or without children/dog.

Ideal for dogs: next to the apartment is a 500m off-leash area!', 'entire_place'::property_type, 'Amsterdam', 'Oostelijk Havengebied - Indische Buurt', '102 Demo Street, Oostelijk Havengebied - Indische Buurt, Amsterdam', 52.36857819999999, 4.9405903, ST_SetSRID(ST_MakePoint(4.938404, 52.372574), 4326)::geography, 4, true, 2, 3, 3, 1.0, 301.33, 0.0, 'EUR', '2018-01-01'),
  (18, 20, 'Private Studio on Houseboat Center Amsterdam', 'PRIVATE "OWN ENTRANCE" SUITE ON OUR BOAT. BEST way to experience the true feeling of Amsterdam is on a houseboat. We invite you to our home to see what we love most about this city. Decorated with detail to design and a romantic getaway to enjoy the canals in the best area of the city! Yes we live on main part of boat, your suite is on the front side with own entrance and own-bathroom. Happy to see you but it''s totally private to you - if you prefer you probably won''t even see or notice us ;)', 'entire_place'::property_type, 'Amsterdam', 'Centrum-West', '72 Demo Street, Centrum-West, Amsterdam', 52.37605, 4.88328, ST_SetSRID(ST_MakePoint(4.880196, 52.373942), 4326)::geography, 2, false, 0, 1, 1, 1.0, 208.0, 25.0, 'EUR', '2018-01-01'),
  (19, 21, 'Maria Centre Apartement in a quiet location', 'It is wonderful to share a nice place with others. I offer an apartment of 28 m2 on the first floor in my cozy house in the centre of Amsterdam. It is located in a quiet street very near (at least 1 km) to the beautiful museums of Amsterdam: Rijksmuseum , Van Gogh Stedelijk museum and the Hermitage. Anne Frankhuis is 15 minutes walk. The canals around the corner. The neighborhood is full of restaurants, pubs, shops and the Albert Cuyp market. The apartmentl is near to public transport.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-Oost', '175 Demo Street, Centrum-Oost, Amsterdam', 52.35937, 4.89266, ST_SetSRID(ST_MakePoint(4.888174, 52.360979), 4326)::geography, 2, false, 0, 1, 2, 1.0, 269.67, 53.0, 'EUR', '2018-01-01'),
  (20, 22, 'Bright room for families and friends in A''dam 3', 'You can stay in this PRIVATE room by yourself or with your friends and family. When you book this room, you have the room for yourself, with private shower and toilet. We are an education center in Amsterdam-East. When you stay with us, you do not only get a comfortable, private room for an affordable price in Amsterdam, but also support a progressive institute organizing trainings on topics such as global justice, feminism, and LGBTQI liberation. No AC in the room.', 'private_room'::property_type, 'Amsterdam', 'Oostelijk Havengebied - Indische Buurt', '157 Demo Street, Oostelijk Havengebied - Indische Buurt, Amsterdam', 52.36413, 4.9374, ST_SetSRID(ST_MakePoint(4.942003, 52.367279), 4326)::geography, 4, false, 0, 1, 4, 1.0, 92.0, 0.0, 'EUR', '2018-01-01'),
  (21, 23, 'Adam''s Suite', 'Located in the heart of Amsterdam and just around the corner from the famous Prinsengracht Canal, you will find a lovely B&B called Adam''s Suite.', 'private_room'::property_type, 'Amsterdam', 'Centrum-Oost', '128 Demo Street, Centrum-Oost, Amsterdam', 52.35943, 4.89156, ST_SetSRID(ST_MakePoint(4.891722, 52.360818), 4326)::geography, 2, false, 0, 1, 2, 1.0, 191.0, 0.0, 'EUR', '2018-01-01'),
  (22, 24, 'Cozy & quiet 2-bedroom apartment', 'Enjoy your stay in Amsterdam in a different way, staying in this newly and beautifully renovated 2-bedroom apartment (60m²) in Amsterdam (Zuidoost). Just a 10-minute walk from Gaasperplas metro station and 5-minute walk from Gaasperpark, a lovely park for runners and swimmers (in the summer). This apartment is located in a residential area, very green, safe and peaceful, just a 10-min car/Uber ride to the buzzy areas of Amsterdam. Ideal for singles, couples or small families (max. 4 persons).', 'entire_place'::property_type, 'Amsterdam', 'Gaasperdam - Driemond', '31 Demo Street, Gaasperdam - Driemond, Amsterdam', 52.30659, 4.97395, ST_SetSRID(ST_MakePoint(4.969755, 52.309106), 4326)::geography, 3, false, 0, 1, 1, 1.0, 270.0, 52.0, 'EUR', '2018-01-01'),
  (23, 25, 'Entire ground floor apartment - De Pijp', 'Welcome to this modern 70m² ground-floor apartment in the vibrant De Pijp district. With a private entrance and a spacious garden, this newly renovated one-bedroom offers comfort and style.

Explore iconic landmarks nearby, including the Albert Cuyp Market, Heineken Experience, and Rijksmuseum. Though centrally located, the apartment is on a quiet street.

Excellent transport links provide easy access to Amsterdam Centrum, Haarlem, and Schiphol Airport, just 15 minutes away by car.', 'entire_place'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '128 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.3492767, 4.8961005, ST_SetSRID(ST_MakePoint(4.890924, 52.346214), 4326)::geography, 2, false, 0, 1, 1, 1.0, 347.67, 58.0, 'EUR', '2018-01-01'),
  (24, 26, 'Boutique-5 min to center-fast WIFI', 'Stay in the heart of De Pijp, Amsterdam''s most vibrant and much-loved neighbourhood. Enjoy a stylish double bedroom with a private en-suite bathroom in a lovely 1920s Amsterdam home. Just a short walk to the canals, Museumplein, the Heineken Experience and the famous Albert Cuyp Market. Easy self check-in, fast Wi-Fi and hosted by experienced Superhosts with 700+ excellent reviews.', 'private_room'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '30 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.35068, 4.89284, ST_SetSRID(ST_MakePoint(4.89191, 52.349546), 4326)::geography, 2, false, 0, 1, 1, 1.0, 125.0, 20.0, 'EUR', '2018-01-01'),
  (25, 27, 'Jolly Horses', 'This apartment has a spacious living room, fully equipped kitchen and 1 bedroom! Located in walking distance from CENTRAL STATION! The apartment is situated on the third floor, the firts flight off stairs is very steep!!! ,and overlooks the city.', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '39 Demo Street, Centrum-West, Amsterdam', 52.38113, 4.89171, ST_SetSRID(ST_MakePoint(4.893024, 52.380432), 4326)::geography, 4, true, 2, 1, 1, 1.0, 237.5, 24.0, 'EUR', '2018-01-01'),
  (26, 28, 'Sunny 65m2 Loft - Superb Canal View - Jordaan Area', 'Experience serenity in my exquisite 65 m2 corner loft on the elegant Herengracht.

Sunlight streams through 7 big windows and give incredible views on the canal and a beyond spacious feeling. The sounds coming from the water are mesmerizing. The atmosphere is quiet and inspirational.

Just a 5 min walk to Dam Square, Anne Frank’s House and the famous 9 Straatjes, plus a 10 min walk to Central Station. 

Amsterdam''s essence awaits.
This is the absolute perfect location to enjoy this vibrant city.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-West', '64 Demo Street, Centrum-West, Amsterdam', 52.37468, 4.88993, ST_SetSRID(ST_MakePoint(4.895193, 52.375199), 4326)::geography, 2, false, 0, 1, 1, 1.0, 394.0, 110.0, 'EUR', '2018-01-01'),
  (27, 29, 'Woning in Amsterdam noord met tuin', 'Entire house in Amsterdam Noord, 1 minute walk from the Noorderpark and the Noorderpark swimming pool. Within 5 minutes by bike, you are on the ferry, or you can take the metro, which is a 15-minute walk away. This will take you to the center of Amsterdam in 20 minutes. 

In addition, it is 7 minutes by bike from NDSM wharf, and there are nice restaurants and bars nearby. For nice tips, just send a message. Often, it is advisable to book in advance.', 'entire_place'::property_type, 'Amsterdam', 'Oud-Noord', '133 Demo Street, Oud-Noord, Amsterdam', 52.39749, 4.91789, ST_SetSRID(ST_MakePoint(4.924016, 52.399268), 4326)::geography, 2, true, 2, 1, 1, 1.5, 226.0, 51.0, 'EUR', '2018-01-01'),
  (28, 30, 'Orginal dutch houseboat city center ''ZIJ''', 'Charming Houseboat in Central Amsterdam – An Unforgettable Waterfront Escape

Step aboard your delightful floating hideaway, right in the heart of Amsterdam. This cozy houseboat offers a truly unique experience—think of it as glamping on the water. Enjoy the perfect mix of comfort and adventure, where peaceful moments on deck meet the lively buzz of the city just around the corner. Whether you''re starting your day with a coffee in the morning sun or winding down after exploring the canals.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-West', '95 Demo Street, Centrum-West, Amsterdam', 52.38426699999999, 4.894558, ST_SetSRID(ST_MakePoint(4.89509, 52.383103), 4326)::geography, 3, false, 0, 1, 3, 1.0, 147.0, 26.0, 'EUR', '2018-01-01'),
  (29, 31, 'The Wikkel | Iconisch Field Cabin', 'The most famous tiny house in the Netherlands. Spacious at 45 m², cozy, and unmistakable with its sloping roof and wooden interior. The large windows at both the front and back, leading to two private decks with lounge chairs, flood the house with natural daylight. In this cabin, you can fully enjoy the sun with friends and family. In addition to a queen-size bed in the master bedroom or a sofa bed in the living room. If you prefer a bunk bed, you can request this based on availability.', 'entire_place'::property_type, 'Amsterdam', 'Geuzenveld - Slotermeer', '51 Demo Street, Geuzenveld - Slotermeer, Amsterdam', 52.3814, 4.77799, ST_SetSRID(ST_MakePoint(4.773658, 52.381778), 4326)::geography, 4, true, 2, 1, 2, 0.0, 212.0, 53.0, 'EUR', '2018-01-01'),
  (30, 32, 'New private bathroom and garden 15 min city center', 'Newly renovated place located in Amsterdam with private ensuite bathroom. There''s direct access to a shared garden. Metro station Ganzenhoef is on 5 min walking distance from the house and will take you in 15 min to the city center. The space contains a queen sized bed, table/desk with two chairs, lockable entrance door, an electric heating system, watercooker and other amenities needed for a great short stay. Also access to a shared area with fridge/freezer, sink, dishes and silverware.', 'private_room'::property_type, 'Amsterdam', 'Bijlmer-Oost', '89 Demo Street, Bijlmer-Oost, Amsterdam', 52.32526, 4.98081, ST_SetSRID(ST_MakePoint(4.984668, 52.325513), 4326)::geography, 2, false, 0, 1, 1, 1.0, 73.04, 0.0, 'EUR', '2018-01-01'),
  (31, 33, '3 bedroom design apartment in Rivierenbuurt', 'Design 3BR Oasis in Rivierenbuurt | Expats & Families

Welcome to our stylish, high-design Amsterdam home! Recently renovated and fully equipped, this quiet ground-floor apartment is ideal for relocating expats and families.

3 bedrooms, 2 full baths & dedicated workspace

Spacious living kitchen & sleek lounge

Kid-friendly with plenty of toys

Tucked in chic Rivierenbuurt, near De Pijp, RAI & Amstel River

Quiet street steps from cafés, shops & quick transit links', 'entire_place'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '79 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.34256, 4.9087, ST_SetSRID(ST_MakePoint(4.904363, 52.34446), 4326)::geography, 6, false, 0, 3, 2, 2.0, 221.87, 0.0, 'EUR', '2018-01-01'),
  (32, 34, 'Cozy & large bohemian style room', 'Cozy spacious room in a beautiful and spiritually decorated apartment. The room is situated on the 3rd floor of a traditional Amsterdam brick building built in the early 20th century. The apartment is shared with the two hosts.', 'private_room'::property_type, 'Amsterdam', 'Oud-Oost', '12 Demo Street, Oud-Oost, Amsterdam', 52.35143, 4.91272, ST_SetSRID(ST_MakePoint(4.914988, 52.351167), 4326)::geography, 2, false, 0, 1, 1, 1.0, 161.0, 55.0, 'EUR', '2018-01-01'),
  (33, 35, 'Cozy apartment in Amsterdam Zuid (near Vondelpark)', 'A 2 bedroom apartment with a spacious balcony, situated near the renowned Vondelpark. This apartment features one master bedroom and a second bedroom with a dedicated working space with a standing desk. The kitchen is modern and fully equipped. One of the highlights of this apartment is the delightful balcony. 
The apartment is conveniently situated within reach of public transportation options. A range of shops, restaurants, cafes, and entertainment venues are just a short walk away.', 'entire_place'::property_type, 'Amsterdam', 'Zuid', '25 Demo Street, Zuid, Amsterdam', 52.35128, 4.85133, ST_SetSRID(ST_MakePoint(4.854993, 52.355069), 4326)::geography, 4, false, 0, 2, 2, 1.0, 364.0, 70.0, 'EUR', '2018-01-01'),
  (34, 36, 'Beautiful room with max privacy in heart of A''dam', 'Recently renovated private room in the heart of Amsterdam. Completely sheltered from street noise, with a small but luxurious private bathroom with an amazing shower. Maximum privacy since the room has its own entrance.

The room is located on the first floor of an historic Amsterdam Canal House.

The location really is as central as it gets. Walking distances:
- 2 minutes from city centre Dam Square
- 3 minutes from main shopping streets
- 10 minutes from Central Station', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '67 Demo Street, Centrum-West, Amsterdam', 52.372257232666016, 4.896886825561523, ST_SetSRID(ST_MakePoint(4.904008, 52.372619), 4326)::geography, 2, false, 0, 1, 1, 1.0, 160.0, 33.0, 'EUR', '2018-01-01'),
  (35, 37, '★★★★ CANAL APARTMENT | AMSTERDAM CENTRAL | 4P ★★★★', 'This type of extraordinary accomodation, in this amazing neighborhood, is rarely available! A nicely designed 7 stylish apartment. 

Warm & cosy with a chique look. 

Experience the joy of the center of Amsterdam and the liveliness of this famous historic neighborhood, while enjoying the tranquility of living in a historic apartment which recently has been fully renovated to a beautiful and luxurious short-stay. 

All amenities are included, so all you need to do is bring your suitcase!', 'private_room'::property_type, 'Amsterdam', 'Centrum-Oost', '52 Demo Street, Centrum-Oost, Amsterdam', 52.36397, 4.91033, ST_SetSRID(ST_MakePoint(4.914443, 52.36423), 4326)::geography, 4, false, 0, 1, 2, 1.0, 364.81, 66.0, 'EUR', '2018-01-01'),
  (36, 38, 'Historic Canal House | 17th Century | 2 King Beds', 'Experience Amsterdam from an authentic 17th-century canal house, fully air-conditioned and ideally located on the historic Geldersekade. Beautifully restored with modern comforts, the apartment offers two king-size bedrooms, a stylish bathroom, a fully equipped pantry and a cozy dining area. Just steps from Nieuwmarkt, Central Station, canals, museums, cafés and restaurants. Perfect for couples, friends and families of up to four guests.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-Oost', '105 Demo Street, Centrum-Oost, Amsterdam', 52.3738602, 4.9015618, ST_SetSRID(ST_MakePoint(4.902078, 52.372405), 4326)::geography, 4, false, 0, 2, 2, 1.0, 498.0, 0.0, 'EUR', '2018-01-01'),
  (37, 39, 'Spacious Apartment in Amsterdam with Park View', 'Very spacious apartment in the heart of Rembrandtpark. With a big living room, fully equipped kitchen, work room and two bedrooms, you have everything you need to enjoy a beautiful stay in Amsterdam. It features one queen bed, two single beds that are stacked, that can also be combined to make a second twin bed, and a 1.5 sofa bed. You can enjoy the amazing view from every room, or dive into the fresh air at the balcony.', 'entire_place'::property_type, 'Amsterdam', 'Slotervaart', '176 Demo Street, Slotervaart, Amsterdam', 52.36169, 4.84447, ST_SetSRID(ST_MakePoint(4.84629, 52.362419), 4326)::geography, 6, false, 0, 3, 4, 1.5, 620.0, 103.0, 'EUR', '2018-01-01'),
  (38, 40, 'Great apartment in Amsterdam', 'Hi all,

I am David and I own a nice studio in Amsterdam. It''s an apartment near the city center. I live in this apartment when You''re not renting it!', 'entire_place'::property_type, 'Amsterdam', 'Bos en Lommer', '92 Demo Street, Bos en Lommer, Amsterdam', 52.37634, 4.84358, ST_SetSRID(ST_MakePoint(4.845588, 52.376354), 4326)::geography, 4, false, 0, 1, 1, 1.0, 191.0, 35.0, 'EUR', '2018-01-01'),
  (39, 41, 'The Keizersgracht Hideaway', 'Enjoy a stylish stay in this beautifully renovated apartment on the iconic Keizersgracht.

This luxurious 48m² apartment offers stunning canal views and combines modern comfort with historic charm. Located on the second floor (two flights of stairs), it provides a peaceful yet central base for your Amsterdam getaway.

Perfect for a relaxing and unforgettable city trip, just minutes from Amsterdam’s top attractions.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-Oost', '141 Demo Street, Centrum-Oost, Amsterdam', 52.36468, 4.89985, ST_SetSRID(ST_MakePoint(4.900989, 52.362434), 4326)::geography, 2, false, 0, 1, 1, 1.5, 522.6, 0.0, 'EUR', '2018-01-01'),
  (40, 42, 'Suite 7 - Big sunny studio in ''de Pijp'', Amsterdam', 'This spacious and sunny studio with private access is located on the 4th floor (no elevator) of our 19th century building in trendy and lively neighborhood de Pijp. Walking distance to the city center and the famous Van Gogh and Rijks museum. The lovely Sarphatipark, the coziest bars and restaurants of Amsterdam, public transport or rent-a-bike, just around the corner. 
High-speed wifi, central heating, a kitchen dresser with fridge and Nespresso machine and private bathroom all for you!', 'private_room'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '34 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.355644, 4.89889, ST_SetSRID(ST_MakePoint(4.898195, 52.359503), 4326)::geography, 2, false, 0, 1, 1, 1.0, 190.2, 0.0, 'EUR', '2018-01-01'),
  (41, 43, 'Cozy Leidseplein Apartment-Vondelpark, Museumplein', 'Experience Amsterdam''s vibrant heart at this Leidseplein apartment. Just a 5-minute walk from Vondelpark, Museum Plein, Canals this charming residence offers a beautifully designed living space, fully equipped kitchen, cozy bedroom, sleek bathroom and comfortable spot for your romantic getaway. Immerse yourself in the city''s cultural attractions, museums, architecture and nightlife from this prime location. Your dream Amsterdam lifestyle starts here.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-Oost', '20 Demo Street, Centrum-Oost, Amsterdam', 52.36286336572783, 4.887088425457478, ST_SetSRID(ST_MakePoint(4.891978, 52.362698), 4326)::geography, 2, false, 0, 0, 3, 1.0, 160.79, 42.0, 'EUR', '2018-01-01'),
  (42, 44, 'Luxe Apartment Next to RAI Centre & City Park', 'Escape to tranquility in this spacious 67m² apartment, just a short stroll from the city center. Located in the charming ‘Rivierenbuurt,’ it offers easy access to the beautiful Beatrixpark. Enjoy a brand-new modern kitchen, a luxurious king-size bed, and the convenience of the RAI conference center just a 2-minute walk away.

Registration number: -0363 9941 9DE3 BEDB 3192
Z/26/3093745', 'entire_place'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '32 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.3458463, 4.8877519, ST_SetSRID(ST_MakePoint(4.881735, 52.347272), 4326)::geography, 2, false, 0, 1, 1, 1.0, 394.67, 0.0, 'EUR', '2018-01-01'),
  (43, 45, 'Complete house with garden in Amsterdam - De Pijp', 'Bright, recently renovated 76m2 apartment with a sunny 42m2 garden in De Pijp/Oud-Zuid. Spacious kitchen and living area with doors opening to a garden with dining table, BBQ and lounge. Bedroom with king-size bed and separate office/guest room with sofa bed. Modern bathroom, separate toilet, and two separate sleeping areas. Quiet street in vibrant Amsterdam.', 'entire_place'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '45 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.34897, 4.88751, ST_SetSRID(ST_MakePoint(4.886009, 52.348561), 4326)::geography, 2, true, 2, 2, 2, 1.0, 559.0, 111.0, 'EUR', '2018-01-01'),
  (44, 46, 'Cozy Apartment in Amsterdam West', 'Cozy 1bedroom apartment in the West side of Amsterdam, 15min walking to the city center. Located on the first floor of a lively street during day time, full of shops, market, and everything you might need. But quiet and cozy at night. Furnished with a comfy bed and a small desk facing the backside of the building which makes it very quiet, a big couch and tv, spacious kitchen fully supplied, bathroom with a bath-tub and a small balcony.', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '76 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36584855939976, 4.866429381072521, ST_SetSRID(ST_MakePoint(4.871542, 52.365931), 4326)::geography, 2, false, 0, 1, 1, 1.0, 196.0, 21.0, 'EUR', '2018-01-01'),
  (45, 47, 'Bright, Stylish, Cozy Familyhouse 4 p, 3BR', 'Beautiful 3-story house in an old town house just outside the center of Amsterdam. Recently renovated with wooden floors, a spacious bathroom, two toilets and a modern kitchen. Stunning Roof Terrace on both the first floor and the third floor. This place is great for a family with children.', 'entire_place'::property_type, 'Amsterdam', 'Watergraafsmeer', '135 Demo Street, Watergraafsmeer, Amsterdam', 52.35339, 4.93679, ST_SetSRID(ST_MakePoint(4.935037, 52.354599), 4326)::geography, 4, false, 0, 3, 5, 1.5, 399.0, 54.0, 'EUR', '2018-01-01'),
  (46, 48, 'Comfortable 2 floor apartment in a popular area', 'Apartment of two floors in a popular, but peaceful area of Amsterdam with tons of great restaurants, bars, shops and market. City centre is just 10-15 minutes away by public transport or bike. Metrostation wibautstraat is 7 min walking distance from the apartment. Train station Amstel is 10-15 min walking. Clean, comfortable, lovely house!', 'entire_place'::property_type, 'Amsterdam', 'Oud-Oost', '145 Demo Street, Oud-Oost, Amsterdam', 52.35295, 4.91879, ST_SetSRID(ST_MakePoint(4.919239, 52.350108), 4326)::geography, 4, false, 0, 2, 2, 1.5, 287.67, 55.0, 'EUR', '2018-01-01'),
  (47, 49, 'Large bright apt w. roofterrace', 'This tastfully furnished 2- bedroom (115 sq. m) loft has everything you need. It offers a lot of privacy and is very spacious. Enjoy the fully equipt kitchen, the large roofterrace and the great area in which this apt is located.', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '121 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36876, 4.86759, ST_SetSRID(ST_MakePoint(4.873715, 52.368024), 4326)::geography, 4, false, 0, 2, 3, 2.0, 485.0, 52.0, 'EUR', '2018-01-01'),
  (48, 50, 'Stylish ground floor apartment at the Sarphatipark', 'This unique and stylish house right at the Sarphatipark is a little paradise in the middle of Amsterdam! Our house is extremely quiet, as well as in our bedrooms! The house is spacious (approx. 100 m2) and has a living room, dining room, kitchen, study, a bathroom, toilet and 2 bedrooms. Our house has a very quiet garden with a lot of privacy. It''s the ideal base for exploring Amsterdam.', 'entire_place'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '15 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.35406907029892, 4.89388541957398, ST_SetSRID(ST_MakePoint(4.893278, 52.352344), 4326)::geography, 3, true, 2, 2, 2, 1.5, 444.5, 0.0, 'EUR', '2018-01-01'),
  (49, 51, 'Private studio on houseboat, Amsterdam main canal', 'Clara is solely responsible for offering this listing on Airbnb, and they host as a business. For more legal information, visit our Help Center.

Business name: Prinsenboat
Business registry: Dutch Business Register of the Dutch Chamber of Commerce
KVK number: 68847491
Email: prinsenboat@protonmail.com
Phone: +31 6 27314424
Address: Prinsengracht 816F, 1017 JL Amsterdam, Netherlands
To help protect yourself from fraud, always use Airbnb to send money and communicate with hosts.', 'private_room'::property_type, 'Amsterdam', 'Centrum-Oost', '82 Demo Street, Centrum-Oost, Amsterdam', 52.36199951171875, 4.89964485168457, ST_SetSRID(ST_MakePoint(4.902129, 52.362128), 4326)::geography, 4, false, 0, 1, 2, 1.0, 276.0, 96.0, 'EUR', '2018-01-01'),
  (50, 52, 'Cool and Spaceous Quiet Canal Apartment', 'Large apartment in the hip area of Oud West with its boutique shops and abundance of bars and restaurants. Near the Vondelpark and close to city center.', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '145 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36162, 4.8592, ST_SetSRID(ST_MakePoint(4.85739, 52.364852), 4326)::geography, 2, false, 0, 1, 1, 1.0, 148.0, 0.0, 'EUR', '2018-01-01')
) AS v(id, host_id, title, description, property_type, city, neighborhood, address, latitude,
  longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds, bathrooms,
  price_per_night, cleaning_fee, currency, created_at)
JOIN cities c ON c.name = v.city;

INSERT INTO listings (id, host_id, title, description, property_type, city_id, neighborhood, address,
  latitude, longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds,
  bathrooms, price_per_night, cleaning_fee, currency, created_at)
OVERRIDING SYSTEM VALUE
SELECT v.id, v.host_id, v.title, v.description, v.property_type, c.id, v.neighborhood, v.address,
  v.latitude, v.longitude, v.public_location, v.max_guests, v.pets_allowed, v.max_pets, v.bedrooms,
  v.beds, v.bathrooms, v.price_per_night, v.cleaning_fee, v.currency, v.created_at::timestamptz
FROM (VALUES
  (51, 53, 'Spacious city suite', 'One of the city’s most sustainable hotels, our family-run home base features a unique zero-emission heating and cooling system, so your stay is as climate-friendly as possible. We offer 24/7 reception, luggage storage, concierge services, and an optional paid breakfast. And our convenient location in the center of Amsterdam puts you near the canals, world-famous museums, shopping, dining, and nightlife.', 'private_room'::property_type, 'Amsterdam', 'Centrum-Oost', '57 Demo Street, Centrum-Oost, Amsterdam', 52.36579, 4.8934, ST_SetSRID(ST_MakePoint(4.89539, 52.365923), 4326)::geography, 2, false, 0, 1, 1, 1.0, 271.9, 61.0, 'EUR', '2018-01-01'),
  (52, 54, 'Cozy apartment in Amsterdam', 'Cozy and renovated apartment in Amsterdam - Zeeburg.
The apartment is fully equipped and is located in a quiet neighborhood in East.
The Flevopark is 1 minute away where you can take wonderful walks. On the other side of the street you will find the pleasant Javaplein, followed by Javastraat. Here you will find a wide range of shops and restaurants.', 'entire_place'::property_type, 'Amsterdam', 'Oostelijk Havengebied - Indische Buurt', '83 Demo Street, Oostelijk Havengebied - Indische Buurt, Amsterdam', 52.36423, 4.94226, ST_SetSRID(ST_MakePoint(4.940069, 52.363948), 4326)::geography, 2, false, 0, 1, 1, 1.0, 210.0, 32.0, 'EUR', '2018-01-01'),
  (53, 55, 'Cosy room with double bed & lounge (apt shared)', 'Upon arrival you find a cute Bohemian place & room with a high double bed and or a lovely lounge couch or a double floor bed underneath. You can use our garden, kitchen, shower & bicycles for free. No weird house rules,. Private rooms, no locks, rest happily shared with us. You might meet other guests.

If you are 4 people you can use the extra bedroom, fee 49€ p/n. If you are 2 or 3 people the fee is higher. 

Smoking (weed) is not allowed in/near the apartment.

Read the reviews!', 'private_room'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '170 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.34392, 4.89207, ST_SetSRID(ST_MakePoint(4.897149, 52.340872), 4326)::geography, 4, false, 0, 2, 4, 1.0, 97.0, 31.0, 'EUR', '2018-01-01'),
  (54, 56, 'Triple room', 'We’re an eco-forward boutique hotel operating on renewable energy, and a commitment to sustainability. Yara Hotel Yara offers minimalist, modern design, comfortable Royal Dutch Auping beds, and in-room yoga mats and hula hoops. If you’re planning a night in, you can pick up vegetarian grab-and-go meals and boardgames in the lobby. Our central location is an easy tram and bus ride from the airport, and you can take a tram from Amsterdam Central Station.', 'private_room'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '164 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.35778, 4.85655, ST_SetSRID(ST_MakePoint(4.858783, 52.354524), 4326)::geography, 3, false, 0, 1, 1, 1.0, 100.5, 35.0, 'EUR', '2018-01-01'),
  (55, 57, 'Jacuzzi boutique suite | center', 'Stay in a 5-star hotel, but with personal service and a super small-scale approach! You''re in the center of Amsterdam with all major attractions within walking distance. 100''s of restaurants, bars, coffeeshops and shops within 5 minutes! The room is equipped with an iPad for atmospheric lighting, an Ultra-HD TV with streaming channels and unlimited coffee and tea. There is a laundry service and a kitchenette (on request). Join us and guests in the lobby of the living room downstairs for a drink!', 'entire_place'::property_type, 'Amsterdam', 'Centrum-Oost', '92 Demo Street, Centrum-Oost, Amsterdam', 52.36455, 4.88257, ST_SetSRID(ST_MakePoint(4.878176, 52.361457), 4326)::geography, 2, true, 2, 1, 1, 1.0, 275.72, 66.0, 'EUR', '2018-01-01'),
  (56, 58, 'Design room in Canal District (historic center)', 'Hello and welcome to my comfortable hide out in the heart of Amsterdam''s lively old center, the Jordaan! The 15 minute walk from Central Station is already a great way to get acquainted with the historical center: majestic canals, surrounded with the traditional 16th century ''gentlemen''s houses'' + cozy little shops, café''s... From the elevated lounge area of my split-level apartment you look right down into the street, enabling you to enjoy your new neighborhood along with a warm cup of tea. :)', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '180 Demo Street, Centrum-West, Amsterdam', 52.381, 4.88677, ST_SetSRID(ST_MakePoint(4.886798, 52.382537), 4326)::geography, 2, false, 0, 1, 1, 1.0, 194.0, 34.0, 'EUR', '2018-01-01'),
  (57, 59, '! Great Room in best part of Ams (shared Bathroom)', 'DistributionAdvice is solely responsible for offering this listing on Airbnb, and they host as a business. For more legal information, visit our Help Center.

Business name: DistributionAdvice
Business registry: Crossroads Bank for Enterprises (CBE)
Enterprise registration number: 0474180540
Email: thierry.bouffioux@gmail.com
Phone: +31 6 28905567
Address: Gisseleire Versélaan, 1082, Sint-Agatha-Berchem, Belgium
To help protect yourself from fraud, always use Airbnb to send money and communicate with hosts.', 'private_room'::property_type, 'Amsterdam', 'Zuid', '157 Demo Street, Zuid, Amsterdam', 52.34527, 4.86177, ST_SetSRID(ST_MakePoint(4.858653, 52.346007), 4326)::geography, 2, false, 0, 1, 1, 1.0, 138.75, 0.0, 'EUR', '2018-01-01'),
  (58, 60, 'Numa | Medium Duplex Studio with Kitchen', 'This comfortable duplex studio offers 29 sqm of space. Ideal for up to two people, its double bed (160x200) and modern bathroom with shower make this stay a perfect way to experience Clara. There’s also a kitchen, a sofa, and a dining table, so you’ll have everything you need for maximum comfort and minimal stress.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-Oost', '82 Demo Street, Centrum-Oost, Amsterdam', 52.3717131, 4.9097795, ST_SetSRID(ST_MakePoint(4.915621, 52.371983), 4326)::geography, 2, false, 0, 1, 1, 1.0, 167.0, 0.0, 'EUR', '2018-01-01'),
  (59, 61, 'Light & spacious apartment near Jordaan/center', 'Completely renovated apartment in the trendy and upcoming neighbourhood Spaarndammerbuurt. With the Westerpark around the corner and a five minute walk from the Jordaan. The apartment is suitable for 2 people, also with a baby/toddler', 'entire_place'::property_type, 'Amsterdam', 'Westerpark', '90 Demo Street, Westerpark, Amsterdam', 52.38724, 4.88051, ST_SetSRID(ST_MakePoint(4.877974, 52.386663), 4326)::geography, 2, false, 0, 1, 1, 1.5, 285.5, 0.0, 'EUR', '2018-01-01'),
  (60, 62, 'Apartment in former Bathhouse. Two bedroom ensuite', 'Private apartment with two big bedrooms with king size beds and private bathroom each. In between the rooms is a living room. Situated in a former public bathhouse in the Northern part of Amsterdam. Close to the NDSM wharf area. The city center is easy accessible by public transport with bus 39/metro 52 (15min) or by bike and ferry (we offer them for rent).
We are looking forward to welcome you in our unique place', 'entire_place'::property_type, 'Amsterdam', 'Noord-West', '97 Demo Street, Noord-West, Amsterdam', 52.41244888305664, 4.88678503036499, ST_SetSRID(ST_MakePoint(4.888046, 52.411166), 4326)::geography, 4, false, 0, 2, 2, 3.0, 328.2, 67.0, 'EUR', '2018-01-01'),
  (61, 63, '284 topLOCATED CANALhouse Room, private bathroom', '284 Supergelegen grachtenpand kamer met privé bath, for solo traveler. Just a 5 mins walk from central station, on Brouwersgracht in famous Jordan area. Single use only room with its own en-suite (in room, private) shower, sink and toilet.

From here you can walk to all main attractions and hotspots.', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '9 Demo Street, Centrum-West, Amsterdam', 52.37988, 4.8942, ST_SetSRID(ST_MakePoint(4.895285, 52.381207), 4326)::geography, 1, false, 0, 1, 1, 1.0, 165.0, 45.0, 'EUR', '2018-01-01'),
  (62, 64, 'Studio Apartment at Wittenberg by Cove', 'Well-appointed and truly beautiful, this neat studio apartment has everything you need to feel at home.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-Oost', '20 Demo Street, Centrum-Oost, Amsterdam', 52.36503982543945, 4.909975051879883, ST_SetSRID(ST_MakePoint(4.911718, 52.363969), 4326)::geography, 2, true, 2, 1, 1, 1.0, 180.71, 0.0, 'EUR', '2018-01-01'),
  (63, 65, 'Central, big window, rear room with private bath.', '🛏️ Rear Room with Private Bathroom

Bright and spacious room in a charming, renovated canal house, overlooking one of Amsterdam’s iconic canals. Features a comfortable king-size bed, private bathroom with shower and toilet, mini fridge, tea and coffee facilities, and free Wi-Fi.

Just a 5-minute walk from Central Station and close to major attractions, cafés, and shops. Ideal for couples, solo travelers, or business guests seeking a comfortable and authentic stay.', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '112 Demo Street, Centrum-West, Amsterdam', 52.37561, 4.9, ST_SetSRID(ST_MakePoint(4.896679, 52.373074), 4326)::geography, 2, false, 0, 1, 1, 1.0, 167.33, 35.0, 'EUR', '2018-01-01'),
  (64, 66, 'Live like a local near Vondelpark, authentic stay', 'My home is a bright and charming ground-floor apartment with its own private garden, located in one of Amsterdam’s most beloved neighbourhoods. Just a short stroll from the Vondelpark and only 10 minutes by tram to the canal district, it’s the perfect base to explore the city while enjoying a relaxed, local vibe.

The area around Hoofddorpplein is truly Amsterdam at its best: a lively mix of young families, creatives, long-time locals, and everything in between.', 'entire_place'::property_type, 'Amsterdam', 'Zuid', '73 Demo Street, Zuid, Amsterdam', 52.35043, 4.84676, ST_SetSRID(ST_MakePoint(4.852498, 52.350093), 4326)::geography, 2, false, 0, 1, 1, 1.0, 185.5, 52.0, 'EUR', '2018-01-01'),
  (65, 67, 'Newly Renovated Peaceful Penthouse', 'We offer an extraordinary experience of comfort and style in the most luxurious neighborhood of the city near the Vondelpark and 10 min from the city center.

This 180m2 residence is newly renovated and fully equiped with all amenities and thoughtfully designed for 2-3 couples or a small family.

Located on a wide and quiet residential street, one wouldn''t expect such a gem when exiting the dedicated elevator. 

This is the ideal place to relax, dine and enjoy after a full day out in the City.', 'entire_place'::property_type, 'Amsterdam', 'Zuid', '170 Demo Street, Zuid, Amsterdam', 52.3498, 4.86873, ST_SetSRID(ST_MakePoint(4.869511, 52.350577), 4326)::geography, 6, false, 0, 3, 3, 3.5, 1147.0, 0.0, 'EUR', '2018-01-01'),
  (66, 68, 'Beautiful first floor apartment in Amsterdam', 'Beautiful apartment in the heart of Amsterdam West! Relax in two cozy bedrooms and a sunny living room, with a contemporary kitchen and a charming balcony. Recently, the bathroom underwent a renovation, complete with floor heating and a pleasant shower. This retreat offers a pleasant place to relax and unwind after a day of discoveries in bustling Amsterdam. Perfectly located, just a 10-minute walk from the food halls and Ten Katemarkt.', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '30 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36604, 4.85308, ST_SetSRID(ST_MakePoint(4.85465, 52.367735), 4326)::geography, 4, false, 0, 2, 2, 1.0, 351.25, 0.0, 'EUR', '2018-01-01'),
  (67, 69, 'Pastory house five', 'Our boutique hotel in Amsterdam West combines historic charm with modern comfort. Set in the beautifully renovated Chassé Church, we offer spacious rooms, each uniquely designed with warm South American-inspired interiors, bamboo floors, and natural elements that create a relaxing atmosphere. Whether you’re here for a romantic weekend, a family getaway, or a short city break, you’ll enjoy thoughtful amenities and a unique setting you’ll love.', 'private_room'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '48 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.3697, 4.86174, ST_SetSRID(ST_MakePoint(4.864218, 52.36806), 4326)::geography, 5, false, 0, 1, 1, 1.0, 89.26, 18.0, 'EUR', '2018-01-01'),
  (68, 70, 'Lovely apt in heart of Amsterdam', 'Stay in Amsterdam''s lively Oud-West neighborhood, just a short walk from the Jordaan, Leidseplein, Vondelpark and Museumplein. This 2nd-floor apartment (45m²) has everything you need for a comfortable stay. Welcome!', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '179 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36794, 4.87251, ST_SetSRID(ST_MakePoint(4.876407, 52.369643), 4326)::geography, 2, false, 0, 1, 1, 1.0, 217.0, 67.0, 'EUR', '2018-01-01'),
  (69, 71, 'Central station mini studio', 'Enjoy easy access to everything from this perfectly located home base. Very central located only 4 min walking from central station and 5 min walking from dam square . Third floor steep stairs', 'entire_place'::property_type, 'Amsterdam', 'Centrum-West', '134 Demo Street, Centrum-West, Amsterdam', 52.37801, 4.89558, ST_SetSRID(ST_MakePoint(4.891599, 52.379569), 4326)::geography, 2, false, 0, 1, 1, 1.0, 107.0, 26.0, 'EUR', '2018-01-01'),
  (70, 72, 'Cozy apartment with canal view in a quiet street', 'We are happy to rent out our apartment. Centrally located and you can discover the entire city by bike, on foot or by public transport. Close to everything there is to see in Amsterdam, but in a quiet street.
From the balcony there is a view of the Admiralengracht. There are several catering establishments within walking distance, but there is also good public transport nearby. 
Perfect for a couple who wants to discover Amsterdam!
We are very flexible so feel free to reach out!', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '9 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.3719827, 4.8568905, ST_SetSRID(ST_MakePoint(4.85578, 52.372951), 4326)::geography, 2, false, 0, 1, 1, 1.0, 258.33, 57.0, 'EUR', '2018-01-01'),
  (71, 73, 'Light Travelin,Private Accommodation Near Van Gogh', 'Stay at a private large, luxurious, cozy apartment at the Museum district.
A total space of 38 m2 square meters with a height of 3.40 meters.
5 minutes from the van Gogh , Rijks and Stedelijk Museum.

Bathroom, bedroom, toilet, balcony and lobby are all your private space.

The accommodation has a energy label A+

There is a direct bus line from Schiphol Airport to the accommodation in 20 minutes.
Departure in front of the flight terminal every 10 minutes on regular days.', 'private_room'::property_type, 'Amsterdam', 'Zuid', '43 Demo Street, Zuid, Amsterdam', 52.35911, 4.87836, ST_SetSRID(ST_MakePoint(4.880581, 52.35502), 4326)::geography, 2, false, 0, 1, 1, 1.0, 167.93, 23.0, 'EUR', '2018-01-01'),
  (72, 74, '2BR Condo with Amstel River View', 'Experience the charm of Amsterdam from our centrally located two-bedroom apartment, with stunning Amstel River views. Just blocks away from the InterContinental Amstel Amsterdam Hotel, our spacious and convenient flat ensures a comfortable stay near the heart of the city.', 'entire_place'::property_type, 'Amsterdam', 'Oud-Oost', '52 Demo Street, Oud-Oost, Amsterdam', 52.35744, 4.90808, ST_SetSRID(ST_MakePoint(4.906316, 52.356959), 4326)::geography, 4, false, 0, 2, 2, 1.0, 364.33, 0.0, 'EUR', '2018-01-01'),
  (73, 75, 'apartamento', 'Enjoy the simplicity of this quiet and centrally-located accommodation.', 'entire_place'::property_type, 'Amsterdam', 'Zuid', '143 Demo Street, Zuid, Amsterdam', 52.35923, 4.87595, ST_SetSRID(ST_MakePoint(4.879185, 52.362475), 4326)::geography, 4, true, 2, 1, 2, 1.0, 291.0, 82.0, 'EUR', '2018-01-01'),
  (74, 76, 'Light and spacious apartment with canal view', 'A very light and spacious apartment in a great area. Large bedrooms with comfortable beds. One bedroom has an en-suite bathroom, the other bathroom is in the hallway. The apartment has a view on the canal!', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '108 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36897, 4.8564, ST_SetSRID(ST_MakePoint(4.853475, 52.366059), 4326)::geography, 4, false, 0, 2, 2, 2.5, 529.6, 55.0, 'EUR', '2018-01-01'),
  (75, 77, 'HIP AND STYLISH B&B in JORDAAN', 'The B&B is within walking distance (15 min.) of the C. Station. Located between the Brouwersgracht (most beautiful canal in Amsterdam) and the Haarlemmerdijk (nicest shopping street in the Netherlands). At the edge of the Jordaan, in a quiet street. Within walking distance of many attractions. The B&B is equipped with comfortable beds, pantry with microwave, kettle, coffee machine. Coffee and tea are provided. Snel internet, Smart-TV en Netflix. The bathroom has a rain shower and a hand shower. Wc is er is separate.', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '26 Demo Street, Centrum-West, Amsterdam', 52.38328, 4.88591, ST_SetSRID(ST_MakePoint(4.883256, 52.379381), 4326)::geography, 4, false, 0, 2, 4, 1.5, 394.0, 132.0, 'EUR', '2018-01-01'),
  (76, 78, 'Cozy apartment with patio near Westerpark-Jordaan', 'Welcome to my apartment!

My recently renovated (May ’25) two-room apartment offers a cosy blend of modern comfort and retro charm. Perfect for up to two guests, it’s tucked away in a quiet, authentic Amsterdam neighbourhood—just a short stroll from the lively Westerpark and the historic Jordaan. You’ll find plenty of cafés, shops, and local highlights within walking distance. And the best part: a private patio, your peaceful little oasis for morning coffee or relaxing afternoons.', 'entire_place'::property_type, 'Amsterdam', 'Westerpark', '122 Demo Street, Westerpark, Amsterdam', 52.38327, 4.87654, ST_SetSRID(ST_MakePoint(4.874211, 52.380346), 4326)::geography, 2, false, 0, 1, 1, 1.0, 430.0, 71.0, 'EUR', '2018-01-01'),
  (77, 79, 'JONI (Room not for parties)', 'We offer 1 bedroom only with your own private bathroom (11,4 square meters) in a centrally located apartment. The room is for a maximum of 2 guests. You can choose between 2 singles beds (80x200cm) or a double bed (160x200cm).

No access to the Kitchen and Living room (as local authority requests).
Breakfast is not provided.

No parties. No pets. No infants.

Self service check-in with a secure Masterlock box.
Check-in from 15.00 (3pm). Check-out no later than 10am.', 'private_room'::property_type, 'Amsterdam', 'Centrum-Oost', '177 Demo Street, Centrum-Oost, Amsterdam', 52.37106, 4.90085, ST_SetSRID(ST_MakePoint(4.89823, 52.372741), 4326)::geography, 2, false, 0, 1, 1, 1.0, 90.0, 18.0, 'EUR', '2018-01-01'),
  (78, 80, 'Modern Apartment with Rooftop Terrace in AdamWest', 'Discover a bright, modern apartment in Bos en Lommer. Enjoy a cozy balcony for morning coffee and a spacious private rooftop terrace for sunset views. Surrounded by local cafés, green parks, and easy tram access, this stylish two-storey apartment offers the perfect blend of comfort and Amsterdam West charm. A relaxing home base to explore the city like a local.', 'entire_place'::property_type, 'Amsterdam', 'Bos en Lommer', '72 Demo Street, Bos en Lommer, Amsterdam', 52.37717, 4.86107, ST_SetSRID(ST_MakePoint(4.867007, 52.375915), 4326)::geography, 2, false, 0, 1, 1, 1.5, 357.67, 38.0, 'EUR', '2018-01-01'),
  (79, 81, 'bright & cozy space next to park', 'Discover the canal city of Amsterdam in an authentic and cozy location. This apartment in Oud-West, right in between Rembrandt and Vondelpark welcomes you with a sunny balcony, a cozy kitchen-living open space, private bedroom, and a large bathtub to relax after a day out. The place is close to many other attractions walking and biking distance: Street market, foodhall, supermarkets and restaurants (5-10 min)
Museums and Central area well connected via public transport or biking (15 min)', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '83 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36308, 4.8561, ST_SetSRID(ST_MakePoint(4.85862, 52.358959), 4326)::geography, 2, true, 2, 1, 1, 1.0, 190.0, 0.0, 'EUR', '2018-01-01'),
  (80, 82, 'Prachtig Luxe Appartement op A+ Locatie met airco', 'The house is the perfect mix of living in the city center, but in a quiet, closed-off street. It has been renovated, has a spacious roof terrace, a bedroom of 35 m² with a private bathroom and Jacuzzi, plus a second bathroom. The apartment can be reached by a few stairs and is on the 2nd and 3rd floor. Hence the beautiful view from the roof terrace.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-West', '133 Demo Street, Centrum-West, Amsterdam', 52.37442, 4.89739, ST_SetSRID(ST_MakePoint(4.897767, 52.37207), 4326)::geography, 2, false, 0, 1, 1, 2.0, 564.67, 185.0, 'EUR', '2018-01-01'),
  (81, 83, 'Sit & Relax canalview apartment central Amsterdam', 'Lovely apartment, heart/centre Amsterdam, totally new renovated, direct at the canal Herengracht, in the famous area “9 streets”, full with different small shops, fashion, art, vintage, boutiques, restaurants, but staying home with coffee, wine and watch the boats or cook in our new fully equiped kitchen, stylish, most famous attractions + central station in walking distance, across te street bike-rental. Spacious apartment due to a smart electric bed system with comfortable matrasses', 'entire_place'::property_type, 'Amsterdam', 'Centrum-West', '146 Demo Street, Centrum-West, Amsterdam', 52.37027, 4.88837, ST_SetSRID(ST_MakePoint(4.886545, 52.371094), 4326)::geography, 2, false, 0, 1, 1, 1.0, 442.5, 100.0, 'EUR', '2018-01-01'),
  (82, 84, 'Tiny and cozy room in ground floor apartment.', 'A tiny and cozy room located in the heart of Amsterdam-West, ten to fifteen minutes away from the city center by public transport. Apartment is located on the ground floor.

The neighborhood is great, with all sorts of places to grab a bite or a drink only a minute''s walk away from the apartment. There are two supermarkets nearby, and at the end of the street there is a lovely park to enjoy as well.

This room is available for one person.', 'private_room'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '51 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.37255, 4.85435, ST_SetSRID(ST_MakePoint(4.852302, 52.374759), 4326)::geography, 1, true, 2, 1, 1, 1.0, 99.0, 0.0, 'EUR', '2018-01-01'),
  (83, 85, 'Quiet Bright Apartment - 2-4p.', 'Light and clean apartment. Located very central in a canal-street. Private entry. Good public transport connection and within walking distance of Jordaan and Rijks museum.', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '126 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36983, 4.87103, ST_SetSRID(ST_MakePoint(4.876503, 52.369999), 4326)::geography, 4, false, 0, 1, 2, 1.0, 284.67, 94.0, 'EUR', '2018-01-01'),
  (84, 86, 'Private studio with own bathroom&terrace', NULL, 'private_room'::property_type, 'Amsterdam', 'Centrum-Oost', '24 Demo Street, Centrum-Oost, Amsterdam', 52.363968, 4.885711, ST_SetSRID(ST_MakePoint(4.883096, 52.364857), 4326)::geography, 2, false, 0, 1, 1, 1.0, 168.0, 52.0, 'EUR', '2018-01-01'),
  (85, 87, 'Holland', 'Beautiful characteristic historic sailing ship located on a quiet quay in Amsterdam. You won’t forget the peaceful surroundings of this rustic destination. Especially because you can be in the bustling center of Amsterdam within 10 minutes.', 'entire_place'::property_type, 'Amsterdam', 'Oostelijk Havengebied - Indische Buurt', '58 Demo Street, Oostelijk Havengebied - Indische Buurt, Amsterdam', 52.377, 4.94661, ST_SetSRID(ST_MakePoint(4.949299, 52.377299), 4326)::geography, 3, false, 0, 1, 2, 1.0, 224.0, 66.0, 'EUR', '2018-01-01'),
  (86, 88, 'Top location, quiet guesthouse, 2p', 'Everything you need is provided in this two room guesthouse with kitchen and bedroom. Perfect location, in the middle of Amsterdam. Walking distance to all museums, restaurants, shops etc. The guesthouse and patio are no smoking area''s.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-Oost', '34 Demo Street, Centrum-Oost, Amsterdam', 52.36239, 4.89859, ST_SetSRID(ST_MakePoint(4.899479, 52.359085), 4326)::geography, 2, false, 0, 1, 1, 1.0, 198.6, 68.0, 'EUR', '2018-01-01'),
  (87, 89, 'Private apartment@ city centre & canal view', 'Your own private souterrain apartment for a couple of days in the heart of Amsterdam!

Spacious apartment with a queensize bed, kitchenette (no stove) , seperate new bathroom and seperate toilet.

The apartment is fully private, no shared spaces!', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '71 Demo Street, Centrum-West, Amsterdam', 52.36902, 4.89535, ST_SetSRID(ST_MakePoint(4.889868, 52.368146), 4326)::geography, 2, false, 0, 1, 1, 1.5, 283.0, 95.0, 'EUR', '2018-01-01'),
  (88, 90, 'Catalonia Vondel Amsterdam 4* - Premium room', 'Experience a superior stay in the Premium Rooms at the Emil Emil Emil hotel, featuring a cozy minimalist design and a private bathroom. Take advantage of all the amenities the hotel offers, such as 24-hour reception, daily housekeeping, or a buffet breakfast, as well as a restaurant and gastropub where you can dine or enjoy a drink whenever you like. All of this in one of the best areas of Emil, near the famous Vondelpark and the lively Leidseplein Square.', 'private_room'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '27 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36373, 4.87849, ST_SetSRID(ST_MakePoint(4.882297, 52.360648), 4326)::geography, 2, false, 0, 0, 1, 1.0, 181.0, 49.0, 'EUR', '2018-01-01'),
  (89, 91, 'the Boathouse bed&bike A''dam centre', 'The studio on the ground floor of a canalhouse, is near the Damsquare, the'' 9 streets, Hermitage, Amsterdam Historical museum, Rembrandthouse, Waterlooplein, Nieuwmarkt. 
You will enjoy ''The Bike shed'' because Amsterdam is at your feet, Everything is walking distance away. The restaurants, musea and theaters and filmhouses are all around the corner. It is still a real neighbourhood where you have coffee with the locals. The studio is perfect for couples and friends / travellers.', 'private_room'::property_type, 'Amsterdam', 'Centrum-Oost', '17 Demo Street, Centrum-Oost, Amsterdam', 52.37026, 4.89931, ST_SetSRID(ST_MakePoint(4.901338, 52.371793), 4326)::geography, 2, false, 0, 1, 1, 1.0, 196.56, 50.0, 'EUR', '2018-01-01'),
  (90, 92, 'Apartment in Amsterdam West across from Vondelpark', 'Modern, minimalistic one-bedroom apartment located on Staringplein, a quiet and beautiful square in Amsterdam Oud-West. The apartment includes a spacious living room with a fully equipped open kitchen, one bedroom, one bathroom with bath tub, and two balconies with view over the square.

Vondelpark is directly across the street, and the city centre is within walking distance. The area offers many cafés, restaurants, and bars, and has a friendly, local atmosphere.', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '39 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.3610423, 4.8626919, ST_SetSRID(ST_MakePoint(4.8691, 52.359804), 4326)::geography, 2, false, 0, 1, 1, 1.0, 214.0, 59.0, 'EUR', '2018-01-01'),
  (91, 93, 'Staysome Amsterdam Hemonyst. | Queen Room +Balcony', 'Welcome! Stay in lovingly furnished apartments – a personal alternative to impersonal hotel rooms or unfamiliar private rentals. Our suites combine the quality standards of a hotel with the coziness and comfort of your own apartment.
Thanks to our electronic access system, you can check in at any time after 3:00 PM – no need for a reception desk or prior arrangements. You''ll receive your access codes by email on the day of arrival.', 'private_room'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '76 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.35813, 4.9022055, ST_SetSRID(ST_MakePoint(4.897471, 52.356176), 4326)::geography, 2, false, 0, 1, 1, 1.0, 324.0, 88.0, 'EUR', '2018-01-01'),
  (92, 94, 'Blueprint B&B - Breakfasts & Bikes', '55 m2 ground floor apartment in the historic center, bikes & breakfasts

The fabulous location of the BluePrint bed and breakfast is set between the city''s best canals Prinsengracht, Reguliersgracht and makes a perfect base from which to enjoy the city''s historic sights.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-Oost', '88 Demo Street, Centrum-Oost, Amsterdam', 52.36012, 4.89513, ST_SetSRID(ST_MakePoint(4.888427, 52.361922), 4326)::geography, 4, false, 0, 1, 4, 1.5, 306.0, 75.0, 'EUR', '2018-01-01'),
  (93, 95, 'Private room in a Historical Building! City Centre', 'A private bedroom in an amazing building what is build in 1785 ! An historical building with typical Amsterdam architecture !

The bedroom and bathroom / toilet with are located on the 1th floor of the appartment. The appartment is on the 2th floor of the building. (In the appartment we have two young females living, they have their own bathroom on the ground floor of the appartment)', 'private_room'::property_type, 'Amsterdam', 'Centrum-Oost', '143 Demo Street, Centrum-Oost, Amsterdam', 52.37103, 4.91205, ST_SetSRID(ST_MakePoint(4.909983, 52.370202), 4326)::geography, 4, false, 0, 1, 4, 1.0, 155.59, 27.0, 'EUR', '2018-01-01'),
  (94, 96, 'Cozy apartment in Amsterdam West', 'Relax and unwind in this peaceful, stylish space. Authentic and cosy apartment with everything you need. Between Rembrandt and Erasmus Park and 1 min walk from the bustling Jan Evertsenstraat (Amsterdam West, de Baarsjes) . Within 5 to 10 minutes in the center of the city. Public transport is front of the door and bicycle rental around the corner!', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '175 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.37257, 4.85025, ST_SetSRID(ST_MakePoint(4.847765, 52.37505), 4326)::geography, 2, false, 0, 1, 1, 1.0, 209.45, 59.0, 'EUR', '2018-01-01'),
  (95, 97, 'Homely studio close to main sights.', 'Bedroom with separate kitchenette and a private bathroom in a real Amsterdam souterrain. Naturally cool in the summer. iVery central location, in walking distance from Museum square and Dam square. Amidst nice restaurants and shops and public transport right on your doorstep this BnB will make your stay in Amsterdam very easy going.', 'private_room'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '67 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.3713968, 4.8716659, ST_SetSRID(ST_MakePoint(4.876995, 52.369573), 4326)::geography, 2, false, 0, 1, 2, 1.0, 123.5, 22.0, 'EUR', '2018-01-01'),
  (96, 98, 'Bed & Beach A’dam, private bathroom + Free Parking', 'Welcome at Bed & Beach Amsterdam. We have a bed for the night, with private bathroom and free car parking. The room is separated from the rest of our house, so very quiet. 
Our house was built in 2020 on a new created island in Amsterdam; Centrumeiland. It is near the new Amsterdam Beach. This is a quiet area where many families live.
For concerts in Ziggo dome or Johan Cruijff Arena: there is a direct bus connection. 

—> We don’t serve breakfast, but there is a refrigerator you can use.', 'private_room'::property_type, 'Amsterdam', 'IJburg - Zeeburgereiland', '159 Demo Street, IJburg - Zeeburgereiland, Amsterdam', 52.35145, 5.01478, ST_SetSRID(ST_MakePoint(5.012265, 52.348668), 4326)::geography, 2, false, 0, 1, 1, 1.0, 126.83, 0.0, 'EUR', '2018-01-01'),
  (97, 99, 'Twin room', 'Our hotel operates on 100% renewable energy, with solar panels on the roof, and a commitment to sustainability. Julia Hotel The Julia Julia is located on the Amstelveenseweg between the large green spaces of Vondelpark and Rembrandtpark. We offer minimalist, modern design, and comfortable Royal Dutch Auping beds. Our central location is an easy tram and bus ride from the airport, and you can take a tram from Amsterdam Central Julia.', 'private_room'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '106 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.35728, 4.85539, ST_SetSRID(ST_MakePoint(4.854369, 52.353994), 4326)::geography, 2, false, 0, 1, 2, 1.0, 96.97, 0.0, 'EUR', '2018-01-01'),
  (98, 100, 'Two-Floor Penthouse in Central AMS · Home Cinema', 'Comfortable two-bedroom apartment with a spacious terrace located in a nice, local and residential neighborhood of Amsterdam. 

Enjoy the spacious terrace and rooftop or watch your favorite movies with great sound from the hammock!

Enjoy your spa-at-home featured with a large bath tub and walk-in shower.

The neighborhood offers a lot of great restaurants, bars and shops within close walking distance. 

All amenities are present, the only thing you need to bring along is your suitcase.', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '118 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.37125, 4.84865, ST_SetSRID(ST_MakePoint(4.84411, 52.374725), 4326)::geography, 4, false, 0, 2, 2, 1.5, 483.67, 90.0, 'EUR', '2018-01-01'),
  (99, 101, 'Bella B&B in the heart of the Pijp, Amsterdam', 'Bella B&B, in a charming 1890 De Pijp building, boasts a sunny back terrace. Steps from Albert Cuyp Market, cafes, and bars, it’s next to two tram stops and a 10-min walk or tram ride from De Pijp Metro Station, with easy Schiphol access. Ideal for exploring the Museum Quarter, 10 min away, it offers vibrant Amsterdam living. Live like locals in trendy De Pijp!', 'entire_place'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '116 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.35379, 4.90109, ST_SetSRID(ST_MakePoint(4.902272, 52.355681), 4326)::geography, 4, false, 0, 1, 3, 1.0, 417.0, 145.0, 'EUR', '2018-01-01'),
  (100, 102, 'Sunny apartment', 'Welcome to our 70m2 apartment located in the heart of Amsterdam, near the Muiderpoort Station! Featuring a sunny balcony. This apartment provides the perfect base for exploring the city. With its central location near the Muiderpoort Station, summary, this apartment is the ideal base to enjoy everything Amsterdam has to offer!', 'entire_place'::property_type, 'Amsterdam', 'Oostelijk Havengebied - Indische Buurt', '110 Demo Street, Oostelijk Havengebied - Indische Buurt, Amsterdam', 52.35879139999999, 4.9356063, ST_SetSRID(ST_MakePoint(4.936509, 52.357545), 4326)::geography, 4, false, 0, 2, 2, 1.0, 262.67, 77.0, 'EUR', '2018-01-01')
) AS v(id, host_id, title, description, property_type, city, neighborhood, address, latitude,
  longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds, bathrooms,
  price_per_night, cleaning_fee, currency, created_at)
JOIN cities c ON c.name = v.city;

INSERT INTO listings (id, host_id, title, description, property_type, city_id, neighborhood, address,
  latitude, longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds,
  bathrooms, price_per_night, cleaning_fee, currency, created_at)
OVERRIDING SYSTEM VALUE
SELECT v.id, v.host_id, v.title, v.description, v.property_type, c.id, v.neighborhood, v.address,
  v.latitude, v.longitude, v.public_location, v.max_guests, v.pets_allowed, v.max_pets, v.bedrooms,
  v.beds, v.bathrooms, v.price_per_night, v.cleaning_fee, v.currency, v.created_at::timestamptz
FROM (VALUES
  (101, 103, 'Modern guesthouse at canal near center', 'This centrally located place is modernly designed and has all things you need for a short trip.
For summers: naturally cooled, since its partly underground.
In Winters: cozy warm due to floor heating.', 'entire_place'::property_type, 'Amsterdam', 'Westerpark', '136 Demo Street, Westerpark, Amsterdam', 52.38607, 4.87933, ST_SetSRID(ST_MakePoint(4.874895, 52.389427), 4326)::geography, 2, false, 0, 1, 1, 1.0, 1446.03, 409.0, 'EUR', '2018-01-01'),
  (102, 104, 'Comfortable apartment in Amsterdam West', 'Comfortable apartment in a lively neighborhood close to the center. The apartment is located in a quiet street close to public transport. It has all you need for a wonderful stay.

PLEASE NOTE: This is not a commercial apartment or hotel room, it is my private home where I live. It is consequently a lived space: I try to make it free of clutter but there may be some personal belongings. If you expect a perfectly sanitized Mary Kondo-experience, this place is NOT FOR YOU :)', 'entire_place'::property_type, 'Amsterdam', 'Bos en Lommer', '151 Demo Street, Bos en Lommer, Amsterdam', 52.38193, 4.84901, ST_SetSRID(ST_MakePoint(4.8505, 52.380917), 4326)::geography, 2, false, 0, 1, 1, 1.5, 156.67, 29.0, 'EUR', '2018-01-01'),
  (103, 105, 'Luxurious apartment in Amsterdam', 'The two-room apartment is a beautiful and very light spacious house, which offers everything you need, including a garden! It lays in the popular ''dapperbuurt'', which is very close to central station and the city centre. The area is known for his trendy bars, good restaurants and it breaths an authentic vibe.', 'entire_place'::property_type, 'Amsterdam', 'Oud-Oost', '176 Demo Street, Oud-Oost, Amsterdam', 52.36544, 4.92655, ST_SetSRID(ST_MakePoint(4.928394, 52.362897), 4326)::geography, 2, true, 2, 1, 1, 1.0, 354.33, 82.0, 'EUR', '2018-01-01'),
  (104, 106, 'Nice Room in center of Amsterdam', 'Enjoy easy access to everything from this perfectly located heart of the city', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '5 Demo Street, Centrum-West, Amsterdam', 52.3759567, 4.8924837, ST_SetSRID(ST_MakePoint(4.886185, 52.377536), 4326)::geography, 2, false, 0, 1, 1, 1.0, 151.5, 21.0, 'EUR', '2018-01-01'),
  (105, 107, 'Houseboat stay in private and cozy studio +2 bikes', 'Our classic ship is in the center of the city but its on a quiet street ,close to central station, the ferry to amsterdam noord and ,shops markets restaurants and bars are all close by.We always try to welcome our guests personally ,but due to work this is not always possible ,then we leave the key in a key lock and send you instructions ,and we meet up later .During your stay we provide 2 city bikes (back pedal brakes )with locks for you to use.Please note that we do not serve breakfast', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '167 Demo Street, Centrum-West, Amsterdam', 52.38567, 4.89019, ST_SetSRID(ST_MakePoint(4.892024, 52.384663), 4326)::geography, 2, false, 0, 0, 1, 1.5, 148.0, 37.0, 'EUR', '2018-01-01'),
  (106, 108, 'Canal view, ground floor, spacious - family', 'Groups (3 or 4 adults) not accepted. 

Perfect for couples, families (max. 4: 2 adults and 2 children/babies/infants) & business travellers.

You will have your own private spacious studio with canal view - located in the souterrain (street-level / ground floor) of the canal house. 

Modern but with original features, such as the ceiling beams, typical Dutch windows and an impressive tiled wall from 1670. 

It is located on the Keizersgracht between the Leidsestraat and the Spiegelstraat.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-Oost', '6 Demo Street, Centrum-Oost, Amsterdam', 52.36402, 4.88912, ST_SetSRID(ST_MakePoint(4.890222, 52.364853), 4326)::geography, 4, false, 0, 1, 6, 1.0, 447.0, 111.0, 'EUR', '2018-01-01'),
  (107, 109, 'Compfy tiny house apartment', 'Cozy little apartment in a quiet& vibrant neighbourhood. We are renting longterm to ideally one person. The studio has a comfortable double bed. Private bathroom and toilet. The place is fully equipped. There is a washing machine, stove, hood, microwave and oven in one. A big supermarket, night shop, restaurants, lunchrooms, bike rentals, bus and tramstops etc are just around the corner one minute walk from us. You walk in 30 min to the hart of the city centre; 15 min walk to the central canals.', 'entire_place'::property_type, 'Amsterdam', 'Bos en Lommer', '162 Demo Street, Bos en Lommer, Amsterdam', 52.375683, 4.860004, ST_SetSRID(ST_MakePoint(4.857771, 52.375194), 4326)::geography, 1, false, 0, 1, 1, 1.0, 107.73, 24.0, 'EUR', '2018-01-01'),
  (108, 110, 'Kamer in Amsterdam - Souterrain kamer', 'Are you alone or with your partner and 26 years and older, are you looking for a quiet place to sleep in the heart of Amsterdam? Then you''ve come to the right place!
Take the IJ ferry at the back of the central station and immediately experience the rural feeling of Amsterdam-Noord and arrive at the destination after three minutes. 
You will be warmly welcomed by Yara, the host. She will do everything she can to make your stay as pleasant as possible. Please note: no drugs, not suitable for groups or friends.', 'private_room'::property_type, 'Amsterdam', 'Oud-Noord', '131 Demo Street, Oud-Noord, Amsterdam', 52.3835172, 4.9128259, ST_SetSRID(ST_MakePoint(4.910484, 52.385449), 4326)::geography, 2, false, 0, 1, 1, 1.0, 158.0, 43.0, 'EUR', '2018-01-01'),
  (109, 111, 'Double room', 'Our hotel is an ideal gateway to explore the city and surrounding suburbs. For business travellers, the RAI Convention Center is only about a 5-minute taxi ride. When you want to soak in nature or greenery, the canals and Sarphatipark are just steps away. Some rooms feature balconies with garden and city views. We’re also close to the ring road, making getting around the city a breeze.', 'private_room'::property_type, 'Amsterdam', 'De Pijp - Rivierenbuurt', '134 Demo Street, De Pijp - Rivierenbuurt, Amsterdam', 52.35525, 4.90248, ST_SetSRID(ST_MakePoint(4.897504, 52.355789), 4326)::geography, 2, false, 0, 1, 1, 1.0, 186.41, 42.0, 'EUR', '2018-01-01'),
  (110, 112, 'Canal, Spacious and Quiet Studio, gr floor', 'A spacious ground floor studio. On Prinsengracht in the heart of the city, Museumdistrict and city centre with its numerous shops and restaurants. The RAI is 5 min. by public transport. The house is a national monument, built in 1655. It''s character is carefully maintained with all modern necessities melted into the original framework. Our family is really attached to the house on the canal. We hope you will enjoy it just as much. The studio is suited for 2 friends or a couple.', 'private_room'::property_type, 'Amsterdam', 'Centrum-Oost', '177 Demo Street, Centrum-Oost, Amsterdam', 52.36277, 4.88854, ST_SetSRID(ST_MakePoint(4.886032, 52.365195), 4326)::geography, 2, false, 0, 1, 1, 1.5, 249.0, 0.0, 'EUR', '2018-01-01'),
  (111, 113, 'Charming Apartment in Westerpark', 'Discover the allure of Amsterdam from this charming 66 square meter apartment nestled in the vibrant neighborhood of Staadliedsburt. Located just one block away from the picturesque Westerpark, you can enjoy easy access to cafes, restaurants, and bars. 

Enjoy a complete with a fully equipped kitchen, comfortable bedroom, and a terrace & balcony. With excellent transport links, including nearby tram lines, exploring the city and beyond is a breeze.', 'entire_place'::property_type, 'Amsterdam', 'Westerpark', '147 Demo Street, Westerpark, Amsterdam', 52.3846453, 4.8707793, ST_SetSRID(ST_MakePoint(4.872056, 52.385582), 4326)::geography, 3, false, 0, 1, 1, 1.0, 337.0, 0.0, 'EUR', '2018-01-01'),
  (112, 69, 'Luxury suite', 'Our boutique hotel in Amsterdam West combines historic charm with modern comfort. Set in the beautifully renovated Chassé Church, we offer spacious rooms, each uniquely designed with warm South American-inspired interiors, bamboo floors, and natural elements that create a relaxing atmosphere. Whether you’re here for a romantic weekend, a family getaway, or a short city break, you’ll enjoy thoughtful amenities and a unique setting you’ll love.', 'private_room'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '26 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.3697, 4.86174, ST_SetSRID(ST_MakePoint(4.857319, 52.369247), 4326)::geography, 3, false, 0, 1, 1, 1.0, 128.1, 0.0, 'EUR', '2018-01-01'),
  (113, 114, 'Bed and Bike Jordaan - Luxury for a family!', 'This apartment provides a unique stay right in the center of Amsterdam. You will have access to the first floor of a two centuries old house. Fully private for 2-3 persons to use with a bathroom, a bedroom and a small seating area with a television. There is a pantry with a microwave, coffee maker, kettle and plates/cutlery.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-West', '45 Demo Street, Centrum-West, Amsterdam', 52.38169, 4.89023, ST_SetSRID(ST_MakePoint(4.892697, 52.383768), 4326)::geography, 3, false, 0, 1, 1, 1.0, 178.0, 31.0, 'EUR', '2018-01-01'),
  (114, 115, 'Amazing renovated apt. in centre', 'This unique Jordaan apartment has been renovated in August ''23 and is equipped with everything you need for an unforgettable stay in Amsterdam. The perfect place for a couple, friends or a business trip at a central location. 

The separate bedroom, a functional bathroom with washer and dryer, a generous living area with open kitchen, spacious couch and beautiful original stained glass windows and with a balcony viewing the courtyard.

Is there anything else you could wish for?', 'entire_place'::property_type, 'Amsterdam', 'Centrum-West', '36 Demo Street, Centrum-West, Amsterdam', 52.3720175, 4.878348, ST_SetSRID(ST_MakePoint(4.880035, 52.375491), 4326)::geography, 2, false, 0, 1, 1, 1.5, 325.0, 40.0, 'EUR', '2018-01-01'),
  (115, 116, 'Cozy flat in Amsterdam West that feels like home!', 'This cozy flat offers a comfortable bed, stylish decor, and a great view of the city. Located in the vibrant neighborhood of Amsterdam West, you''ll be surrounded by trendy cafes, local markets, and beautiful parks. It''s the ideal spot for exploring all that Amsterdam has to offer! 🌷✨', 'entire_place'::property_type, 'Amsterdam', 'Osdorp', '30 Demo Street, Osdorp, Amsterdam', 52.35665, 4.78965, ST_SetSRID(ST_MakePoint(4.792709, 52.355419), 4326)::geography, 2, false, 0, 1, 1, 1.5, 208.0, 59.0, 'EUR', '2018-01-01'),
  (116, 117, 'Generator - Bed in 4 bed Dorm', 'Lucas is solely responsible for offering this listing on Airbnb, and they host as a business. For more legal information, visit our Help Center.

Business name: Horizon Properties BV
Business registry: Dutch Business Register of the Dutch Chamber of Commerce
KVK number: 60538376
Email: reception.geams@staygenerator.com
Phone: +31 20 399 8886
Address: Mauritskade 57, 1092 AD Amsterdam, Netherlands
To help protect yourself from fraud, always use Airbnb to send money and communicate with hosts.', 'shared_room'::property_type, 'Amsterdam', 'Oud-Oost', '29 Demo Street, Oud-Oost, Amsterdam', 52.36054, 4.91984, ST_SetSRID(ST_MakePoint(4.914779, 52.361478), 4326)::geography, 1, false, 0, 1, 1, 1.0, 44.0, 13.0, 'EUR', '2018-01-01'),
  (117, 118, 'Comfort City View Room by Sotel Amsterdam CS', 'A compact 8 m² escape for up to 2 guests, this room features a single bed, safe, tea & coffee facilities, and a modern private bathroom. Large window offers city views, and free Wi-Fi, air-con and sound-proofing ensure a comfortable stay in the heart of Shirin.', 'private_room'::property_type, 'Amsterdam', 'Centrum-West', '146 Demo Street, Centrum-West, Amsterdam', 52.378, 4.89622, ST_SetSRID(ST_MakePoint(4.896963, 52.373852), 4326)::geography, 2, false, 0, 1, 1, 1.0, 255.0, 0.0, 'EUR', '2018-01-01'),
  (118, 119, 'Beautiful, bright apartment near city center', 'This family friendly house is 100 m2. The house is located in Westerpark area a quiet and friendly neighborhood.
Near central station and city centre, both 10 min on your bike. We live very close to the Westergasfabriek. An area with a lot of
cultural activities and nice restaurants. Very close to the house, 2 min walk there is the stop for the tram wich takes you to the centre
all the museums and the Artis zoo. And lots of other things to do.', 'entire_place'::property_type, 'Amsterdam', 'Westerpark', '34 Demo Street, Westerpark, Amsterdam', 52.38453, 4.87098, ST_SetSRID(ST_MakePoint(4.866495, 52.387443), 4326)::geography, 4, false, 0, 2, 2, 1.0, 486.0, 123.0, 'EUR', '2018-01-01'),
  (119, 120, 'Cozy private studio | Centre of Amsterdam | 2P', 'Julia is solely responsible for offering this listing on Airbnb, and they host as a business. For more legal information, visit our Help Center.

Business name: PJ''s
Business registry: Dutch Business Register of the Dutch Chamber of Commerce
KVK number: 58673792
Email: korteleidsedwarsstraat_163sous@user.guesty.com
Phone: +31 6 46647337
Address: Korte Leidsedwarsstraat 163, 1017 RA Amsterdam, Netherlands
To help protect yourself from fraud, always use Airbnb to send money and communicate with hosts.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-Oost', '174 Demo Street, Centrum-Oost, Amsterdam', 52.363037109375, 4.885691165924072, ST_SetSRID(ST_MakePoint(4.88846, 52.362315), 4326)::geography, 2, false, 0, 1, 1, 1.0, 284.5, 0.0, 'EUR', '2018-01-01'),
  (120, 121, 'Luxury water-side flat in the Canal District', 'Luxurious, fully equipped, 106m2 1st - floor apartment located in the Canal District and pinned to the famous 9 Streets.
Stunning views onto the best canal in Amsterdam. You have access to all the central and Jordaan shops & restaurants as well walking distance to the Anne Frank House.
Separate bedroom and bathroom with access to canal views by being very Dutch and sitting in the windows to enjoy the world pass by. Enjoy this sort-after famous interior-styled property.', 'entire_place'::property_type, 'Amsterdam', 'Centrum-West', '180 Demo Street, Centrum-West, Amsterdam', 52.37202121286534, 4.886802098849934, ST_SetSRID(ST_MakePoint(4.886301, 52.36993), 4326)::geography, 2, false, 0, 1, 1, 1.0, 1027.0, 275.0, 'EUR', '2018-01-01'),
  (121, 122, 'Cosy apartment in Amsterdam', 'Discover Amsterdam from our charming apartment in the trendy De Baarsjes district. This cozy space is equipped with all the modern comforts you need. It features a snug bedroom and a relaxing living area, perfect for unwinding after a day of exploration. Just steps away, you''ll find lively cafes, unique shops, and beautiful parks. Whether you''re visiting for a few days or planning a longer stay, our apartment offers a blend of comfort and convenience in one of Amsterdam''s most vibrant areas', 'entire_place'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '143 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.37281, 4.857, ST_SetSRID(ST_MakePoint(4.853833, 52.374021), 4326)::geography, 2, false, 0, 1, 1, 1.0, 231.67, 62.0, 'EUR', '2018-01-01'),
  (122, 123, 'Spacious Stylish room @ Leidseplein', 'The bedroom is modernly decorated and still cozy and has a private bathroom with shower and bathtub. It''s located in the true centre of Amsterdam. All the tourist attractions are in walking distance. I you don''t know where to go, I will show you! :)', 'private_room'::property_type, 'Amsterdam', 'Centrum-Oost', '126 Demo Street, Centrum-Oost, Amsterdam', 52.36349105834961, 4.883462905883789, ST_SetSRID(ST_MakePoint(4.886448, 52.367077), 4326)::geography, 2, false, 0, 1, 1, 1.5, 152.92, 48.0, 'EUR', '2018-01-01'),
  (123, 124, 'Quadruple room', NULL, 'private_room'::property_type, 'Amsterdam', 'Centrum-Oost', '21 Demo Street, Centrum-Oost, Amsterdam', 52.36521, 4.88575, ST_SetSRID(ST_MakePoint(4.882375, 52.366134), 4326)::geography, 4, false, 0, 1, 1, 1.0, 206.61, 49.0, 'EUR', '2018-01-01'),
  (124, 125, 'Double/twin room', 'Welcome to Zara’s Oud-West district at Hotel Zara City Centre, where large windows create sunlit spaces and our coffee-inspired art and always-flowing brews reflect our heritage. Centrally located, you can stroll to the landmark Prinsengracht canal in just 10 minutes or reach Leidseplein for direct airport buses and luxury designer shops along P.C. Hooftstraat. We offer dedicated wheelchair-accessible rooms, cots and highchairs for families, and an optional continental breakfast.', 'private_room'::property_type, 'Amsterdam', 'De Baarsjes - Oud-West', '27 Demo Street, De Baarsjes - Oud-West, Amsterdam', 52.36295, 4.87628, ST_SetSRID(ST_MakePoint(4.872668, 52.361418), 4326)::geography, 2, false, 0, 1, 2, 1.0, 122.31, 16.0, 'EUR', '2018-01-01'),
  (125, 126, 'CCentre Light gf. apt. | 150m² | garden + view', 'Welcome to our place. 

Our apartment is situated at the lower two floors of at 19th century building with a lot of interesting Dutch Architecture.

And lies opposite of the Park, within 5 minutes you are in the heart of City Center. In the street you find several restaurants and bars and the Tropen Museum. Wihtin 500m from our home you have high-end Hotels like Hyat, Pillows and Arena.

PUBLIC TRANSPORT (door to door):
- JohanCruijff Arena: 20m 
- Rai: 20m
- Museumsquare: 19m
- Damsquare: 18m', 'entire_place'::property_type, 'Amsterdam', 'Oud-Oost', '159 Demo Street, Oud-Oost, Amsterdam', 52.35993, 4.92418, ST_SetSRID(ST_MakePoint(4.922959, 52.358958), 4326)::geography, 4, false, 0, 3, 2, 2.5, 1170.6, 0.0, 'EUR', '2018-01-01'),
  (126, 127, 'The Adega', 'Lovely and cosy place close to Ribeira d''Ilhas surf beach and Ericeira fishing village. Santo Isidoro is a quiet traditional village where you are woken in the morning by the birds. The village has a cafe, a grocery shop and a butcher. Everything you need for a relaxing holiday.

See video or region

https://youtu.be/GWSm_Z4pqUQ', 'entire_place'::property_type, 'Lisbon', 'Santo Isidoro', '109 Demo Street, Santo Isidoro, Lisbon', 38.99176, -9.39848, ST_SetSRID(ST_MakePoint(-9.403405, 38.991646), 4326)::geography, 3, true, 2, 1, 3, 1.0, 120.0, 25.0, 'EUR', '2018-01-01'),
  (127, 128, 'Lisbon metro double room', 'One double room in the residencial luxury quarter of north Lisbon. This is a house in the higher point of the city. Facility for parking the cars, paying outside the house. 400m from the subway station.', 'private_room'::property_type, 'Lisbon', 'Lumiar', '65 Demo Street, Lumiar, Lisbon', 38.76516, -9.16873, ST_SetSRID(ST_MakePoint(-9.164304, 38.767225), 4326)::geography, 2, false, 0, 1, 1, 1.0, 112.33, 0.0, 'EUR', '2018-01-01'),
  (128, 129, 'Capitão', 'The space
It has 6 bedrooms with private bathroom, common areas, like a co-working room, equipped kitchen, dining room, all with fast internet, cleaning and fresh towels and linen.
Each room has a fridge and a desk to work.

Registration Details
33353/AL', 'private_room'::property_type, 'Lisbon', 'Ericeira', '127 Demo Street, Ericeira, Lisbon', 38.96482, -9.41727, ST_SetSRID(ST_MakePoint(-9.417415, 38.963422), 4326)::geography, 1, false, 0, 1, 1, 1.0, 43.9, 0.0, 'EUR', '2018-01-01'),
  (129, 130, 'Lisbon Design Prata Apartment 5E', 'Located in the best location in Lisbon, on Rua da Prata (pedestrian-only), this recently renovated apartment offers a stunning view of São Jorge Castle. Just 300 meters from Comércio Square, it is surrounded by restaurants, bars, supermarkets, grocery stores, and traditional bakeries. Additionally, the city''s main tourist attractions are within walking distance
The metro station is only 250 meters away
With 80m², the apartment features:
✔ 3 bedrooms, including one en-suite
✔ 2 full bathrooms', 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '93 Demo Street, Santa Maria Maior, Lisbon', 38.71147879999999, -9.1372561, ST_SetSRID(ST_MakePoint(-9.137179, 38.712514), 4326)::geography, 5, true, 2, 3, 3, 2.0, 182.0, 0.0, 'EUR', '2018-01-01'),
  (130, 131, 'Cais do Sodré | 5 Bedrooms + 5 Baths | Sleeps 15', 'Stay in the heart of Cais do Sodré, just steps from Time Out Market and close to Chiado. Ideal for families and groups of up to 15 guests.

The accommodation consists of 2 apartments connected by an interior door, offering 5 bedrooms, 5 bathrooms, 2 living rooms and 2 fully equipped kitchens.
Both are located on the 2nd floor. The lift stops between floors, so stairs are required before and after the lift.
A great option for groups who want to stay together while enjoying more space and privacy.', 'entire_place'::property_type, 'Lisbon', 'Misericrdia', '52 Demo Street, Misericrdia, Lisbon', 38.70808792114258, -9.145041465759277, ST_SetSRID(ST_MakePoint(-9.145944, 38.71169), 4326)::geography, 15, false, 0, 5, 10, 5.0, 405.0, 0.0, 'EUR', '2018-01-01'),
  (131, 132, 'GuestReady - Condessa Jasmine', 'This two-bedroom apartment in the heart of Lisbon is perfect for couples and friends looking to stay in the city centre. It has everything you need for a pleasant stay. The property is close to various attractions like Castelo de São Jorge, good restaurants and shops, and the Lisboa Rossio station is just 3 minutes away, so guests can easily travel and explore the city!', 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '157 Demo Street, Santa Maria Maior, Lisbon', 38.7138, -9.14159, ST_SetSRID(ST_MakePoint(-9.145308, 38.710401), 4326)::geography, 4, true, 2, 2, 2, 1.0, 267.67, 86.0, 'EUR', '2018-01-01'),
  (132, 133, 'Numa | XL Studio w/ Kitchenette near Rato', 'This comfortable room offers 31 sqm of space. Ideal for up to four people, its double bed (160x200), sofabed (160x200), and modern bathroom with shower make this stay a perfect way to experience Shirin. The room also offers a kitchenette with sustainable coffee and a dining table, so you’ll have everything you need for maximum comfort and minimal stress.', 'entire_place'::property_type, 'Lisbon', 'Santo Antnio', '117 Demo Street, Santo Antnio, Lisbon', 38.721061, -9.1529281, ST_SetSRID(ST_MakePoint(-9.152978, 38.723002), 4326)::geography, 4, true, 2, 1, 2, 1.0, 171.9, 43.0, 'EUR', '2018-01-01'),
  (133, 134, 'Sunny Alcântara Studio with Shared Pool & Garden', 'Welcome to Alcântara Gardens – your peaceful retreat in the tranquil neighborhood of Alvito, Lisbon! Surrounded by greenery and sunshine, our bright studio offers the perfect escape for those seeking comfort and calm.', 'entire_place'::property_type, 'Lisbon', 'Alcntara', '119 Demo Street, Alcntara, Lisbon', 38.7098063, -9.1756528, ST_SetSRID(ST_MakePoint(-9.173183, 38.70644), 4326)::geography, 2, false, 0, 1, 1, 1.0, 111.5, 13.0, 'EUR', '2018-01-01'),
  (134, 135, 'Romantic flat in Alfama (Lisbon)', 'Romantic duplex apartment for two in the heart of Alfama, with a lovely view over the Tagus River. Includes living area, equipped kitchen, bathroom and an upstairs bedroom. Located on the 1st floor without elevator in a pedestrian area near the top of a small hill. The bedroom is accessed by narrow interior stairs typical of historic houses.', 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '10 Demo Street, Santa Maria Maior, Lisbon', 38.71147, -9.12931, ST_SetSRID(ST_MakePoint(-9.130803, 38.712906), 4326)::geography, 2, false, 0, 1, 1, 1.0, 124.5, 0.0, 'EUR', '2018-01-01'),
  (135, 136, 'NEW Studio! The Most Perfect Spot in Alfama', 'Wake up to the bell of Tram 28 and fall asleep to fado drifting up from the streets below. This brand-new studio sits in the beating heart of authentic Alfama, the true soul of real Lisbon. Walk on foot to: São Jorge Castle, Portas do Sol & Santa Luzia miradouros, cafés and restaurants. Guests call it “the most perfect spot in all of Alfama”. Stylish with hotel-standard bed and bath linens – the ideal romantic base to live like a local and feel the true magic of historic Lisbon every single day.', 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '116 Demo Street, Santa Maria Maior, Lisbon', 38.7131999, -9.1303624, ST_SetSRID(ST_MakePoint(-9.13076, 38.714197), 4326)::geography, 2, false, 0, 1, 1, 1.0, 135.17, 31.0, 'EUR', '2018-01-01'),
  (136, 137, 'Room 2+bath, in villa w/pool, À-das-Lebres, Loures', 'Double room on the 1st floor (no elevator) with private bathroom and AC in a villa with swimming pool, private parking and large outdoor space in Á-das-Lebres, 5min. from Loures and 15min. from Lisbon, by car.
The villa is located in a very quiet area and consists of 6 bedrooms and common areas such as a living room with TV, dining area, equipped kitchen, terrace, parking, garden and swimming pool.', 'private_room'::property_type, 'Lisbon', 'Santo Anto e So Julio do Tojal', '164 Demo Street, Santo Anto e So Julio do Tojal, Lisbon', 38.85361, -9.16652, ST_SetSRID(ST_MakePoint(-9.165957, 38.857863), 4326)::geography, 2, false, 0, 1, 2, 1.0, 84.0, 27.0, 'EUR', '2018-01-01'),
  (137, 138, 'Belém Charming House', 'Relax in this quiet and stylish space.

Cozy and friendly studio near Belém, 5-10 minutes'' walk from the Tagus riverbank, great museums and monuments, many restaurants and cafes, including the famous "Pasteis de Belém".

The house is a ground floor, fully equipped with air conditioning and easy and private access to the street; it has lots of light and is decorated with modern furniture.

The kitchen is fully equipped and the bathroom has all the necessary amenities.

Happy stay!', 'entire_place'::property_type, 'Lisbon', 'Alcntara', '170 Demo Street, Alcntara, Lisbon', 38.69994, -9.19198, ST_SetSRID(ST_MakePoint(-9.186426, 38.700954), 4326)::geography, 2, false, 0, 1, 1, 1.0, 110.0, 0.0, 'EUR', '2018-01-01'),
  (138, 139, 'Chic 2BR Oasis in Center-New &AC', 'Experience city living in this brand new, light-filled 2-bedroom apartment, perfectly located just a 3-minute walk from the iconic Arco da Rua Augusta. With top-quality finishes, central heating, and AC. Conveniently situated in the heart of the city with easy access to all public transportation. Plus, take advantage of our reception for luggage drop-off starting at 10am. Ideal for those who want to explore the city in style and comfort! Wifi: 1000mbps. 3rd floor with elevator .', 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '176 Demo Street, Santa Maria Maior, Lisbon', 38.70981, -9.13745, ST_SetSRID(ST_MakePoint(-9.133966, 38.710688), 4326)::geography, 6, true, 2, 2, 4, 1.0, 233.0, 42.0, 'EUR', '2018-01-01'),
  (139, 140, 'Twin Room | AC & Shared Bathroom | Saldanha II', 'Private twin room with two single beds, air conditioning and TV in a shared guesthouse near Saldanha. A practical choice for two friends, colleagues or relatives looking for a well-connected Lisbon base with access to a kitchen, living area and balcony.', 'private_room'::property_type, 'Lisbon', 'Avenidas Novas', '44 Demo Street, Avenidas Novas, Lisbon', 38.73287274655271, -9.149740368786622, ST_SetSRID(ST_MakePoint(-9.155142, 38.732368), 4326)::geography, 2, false, 0, 1, 2, 3.0, 92.0, 0.0, 'EUR', '2018-01-01'),
  (140, 141, 'Quarto bairro alto', 'This special place is close to everything, making it easy to plan your visit.', 'private_room'::property_type, 'Lisbon', 'Misericrdia', '93 Demo Street, Misericrdia, Lisbon', 38.7090546, -9.1457936, ST_SetSRID(ST_MakePoint(-9.148882, 38.708737), 4326)::geography, 1, false, 0, 1, 1, 1.0, 40.5, 0.0, 'EUR', '2018-01-01'),
  (141, 142, 'Lisbon Central Apartment', 'Apartment located in the city center, in Avenidas Novas, very close to El Corte Inglês, Gulbenkian museum, Eduardo VII park, Av. da Liberdade ideal for business or leisure travel.
The Building has 2 elevators is inserted in a street with several restaurants and cafes, pharmacy, gym and supermarket next door. Located next to several bus stops has metro station at 70m2 ..', 'entire_place'::property_type, 'Lisbon', 'Avenidas Novas', '40 Demo Street, Avenidas Novas, Lisbon', 38.74028, -9.14788, ST_SetSRID(ST_MakePoint(-9.145993, 38.743115), 4326)::geography, 4, false, 0, 2, 2, 1.0, 125.5, 34.0, 'EUR', '2018-01-01'),
  (142, 143, 'Castelo Blue Studio -Lisbon-', NULL, 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '30 Demo Street, Santa Maria Maior, Lisbon', 38.71309, -9.13593, ST_SetSRID(ST_MakePoint(-9.137125, 38.717279), 4326)::geography, 2, false, 0, 1, 1, 1.0, 91.0, 27.0, 'EUR', '2018-01-01'),
  (143, 144, '★★Relax and comfy - - Down Town - - Kings bed ★★', 'Accommodation is ideally located in the vibrant heart of downtown, just a short walk away from major attractions, metro and significant destinations. 
Relax in a cozy bedroom with a king-size bed and AC, ensuring your comfort throughout stay. 
You''ll have access to a marble SHARED BATHROOM, shared with just one other room (max.2 other guests) and cleaned daily for your convenience. 
Enjoy the fully equipped shared kitchen, offering everything you need to make your stay seamless and enjoyable.', 'private_room'::property_type, 'Lisbon', 'Santo Antnio', '92 Demo Street, Santo Antnio, Lisbon', 38.71999, -9.14328, ST_SetSRID(ST_MakePoint(-9.147162, 38.720677), 4326)::geography, 2, false, 0, 1, 1, 1.0, 110.0, 24.0, 'EUR', '2018-01-01'),
  (144, 145, 'Mini Hostel in Lisbon. Room 2 guest', 'It''s simple: a quiet place to stay in the city center. Very convenient location. Quiet and beautiful street. Lots of cafes and shops. Supermarket 50 meters away.', 'private_room'::property_type, 'Lisbon', 'Areeiro', '159 Demo Street, Areeiro, Lisbon', 38.738681520872575, -9.135068133473396, ST_SetSRID(ST_MakePoint(-9.134805, 38.740467), 4326)::geography, 2, true, 2, 1, 1, 3.0, 40.0, 9.0, 'EUR', '2018-01-01'),
  (145, 146, 'Spacious coastal house with garden and BBQ', 'Situated between Ribeira D´llhas and Coxos, Kodu Lodge has the perfect location for surfers and families who love to be close to the beach. 

With about 200 m2 of space over two floors, you will find the lodge relaxing and homely.

Your host lives in the same property with completely separate areas. The lodge guests have full privacy. 

“Kodu” meaning “home” in estonian, welcomes you to find your holiday home in Portugal.', 'entire_place'::property_type, 'Lisbon', 'Santo Isidoro', '177 Demo Street, Santo Isidoro, Lisbon', 38.99575, -9.412612, ST_SetSRID(ST_MakePoint(-9.412991, 38.993643), 4326)::geography, 8, false, 0, 4, 6, 2.0, 301.0, 0.0, 'EUR', '2018-01-01'),
  (146, 147, 'Casa do Pátio | 3 Bedrooms - Ponte Rol', 'Casa do Pátio is a family home located about 5 minutes from the city of Torres Vedras and only 15 minutes from the village of Santa Cruz.

This accommodation is pet friendly, so you can also bring your pet to spend a great family vacation.

Take the opportunity to relax and have your family meals in our marquee.', 'entire_place'::property_type, 'Lisbon', 'Ponte do Rol', '132 Demo Street, Ponte do Rol, Lisbon', 39.09238, -9.3207, ST_SetSRID(ST_MakePoint(-9.317876, 39.095258), 4326)::geography, 6, true, 2, 3, 4, 2.0, 129.0, 25.0, 'EUR', '2018-01-01'),
  (147, 148, 'Cozy Studio for 2 – Near Janelas Verdes', 'Discover this cozy Standard Studio at Mina Mina Mina, conveniently located near the centers of Santos and Alcântara, just a short distance from downtown Lisbon.

The studio features a kitchenette, perfect for preparing your meals, along with a coffee machine and kettle for a more comfortable start to your day.

It also offers a pleasant outdoor patio and common areas for those working from home. This versatile space is ideal for both work and leisure!', 'entire_place'::property_type, 'Lisbon', 'Estrela', '59 Demo Street, Estrela, Lisbon', 38.7047, -9.17208, ST_SetSRID(ST_MakePoint(-9.170205, 38.707973), 4326)::geography, 2, false, 0, 0, 1, 1.0, 152.0, 45.0, 'EUR', '2018-01-01'),
  (148, 149, 'Room 12 - Rossio', 'Offering private accommodations in the Lisbon city center, 3 minutes’ walking from Rossio Square, the 24-hour Welcome Guest House offers free WiFi access and shared kitchen facilities.Each accommodations features lockers, and all have access to shared bathroom facilities. A shared lounge area is available, where guests can socialize and read the newspapers.

A number of restaurants, cafes and mini-markets are within walking distance from the Welcome Guest House.', 'private_room'::property_type, 'Lisbon', 'Santa Maria Maior', '11 Demo Street, Santa Maria Maior, Lisbon', 38.71503, -9.13702, ST_SetSRID(ST_MakePoint(-9.133118, 38.716038), 4326)::geography, 2, false, 0, 1, 1, 3.5, 61.0, 12.0, 'EUR', '2018-01-01'),
  (149, 150, 'Villa Twin Norte - Golden Halcyon Ericeira Villas', 'Welcome to your private villa, the master bedroom , air conditioning, and large windows.Have a private ensuite bathroom.
Guests have access to an outdoor swimming pool and on-site parking (subject to availability).

Free WiFi is available.

This space accommodates up to 4 guests, occupancy price,with the option of a single or double bed in the living area. 

Breakfast is on request subject to availability extra payment at the property - only high season.', 'entire_place'::property_type, 'Lisbon', 'Ericeira', '107 Demo Street, Ericeira, Lisbon', 38.97367, -9.41366, ST_SetSRID(ST_MakePoint(-9.418061, 38.971142), 4326)::geography, 4, true, 2, 1, 3, 1.0, 106.5, 37.0, 'EUR', '2018-01-01'),
  (150, 151, 'Aconchego Cascais', 'Experience the best of Cascais in this spacious, centrally located house for up to 6 guests. Just a 5-minute walk to the beach and pier, it’s perfect for sun, sea, and strolls. Discover a fantastic variety of restaurants and charming cafes steps away, offering local flavors and cozy settings. With ample space for families or groups, this retreat combines coastal relaxation with the convenience of everything you need right around the corner.', 'entire_place'::property_type, 'Lisbon', 'Cascais e Estoril', '30 Demo Street, Cascais e Estoril, Lisbon', 38.6984413, -9.4232896, ST_SetSRID(ST_MakePoint(-9.423494, 38.697208), 4326)::geography, 6, false, 0, 2, 5, 1.0, 172.0, 0.0, 'EUR', '2018-01-01')
) AS v(id, host_id, title, description, property_type, city, neighborhood, address, latitude,
  longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds, bathrooms,
  price_per_night, cleaning_fee, currency, created_at)
JOIN cities c ON c.name = v.city;

INSERT INTO listings (id, host_id, title, description, property_type, city_id, neighborhood, address,
  latitude, longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds,
  bathrooms, price_per_night, cleaning_fee, currency, created_at)
OVERRIDING SYSTEM VALUE
SELECT v.id, v.host_id, v.title, v.description, v.property_type, c.id, v.neighborhood, v.address,
  v.latitude, v.longitude, v.public_location, v.max_guests, v.pets_allowed, v.max_pets, v.bedrooms,
  v.beds, v.bathrooms, v.price_per_night, v.cleaning_fee, v.currency, v.created_at::timestamptz
FROM (VALUES
  (151, 152, 'Apartamento acolhedor na ERICEIRA', 'Cozy apartment with great location, careful decoration with 2 bedrooms, living room, kitchen, bathroom and balcony with sea view.
Excellent sun exposure, East-West.
130 TV channels (Fiber), 200/100 Mbps Internet, Wireless access.
Equipped with all appliances, washing machine, dishes, microwave, coffee machine, refrigerator and oven. It can accommodate up to 4 people.
Close to the beaches and the village center (400 meters), supermarket nearby
Good access to the A21 and A8', 'entire_place'::property_type, 'Lisbon', 'Ericeira', '164 Demo Street, Ericeira, Lisbon', 38.96331, -9.413328, ST_SetSRID(ST_MakePoint(-9.418104, 38.964168), 4326)::geography, 4, false, 0, 2, 3, 1.0, 118.5, 15.0, 'EUR', '2018-01-01'),
  (152, 153, 'GreatStay Fanqueiros Guest House 1 Room 103', 'Independent Room full of light located in the heart of the city, in a 5 Rooms apartment, with private bathroom, equiped shared kitchen. O meu espaço é bom para casais e aventuras individuais. Note, that the room is located on the 3rd floor WITHOUT elevator.

LOCATION: 
2 minute walk to main square Praça do Comercio and Alfama, 5 min walk to Chiado and Bairro Alto. 
1 min to all transports (metro and Bus).', 'private_room'::property_type, 'Lisbon', 'Santa Maria Maior', '171 Demo Street, Santa Maria Maior, Lisbon', 38.7127, -9.13657, ST_SetSRID(ST_MakePoint(-9.137184, 38.713888), 4326)::geography, 2, false, 0, 1, 2, 1.0, 155.0, 0.0, 'EUR', '2018-01-01'),
  (153, 154, 'Heart of Bairro Alto - Lisbon Nightlife', 'Welcome to our simple and functional 1-bedroom apartment, located in the heart of Bairro Alto! Just a short walk from Príncipe Real and Chiado, this is the perfect base to explore Lisbon’s vibrant nightlife, enjoy authentic Portuguese cuisine, and discover a variety of local bars, restaurants, and shops.

Our apartment offers convenience and a genuine city experience. Step outside and feel the pulse of one of Lisbon’s most iconic neighborhoods!', 'entire_place'::property_type, 'Lisbon', 'Misericrdia', '136 Demo Street, Misericrdia, Lisbon', 38.71536, -9.14474, ST_SetSRID(ST_MakePoint(-9.145333, 38.719284), 4326)::geography, 2, false, 0, 1, 1, 1.0, 92.67, 16.0, 'EUR', '2018-01-01'),
  (154, 155, 'Alfama Dream Apartment 4 A', 'Fully renovated apartment in the typical neighborhood of Viktor, in a cozy and full of elegance, where the typical and traditional features of the neighborhood intersect with the comfort of a unique space with the surroundings of the Quintalinhos Patio.', 'entire_place'::property_type, 'Lisbon', 'So Vicente', '24 Demo Street, So Vicente, Lisbon', 38.71348, -9.13006, ST_SetSRID(ST_MakePoint(-9.125053, 38.711404), 4326)::geography, 4, false, 0, 1, 3, 1.0, 120.0, 0.0, 'EUR', '2018-01-01'),
  (155, 156, 'AnaCris'' Villa 1: cozy 2 Bedroom apt. with garden', 'Your Garden Retreat in Alcabideche. Escape to tranquility! The AnaCris'' Villa 1 apartment offers a full kitchen and direct, exclusive access to a relaxing garden, ideal for unwinding. Located in a quiet area, it''s just minutes from mystical Sintra, vibrant Cascais, and Estoril''s beaches. Easy access to explore cosmopolitan Lisbon. A perfect base to discover the best of the region, enjoying the silence and your private green space.', 'entire_place'::property_type, 'Lisbon', 'Alcabideche', '32 Demo Street, Alcabideche, Lisbon', 38.721257087993635, -9.37985859811306, ST_SetSRID(ST_MakePoint(-9.377811, 38.720329), 4326)::geography, 3, false, 0, 2, 2, 1.0, 73.2, 9.0, 'EUR', '2018-01-01'),
  (156, 157, '|NEW! Stylish Deluxe One Bedroom Apartment', 'Light traces and details of historic buildings surround the large windows in these designer-made apartments in the heart of Lisbon.

Our luxury apartments offer an unforgettable experience in one of the most vibrant and fascinating cities in the world! The proximity to Lisbon''s historic heart and our team''s commitment guarantee an intimate, exclusive stay unmatched by any other.

Add my listing to your wishlist by clicking the ❤ in the upper-right corner.', 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '139 Demo Street, Santa Maria Maior, Lisbon', 38.70961, -9.13802, ST_SetSRID(ST_MakePoint(-9.1406, 38.709745), 4326)::geography, 4, false, 0, 1, 1, 1.0, 268.0, 0.0, 'EUR', '2018-01-01'),
  (157, 158, 'Lapa Garden Studio with Swimming Pool', 'This modern, functional studio lets you enjoy Lisbon’s sunshine by the pool. It features a comfortable double bed, flat-screen TV, and high-speed fiber internet. The modern kitchenette is fully equipped with a stove, fridge, coffee machine, and all essentials for easy meals. It also includes a washing machine and dishwasher.
For stays longer than 28 days, a lodging contract is required under Portuguese law.', 'entire_place'::property_type, 'Lisbon', 'Estrela', '26 Demo Street, Estrela, Lisbon', 38.70688, -9.15926, ST_SetSRID(ST_MakePoint(-9.163718, 38.704608), 4326)::geography, 2, false, 0, 1, 1, 1.0, 140.67, 33.0, 'EUR', '2018-01-01'),
  (158, 159, 'Apartamento Bairro Alto – Centro de Lisboa', 'Unique experience in Parisa! Our magnificent 5-bedroom apartment, located in the prestigious Bairro Alto, offers the perfect setting for an unforgettable stay in the Portuguese capital. With its proximity to the stunning Miradouro São Pedro de Alcântara and the iconic Elevador de Santa Justa, you will be immersed in the beauty and history of this charming city. The apartment combines traditional charm with modern comfort, ideal for families or groups who want to explore Parisa in style', 'entire_place'::property_type, 'Lisbon', 'Misericrdia', '151 Demo Street, Misericrdia, Lisbon', 38.7145853, -9.1449179, ST_SetSRID(ST_MakePoint(-9.144336, 38.715571), 4326)::geography, 12, false, 0, 5, 7, 2.0, 299.0, 50.0, 'EUR', '2018-01-01'),
  (159, 160, 'J Home Prior Velho', 'JHome is located in Lisbon and has a garden and free WiFi. This air-conditioned vacation home comes with 3 separate bedrooms, a fully equipped kitchen, and 2 bathrooms.

Very close to Lisbon Airport, only 4.6 km from Lisbon East Station, this holiday home is 10 km from Miradouro da Senhora do Monte, 10 km from the National Theater of Dona Maria II, 5.8 km from Lisbon Oceanarium, and 9.4 km from Rossio.

I hope you and your family have wonderful memories here.', 'entire_place'::property_type, 'Lisbon', 'Sacavm e Prior Velho', '64 Demo Street, Sacavm e Prior Velho, Lisbon', 38.79034141148928, -9.120675399899483, ST_SetSRID(ST_MakePoint(-9.121373, 38.791706), 4326)::geography, 6, true, 2, 3, 3, 2.0, 230.0, 29.0, 'EUR', '2018-01-01'),
  (160, 161, 'Great View Pool Villa by S Pedro do Estoril Beach', 'A four bedroom house in a very quiet area with amazing views of the "Serra de Sintra". 10 mins walk from S. Pedro do Estoril beach (one of the best in Estoril Coast) and 7 mins walk from S. Pedro do Estoril Train Station (direct trains to Lisbon and Cascais). Big Swimming Pool. Plenty of space to relax and enjoy the sun and amazing views. Exterior WC, Al Fresco Shower and Kitchen with BBQ and Table Tennis. Private Parking inside the Villa for up to three cars.', 'entire_place'::property_type, 'Lisbon', 'Carcavelos e Parede', '33 Demo Street, Carcavelos e Parede, Lisbon', 38.69944, -9.36611, ST_SetSRID(ST_MakePoint(-9.364906, 38.699629), 4326)::geography, 8, false, 0, 4, 5, 4.0, 687.8, 177.0, 'EUR', '2018-01-01'),
  (161, 162, 'Atlantic Apartments Lisbon 1B', 'This elegant apartment, located in Algés, offers the perfect balance between comfort, location and practicality. With modern and functional decor, it is the ideal choice for couples or families who want to explore the region with ease.

The space has been carefully equipped and designed to provide a quiet and pleasant stay.', 'entire_place'::property_type, 'Lisbon', 'Algs, Linda-a-Velha e Cruz Quebrada-Dafundo', '49 Demo Street, Algs, Linda-a-Velha e Cruz Quebrada-Dafundo, Lisbon', 38.69972, -9.22947, ST_SetSRID(ST_MakePoint(-9.225949, 38.699315), 4326)::geography, 4, false, 0, 1, 2, 1.0, 156.0, 16.0, 'EUR', '2018-01-01'),
  (162, 163, 'Charming 2-Story Apt Near Beach w/ Pool & Patio', 'Bright 2-bed duplex in Villa Sol Nascente. Bedrooms with AC and blackout curtains; charming, fully equipped kitchen with private balcony; airy upstairs lounge with smart TV and generous seating. Shared outside areas with brand-new sunset deck, plunge pool and sun-loungers; a sunny patio with seating; secure, gated parking on the fully fenced property. 5-min drive to Praia da Areia Branca surf beach, cafés, bars & restaurants; wineries, clifftop hikes and Lisbon day-trips are within easy reach.', 'entire_place'::property_type, 'Lisbon', 'Lourinh e Atalaia', '104 Demo Street, Lourinh e Atalaia, Lisbon', 39.2589899, -9.316532, ST_SetSRID(ST_MakePoint(-9.313537, 39.25743), 4326)::geography, 4, true, 2, 2, 2, 1.0, 84.75, 13.0, 'EUR', '2018-01-01'),
  (163, 164, 'Sweet Spot Beach - Room B3', 'Private room in a charming old house, restored to create a welcoming Airbnb experience while preserving its original character. 

In this cozy room (B3), you can choose between 2 single beds or 1 double bed. 
Plus, you''ll have the added convenience of a private ensuite bathroom – no need to share!

Our prime location offers quick access to Cascais'' best beaches (the nearest one is just 300m away). 

The train station is only 100 meters away, providing a quick 30min ride to Lisbon downtown.', 'private_room'::property_type, 'Lisbon', 'Cascais e Estoril', '108 Demo Street, Cascais e Estoril, Lisbon', 38.69532, -9.3728, ST_SetSRID(ST_MakePoint(-9.369207, 38.698137), 4326)::geography, 2, false, 0, 1, 3, 1.0, 76.0, 0.0, 'EUR', '2018-01-01'),
  (164, 165, 'Top Floor, 2 Balconies & City View 4C', 'Rosa Do Rosa Rosa is solely responsible for offering this listing on Airbnb, and they host as a business. For more legal information, visit our Help Center.

Business name: Parallel Bubbles
Business registry: Business register
NIPC number: PT510964710
Email: booking@portasdosol.pt
Phone: +351 917 723 716
Address: Rua Tenente Valadim 6B, 1350-319, Lisboa, Portugal
To help protect yourself from fraud, always use Airbnb to send money and communicate with hosts.', 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '33 Demo Street, Santa Maria Maior, Lisbon', 38.713836669921875, -9.130849838256836, ST_SetSRID(ST_MakePoint(-9.128819, 38.713807), 4326)::geography, 3, false, 0, 1, 2, 1.0, 194.0, 39.0, 'EUR', '2018-01-01'),
  (165, 166, 'NEW! Sunny & spacious apartment w/ great balcony', 'The apartment is perfect for those who want to explore and experience the fantastic city of Lisbon like a local.

Central, spacious, with lots of sun and light, and an incredible balcony.

It is also prepared for longer stays, with an office, fully equipped kitchen and everything you need for day-to-day life.

The apartment was our home for many years and we loved every moment we lived there! We hope you like it too and make the most of it!', 'entire_place'::property_type, 'Lisbon', 'Campo de Ourique', '64 Demo Street, Campo de Ourique, Lisbon', 38.71912, -9.16115, ST_SetSRID(ST_MakePoint(-9.156756, 38.719534), 4326)::geography, 5, true, 2, 2, 3, 1.0, 253.7, 0.0, 'EUR', '2018-01-01'),
  (166, 167, 'Contemporay charming Duplex VILA BERTA', 'Brand new Luxurious contemporary DUPLEX , with terrass, 2 steps from Graça square, Tramway 28, Belvedere Graça, Saint Vincente monastery, shops and restaurants.
On Vila Berta street
Professional WIFI FIBER', 'entire_place'::property_type, 'Lisbon', 'So Vicente', '54 Demo Street, So Vicente, Lisbon', 38.71692, -9.12812, ST_SetSRID(ST_MakePoint(-9.12809, 38.718223), 4326)::geography, 5, true, 2, 2, 2, 1.5, 201.0, 34.0, 'EUR', '2018-01-01'),
  (167, 168, 'Estoril Nest – Walk to the Beach', '💙 Welcome to your little retreat just 3 minutes from the beach! This studio offers comfort, and all the amenities you need to feel at home. 

Lisbon is at a 25 min train trip!', 'entire_place'::property_type, 'Lisbon', 'Cascais e Estoril', '32 Demo Street, Cascais e Estoril, Lisbon', 38.70280622163902, -9.38636356291374, ST_SetSRID(ST_MakePoint(-9.387828, 38.701953), 4326)::geography, 4, false, 0, 1, 1, 1.0, 100.0, 21.0, 'EUR', '2018-01-01'),
  (168, 169, 'Lovely house in Sintra', 'Private small house and garden with a view to the sea at end of village lane. 
About 10 min. walk from the village of Almoçageme, with grocery stores, hairdresser, laundry, restaurants and cafes.
About 15 min. walk from the village of Penedo and 25 min. walk from Adraga beach. you are 15 min. by car from Sintra, 25 min. from Cascais and 40 min. from the airport.
In the beautiful surroundings it is possible to take long hikes in the green forest or at the top of the stunning cliffs .', 'entire_place'::property_type, 'Lisbon', 'Colares', '38 Demo Street, Colares, Lisbon', 38.79348, -9.46332, ST_SetSRID(ST_MakePoint(-9.466601, 38.795536), 4326)::geography, 3, true, 2, 1, 3, 1.0, 108.33, 18.0, 'EUR', '2018-01-01'),
  (169, 170, 'Bright minimalist room + views of the Tejo River', 'Discover the charm of Lisbon from this cozy and inviting room in one of the city’s most central areas! Close to public transport, cafés, supermarkets and Lisbon’s iconic neighborhoods, this space offers comfort and convenience for your stay.

Relax in a welcoming environment after exploring the city’s beautiful streets and viewpoints. Whether for tourism, work, or a quick getaway, this location places you in the heart of authentic Lisbon.

✨ Book your stay now and experience Lisbon like a local!', 'private_room'::property_type, 'Lisbon', 'Penha de Frana', '119 Demo Street, Penha de Frana, Lisbon', 38.733589046177435, -9.12667516618967, ST_SetSRID(ST_MakePoint(-9.126649, 38.734663), 4326)::geography, 2, false, 0, 1, 1, 1.0, 43.2, 7.0, 'EUR', '2018-01-01'),
  (170, 171, 'Remote Work–Ready Room • AC • Shared Home', 'A remote work–ready shared home ideal for digital nomads, freelancers, and extended travelers. Your private room includes a desk, ergonomic chair, and AC. Shared areas offer space to work or relax — and often attract guests with similar lifestyles, whether you''re here to focus, recharge, or explore Lisbon at your pace.', 'private_room'::property_type, 'Lisbon', 'Arroios', '73 Demo Street, Arroios, Lisbon', 38.73314, -9.13812, ST_SetSRID(ST_MakePoint(-9.136505, 38.73284), 4326)::geography, 2, false, 0, 1, 1, 1.0, 90.5, 14.0, 'EUR', '2018-01-01'),
  (171, 172, 'Cantinho Da Lapa- Lovely, Quiet, Centrally-Located Apartment', 'Open the floor-to-ceiling windows to access the second-story Juliet balcony, with its view of the tiled buildings that line this historic street. The interior blends classic charm, such as hardwood floors, with modern touches like a double-head rain shower. Relax in the open plan living room or the large airy main bedroom. It is the perfect place to return to at the end of the day or sit back and enjoy the view.

Recommendations will be provided on what to see and do in and around Lisbon upon arrival.

Located on the second level, the floor to ceiling windows look out onto colourfully tiled buildings, characteristic of Lisbon. The spacious home is both bright and cozy, with hardwood floors throughout. The apartment is comprised of 2 bedrooms, a large bathroom with a double shower, a fully equipped kitchenette and a living room. The bedrooms can accommodate 4 guests, one bedroom has a queen-sized bed and desk, while the other contains two single beds. The kitchenette', 'entire_place'::property_type, 'Lisbon', 'Arroios', '165 Demo Street, Arroios, Lisbon', 38.72738, -9.14277, ST_SetSRID(ST_MakePoint(-9.139623, 38.725646), 4326)::geography, 4, false, 0, 2, 3, 1.0, 160.59, 37.0, 'EUR', '2018-01-01'),
  (172, 173, '"Window to the Valley" - Ericeira', '“Window to the Valley” – A Peaceful Family Home in the Countryside

A welcoming family home set in a peaceful rural area, just 6 km from the famous Ribeira d’Ilhas beach and 8 km from the centre of Leila.', 'entire_place'::property_type, 'Lisbon', 'Santo Isidoro', '166 Demo Street, Santo Isidoro, Lisbon', 38.988774, -9.360285, ST_SetSRID(ST_MakePoint(-9.362024, 38.989041), 4326)::geography, 6, true, 2, 3, 3, 3.0, 196.0, 41.0, 'EUR', '2018-01-01'),
  (173, 174, 'Drop In Estoril - Family room', 'Bright and spacious room with beautiful views of the Sintra mountains and Cascais skyline. Located in a shared house with seven bedrooms. Guests have access to one shared bathroom, a separate toilet, a fully equipped kitchen, a sheltered patio, and a cozy garden with a hammock.

The supermarket, train station, and beach are all within 1 km. From the nearest beach, a scenic seaside promenade leads to Cascais, with cafés, restaurants, and beautiful beaches along the way.', 'private_room'::property_type, 'Lisbon', 'Cascais e Estoril', '177 Demo Street, Cascais e Estoril, Lisbon', 38.70745, -9.38956, ST_SetSRID(ST_MakePoint(-9.390177, 38.703993), 4326)::geography, 2, false, 0, 1, 1, 1.5, 55.0, 7.0, 'EUR', '2018-01-01'),
  (174, 175, 'Franks House - Belem- Ponte 25 de Abril (Q2)', 'Reza is solely responsible for offering this listing on Airbnb, and they host as a business. For more legal information, visit our Help Center.

Business name: Franklin & Alves LDA
Business registry: Business register
NIPC number: 1553-3006-4702
Email: becodabicaalojamentos@gmail.com
Phone: +351 913 933 577
Address: Beco dos Aciprestes 9 Andar 1, 1200, Lisboa, Portugal
To help protect yourself from fraud, always use Airbnb to send money and communicate with hosts.', 'private_room'::property_type, 'Lisbon', 'Belm', '62 Demo Street, Belm, Lisbon', 38.69522, -9.2132, ST_SetSRID(ST_MakePoint(-9.215691, 38.69742), 4326)::geography, 2, false, 0, 1, 1, 2.0, 40.0, 4.0, 'EUR', '2018-01-01'),
  (175, 176, 'FLH Augusta''s Arch Design Apartment', 'The apartment in Lisbon has 2 bedrooms and has capacity for 4 people.

The apartment is 98 m².

The accommodation is equipped with the following items: iron, internet (Wi-Fi), air-conditioned, TV.

In the kitchen, refrigerator, microwave, freezer, washing machine, dishwasher, dishes/cutlery, kitchen utensils, coffee machine and toaster are provided.', 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '47 Demo Street, Santa Maria Maior, Lisbon', 38.708839863149514, -9.13740818870969, ST_SetSRID(ST_MakePoint(-9.139144, 38.711474), 4326)::geography, 4, false, 0, 2, 3, 2.5, 339.0, 106.0, 'EUR', '2018-01-01'),
  (176, 177, 'Bel appartement en plein cœur de Lisbonne', NULL, 'entire_place'::property_type, 'Lisbon', 'Misericrdia', '1 Demo Street, Misericrdia, Lisbon', 38.70861, -9.14648, ST_SetSRID(ST_MakePoint(-9.148013, 38.705981), 4326)::geography, 3, false, 0, 1, 3, 1.0, 161.0, 44.0, 'EUR', '2018-01-01'),
  (177, 178, 'Room 3a - 5', 'A beautiful apartment consisting of 5 bedrooms, 2 bathrooms, a kitchen and a spacious living and dining room, located on the third floor of a building. A completely pleasant, clean and airy apartment.
It is situated in an area with a lot of commerce and a lot of life, with several transportation options at the door. Like buses and subway.
You can take a 15-minute walk and be in the historic area of Lisbon (downtown). We already have air conditioning for better comfort.', 'private_room'::property_type, 'Lisbon', 'Arroios', '161 Demo Street, Arroios, Lisbon', 38.73255, -9.13293, ST_SetSRID(ST_MakePoint(-9.135434, 38.729303), 4326)::geography, 3, true, 2, 1, 3, 2.0, 80.0, 13.0, 'EUR', '2018-01-01'),
  (178, 179, 'Sleep&Surf - Ericeira - Portugal', 'Spacious and comfortable house, ideal for families or groups of up to 10 people, is a 10-minute walk from the center of Ericeira and São Sebastião beach (750m). Nearby is Ribeira d''Ilhas Beach-World Surf Reserve, several Portuguese restaurants and large supermarkets, Aldi, Lidl, Continente, Intermarché. NOTE: The pool belongs to the condominium and not only to Sleep & Surf Ericeira. The use of the swimming pool is at your own risk.', 'entire_place'::property_type, 'Lisbon', 'Ericeira', '63 Demo Street, Ericeira, Lisbon', 38.9697, -9.41522, ST_SetSRID(ST_MakePoint(-9.412072, 38.970559), 4326)::geography, 10, true, 2, 4, 7, 4.0, 482.0, 0.0, 'EUR', '2018-01-01'),
  (179, 180, 'Reef Bungalow Lux/8 - T1', 'Welcome to paradise! Our charming wooden bungalow in Ericeira is situated in a pine forest in front of the sea, in the middle of the world surfing reserve. You''ll be surrounded by the natural beauty of the forest and breathtaking views of the ocean.', 'entire_place'::property_type, 'Lisbon', 'Ericeira', '177 Demo Street, Ericeira, Lisbon', 38.97743, -9.41883, ST_SetSRID(ST_MakePoint(-9.420033, 38.975169), 4326)::geography, 4, false, 0, 1, 3, 1.0, 148.67, 33.0, 'EUR', '2018-01-01'),
  (180, 181, 'Chic Flat by Praça das Flores & Príncipe Real', 'Stylish and cozy attic flat in one of Lisbon’s most charming neighborhoods, just steps from Praça das Flores, Príncipe Real and Bairro Alto. Surrounded by some of the city’s best cafés, restaurants, wine bars and local shops, it’s perfectly located for exploring Lisbon on foot while enjoying the authentic atmosphere of one of the city’s trendiest residential areas.', 'entire_place'::property_type, 'Lisbon', 'Misericrdia', '19 Demo Street, Misericrdia, Lisbon', 38.71473, -9.1520653, ST_SetSRID(ST_MakePoint(-9.152143, 38.717109), 4326)::geography, 2, false, 0, 1, 1, 1.0, 183.0, 28.0, 'EUR', '2018-01-01'),
  (181, 182, 'Sunny Príncipe Real Duplex w/ Terrace & River View', 'Experience Lisbon from this luminous 3-bedroom duplex in trendy Principe Real. The highlight is a stunning, sun-drenched terrace with frontal river, city, and bridge views. Comfortably accommodating up to 8 guests, this stylish apartment is just minutes from Bairro Alto''s nightlife and chic shopping. Perfect for families or groups seeking a central, scenic retreat with amazing views. Fully equipped. Central. No Elevator. LvPremier PREAL PI1', 'entire_place'::property_type, 'Lisbon', 'Misericrdia', '25 Demo Street, Misericrdia, Lisbon', 38.71614, -9.15307, ST_SetSRID(ST_MakePoint(-9.148609, 38.716839), 4326)::geography, 8, false, 0, 3, 8, 2.0, 389.0, 0.0, 'EUR', '2018-01-01'),
  (182, 183, 'Double Room-Da Vinci Shared Flat', 'Da Vinci Flat offers free Wi-Fi and accommodation in Lisbon, in the Estefânia and Arroios area, where the residential mixes with the commercial. 
Av. Pascoal de Melo has traditional stores and cafés, while Av. Almirante Reis reflects current trends. 
The area is marked by a strong sense of community. 

Welcome to Estefânia & Arroios!', 'private_room'::property_type, 'Lisbon', 'Arroios', '24 Demo Street, Arroios, Lisbon', 38.72794, -9.13536, ST_SetSRID(ST_MakePoint(-9.138627, 38.731146), 4326)::geography, 2, false, 0, 7, 1, 1.5, 33.3, 9.0, 'EUR', '2018-01-01'),
  (183, 184, 'Apartment in Principe Real Lisbon Center', 'In the heart of the trendiest neighbourhood of Lisbon, Príncipe Real, this Amazing Apartment offers the comfort you need to get the most wonderfull holidays in Lisbon. It is spacious, very well decorated with all you need for a confortable holidays ( flat televisions, sound column, good sofá and beds and the most importante it is very central, walking distance to the main spots ).
Two bedrooms , one with double bed and the other with 2 single beds. 1 bathroom with shower and one small bathroom .', 'entire_place'::property_type, 'Lisbon', 'Santo Antnio', '162 Demo Street, Santo Antnio, Lisbon', 38.71791, -9.15055, ST_SetSRID(ST_MakePoint(-9.151885, 38.716445), 4326)::geography, 4, false, 0, 2, 3, 1.5, 312.0, 0.0, 'EUR', '2018-01-01'),
  (184, 185, 'Charmoso T1 na Praça das Flores – Príncipe Real', 'Comfortable T1 located in Praça das Flores, one of the trendiest areas of Lisbon. Ideal for people who value a central, safe neighborhood with a great quality of life.

The apartment is perfect for studying, resting and living in the city. Surrounded by cafes, supermarkets, restaurants and green spaces, with excellent transport links to universities and central areas.

A great option for those looking for comfort, location and a youthful atmosphere, all within walking distance.', 'entire_place'::property_type, 'Lisbon', 'Santo Antnio', '126 Demo Street, Santo Antnio, Lisbon', 38.7157935, -9.1517494, ST_SetSRID(ST_MakePoint(-9.156347, 38.71531), 4326)::geography, 2, false, 0, 1, 1, 1.0, 191.0, 0.0, 'EUR', '2018-01-01'),
  (185, 186, 'Sobral GuestHouse', 'Sobral Guesthouse, in Ericeira, is the ideal choice for those looking for tranquility near the sea. Located just minutes from the center and very close to Ribeira d''Ilhas, it has a spacious terrace, a balcony with a sunset view, parking, and is fully equipped. Children are welcome, and the house has two cribs for the comfort of families.', 'entire_place'::property_type, 'Lisbon', 'Ericeira', '72 Demo Street, Ericeira, Lisbon', 38.98383, -9.41322, ST_SetSRID(ST_MakePoint(-9.414972, 38.986495), 4326)::geography, 5, false, 0, 2, 3, 1.5, 197.75, 0.0, 'EUR', '2018-01-01'),
  (186, 187, 'La Scala Sea Views - by Portugal Portfolio', 'Ocean facing one bedroom with large balcony that extends over the entire frontage of the apartment. Located in Gandarinha, the most upmarket part of Cascais overlooking the ocean and offering sun soaked rooms from morning till sunset. It is located in a luxury condominium offering a heated indoor pool as well as an outdoor swimming pool (not heated), a fully equipped gym and spa facilities. Beautiful gardens and lots of open space will make you never want to leave this little oasis.', 'entire_place'::property_type, 'Lisbon', 'Cascais e Estoril', '6 Demo Street, Cascais e Estoril, Lisbon', 38.69602584838867, -9.43295669555664, ST_SetSRID(ST_MakePoint(-9.434104, 38.695155), 4326)::geography, 4, false, 0, 1, 2, 2.0, 201.0, 21.0, 'EUR', '2018-01-01'),
  (187, 188, 'Elegant Chiado Rooftop • Tagus View • 3BR • AC', '🌟 CHIADO RIVER VIEW DELUXE APARTMENT – TAGUS VIEWS IN THE HEART OF LISBON

Wake up with panoramic views over the Tagus River in this elegant apartment in Chiado, one of Lisbon’s most iconic areas.

Set on the top floor of an 18th-century Pombaline building, it combines historic charm, modern comfort and a privileged location.

Spacious and bright, it is ideal for families, couples, groups of friends and business stays.', 'entire_place'::property_type, 'Lisbon', 'Misericrdia', '34 Demo Street, Misericrdia, Lisbon', 38.70791, -9.14184, ST_SetSRID(ST_MakePoint(-9.139854, 38.708317), 4326)::geography, 6, true, 2, 3, 3, 2.0, 695.4, 197.0, 'EUR', '2018-01-01'),
  (188, 189, 'Sunny apartment city center (Avenida da Liberdade)', 'GREAT LOCATION!
Located at 300m from Avenida da Liberdade. Quiet neighborhood with everything you will need. Comfortable apartment refurbished. It''s close to every touristic attraction in the city center, such as Rossio, Praça do Comércio, Chiado and Bairro Alto.', 'entire_place'::property_type, 'Lisbon', 'Santo Antnio', '53 Demo Street, Santo Antnio, Lisbon', 38.72103, -9.14169, ST_SetSRID(ST_MakePoint(-9.142578, 38.722156), 4326)::geography, 4, false, 0, 1, 2, 1.0, 117.0, 0.0, 'EUR', '2018-01-01'),
  (189, 190, 'Casinha de campo - natureza e cavalos', 'Ana dos Ana is located in Arruda dos Vinhos, 30 minutes from Lisbon.
A retreat for a getaway for two, ideal for relaxing

It is a little house in the countryside, with a breathtaking view, which provides a unique experience of rest and vitality, ideal for lovers of horses and nature

The accommodation has a double bed, bathroom, kitchenette, air conditioning, television, Wi-Fi, barbecue facilities, saltwater pool and parking', 'entire_place'::property_type, 'Lisbon', 'Santiago dos Velhos', '97 Demo Street, Santiago dos Velhos, Lisbon', 38.987735748291016, -9.10795783996582, ST_SetSRID(ST_MakePoint(-9.103744, 38.989841), 4326)::geography, 2, false, 0, 1, 1, 1.0, 93.0, 25.0, 'EUR', '2018-01-01'),
  (190, 191, 'Santa Beach House - Shared Room', 'Located in the heart of Santa Cruz, Santa Beach Hostel is a few footsteps away from several beaches.

Born in a family house, it embodies the pleasure for the beach, travelling, receiving friends and making new friendships.

We have garage available for bikes', 'shared_room'::property_type, 'Lisbon', 'Silveira', '19 Demo Street, Silveira, Lisbon', 39.1335, -9.37923, ST_SetSRID(ST_MakePoint(-9.377933, 39.13416), 4326)::geography, 6, false, 0, 1, 6, 2.0, 29.0, 6.0, 'EUR', '2018-01-01'),
  (191, 192, 'Charming cottage, pool & garden by Guincho beach', 'Secluded retreat: Beautiful one-bedroom cottage with fenced pool, pateo and lush garden 5 min drive from iconic Guincho beach and 10 min drive from wonderful hiking trails of Sintra-Cascais Natural Park. Perfect for families, the bedroom features a queen-size bed with a pull-out single bed (ideal for a baby or child). The living room includes a sofa bed suitable for up to 2 children or 1 adult. 2 bicycles are available, 1 with toddler seat. Perfect also for couples or a peaceful coastal escape.', 'entire_place'::property_type, 'Lisbon', 'Cascais e Estoril', '174 Demo Street, Cascais e Estoril, Lisbon', 38.72971, -9.44733, ST_SetSRID(ST_MakePoint(-9.451654, 38.728928), 4326)::geography, 5, false, 0, 1, 2, 1.0, 168.0, 24.0, 'EUR', '2018-01-01'),
  (192, 193, 'Aeroporto Lisboa - 5 min', 'Private room with double bed, kitchenette, private bathroom, television and air conditioning. Great space for those who want to spend quiet nights 5 minutes from Lisbon airport.', 'entire_place'::property_type, 'Lisbon', 'Olivais', '146 Demo Street, Olivais, Lisbon', 38.7769136, -9.119524199999999, ST_SetSRID(ST_MakePoint(-9.120702, 38.772527), 4326)::geography, 2, false, 0, 1, 1, 1.0, 98.0, 14.0, 'EUR', '2018-01-01'),
  (193, 136, 'Lisbon Alfama Flat Overlooking Tagus River', 'Lisbon, between Tagus river and Alfama. Renovated apartment with a unique view of the Tagus River. Two minutes walking distance from Lisbon Sé Cathedral. Enjoy the buzz of Lisbon''s oldest distric!

Wifi: AlfamaTagus
Password: lisbonalfamatagus', 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '81 Demo Street, Santa Maria Maior, Lisbon', 38.70957, -9.13081, ST_SetSRID(ST_MakePoint(-9.129117, 38.705895), 4326)::geography, 4, false, 0, 2, 3, 2.0, 308.33, 0.0, 'EUR', '2018-01-01'),
  (194, 194, 'EZFlats Cascais Bay 1', 'Small apartment very close to the beach, within Cascais historic center, Sacolinha patisserie, Largo Luís de Camões, station that takes you Lisbon & Sintra, touristic activities, right within the historic village. Apartment, has a double-bed and a sofa bed, sits in a quiet road, but close to the trendiest restaurants and walking distance to virtually everywhere. My place is good for couples, business travelers and young travelers or children using the extra sofa bed.', 'entire_place'::property_type, 'Lisbon', 'Cascais e Estoril', '149 Demo Street, Cascais e Estoril, Lisbon', 38.69708, -9.42169, ST_SetSRID(ST_MakePoint(-9.423286, 38.699613), 4326)::geography, 3, false, 0, 1, 2, 1.0, 179.4, 35.0, 'EUR', '2018-01-01'),
  (195, 195, 'Sintra Cottage', 'Relax with the whole family at this peaceful place to stay. Old family house that has been prepared to accommodate 4 people. Keeping the old style, much of the furniture was recovered to offer a connection between the family''s furniture and adapt them to modern life without losing the charm of other times. An outdoor space that invites you to relax, contemplating the Serra and its monuments, reading a book or having a refreshing drink, while preparing the itinerary for the next day', 'entire_place'::property_type, 'Lisbon', 'S.Maria, S.Miguel, S.Martinho, S.Pedro Penaferrim', '102 Demo Street, S.Maria, S.Miguel, S.Martinho, S.Pedro Penaferrim, Lisbon', 38.81428344206954, -9.390317054122972, ST_SetSRID(ST_MakePoint(-9.392199, 38.810585), 4326)::geography, 5, false, 0, 2, 2, 2.0, 156.5, 37.0, 'EUR', '2018-01-01'),
  (196, 196, 'Stylish Alfama Loft D • Walk to viewpoints • AC', 'Alfama is one of the most typical neighborhoods in Lisbon, quiet and family-friendly, it is a unique experience!
From the apartment, you can explore the entire pedestrian area of Alfama on foot and visit São Jorge Castle, the Santa Luzia viewpoint, Lisbon Cathedral and catch the famous Tram 28.', 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '13 Demo Street, Santa Maria Maior, Lisbon', 38.711137720288924, -9.129896640777579, ST_SetSRID(ST_MakePoint(-9.128314, 38.712351), 4326)::geography, 2, false, 0, 1, 1, 1.0, 178.0, 42.0, 'EUR', '2018-01-01'),
  (197, 197, 'Luxury 2 Bedroom Beach Oasis', 'Enjoy the best of Cascais at this centrally-located apartment next to the beach and best restaurants in town.', 'entire_place'::property_type, 'Lisbon', 'Cascais e Estoril', '67 Demo Street, Cascais e Estoril, Lisbon', 38.69823019602256, -9.421493316979195, ST_SetSRID(ST_MakePoint(-9.419515, 38.700548), 4326)::geography, 4, false, 0, 2, 4, 1.0, 414.67, 50.0, 'EUR', '2018-01-01'),
  (198, 198, 'Top-Floor Lisbon Studio | Peaceful & Central', 'Welcome to the heart of Lisbon! This cosy apartment is located on a pedestrian street in Baixa, between Praça dos Restauradores and Rossio Square — in the absolute centre of the city, with everything within walking distance. From here, you can walk to almost everything: St. George''s Castle, Alfama, Bairro Alto, Mouraria, Chiado, Cais do Sodré and Avenida da Liberdade. Great transport links will also take you to Sintra, Belém, Cascais or Almada (Cristo Rei).
Come and discover our city. See you!', 'entire_place'::property_type, 'Lisbon', 'Santa Maria Maior', '179 Demo Street, Santa Maria Maior, Lisbon', 38.71555, -9.13983, ST_SetSRID(ST_MakePoint(-9.141568, 38.715898), 4326)::geography, 4, false, 0, 1, 2, 1.0, 123.5, 38.0, 'EUR', '2018-01-01'),
  (199, 199, 'Elegant Flat with AC by the Metro', 'Discover Lisbon from this well-located 2-bedroom apartment in the Anjos neighbourhood, right next to Anjos metro station, the apartment comfortably accommodates up to 5 guests.

The space includes air conditioning in all rooms, fast Wi-Fi, and a washer and dryer inside the apartment. Its central location makes it easy to explore Lisbon using public transport while staying in a lively, authentic area of the city.

A practical and comfortable base for couples, friends, or small families.', 'entire_place'::property_type, 'Lisbon', 'Arroios', '118 Demo Street, Arroios, Lisbon', 38.7262, -9.13586, ST_SetSRID(ST_MakePoint(-9.137378, 38.726276), 4326)::geography, 3, true, 2, 2, 3, 1.0, 117.5, 30.0, 'EUR', '2018-01-01'),
  (200, 200, 'Charming Duplex in Lisbon | Chiado & Bairro Alto', 'Chloe is solely responsible for offering this listing on Airbnb, and they host as an individual.

Consumer protection laws don’t apply to reservations hosted by individuals, but every Airbnb reservation comes with 24/7 customer support. For more information, visit our Help Center.', 'entire_place'::property_type, 'Lisbon', 'Misericrdia', '171 Demo Street, Misericrdia, Lisbon', 38.710838317871094, -9.150282859802246, ST_SetSRID(ST_MakePoint(-9.150077, 38.711764), 4326)::geography, 3, false, 0, 1, 2, 1.0, 143.5, 0.0, 'EUR', '2018-01-01')
) AS v(id, host_id, title, description, property_type, city, neighborhood, address, latitude,
  longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds, bathrooms,
  price_per_night, cleaning_fee, currency, created_at)
JOIN cities c ON c.name = v.city;

INSERT INTO listings (id, host_id, title, description, property_type, city_id, neighborhood, address,
  latitude, longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds,
  bathrooms, price_per_night, cleaning_fee, currency, created_at)
OVERRIDING SYSTEM VALUE
SELECT v.id, v.host_id, v.title, v.description, v.property_type, c.id, v.neighborhood, v.address,
  v.latitude, v.longitude, v.public_location, v.max_guests, v.pets_allowed, v.max_pets, v.bedrooms,
  v.beds, v.bathrooms, v.price_per_night, v.cleaning_fee, v.currency, v.created_at::timestamptz
FROM (VALUES
  (201, 201, 'A Casa da Benvinda', 'In the heart of Bairro Alto, in a building that belongs to my family for more than two centuries, this typical Pombaline ground floor flat maintains all its original characteristics with low ceilings and cozy rooms. 
It has been restored keeping its original traces. Decorated with personal furniture and objects, it offers a sense of familiarity and comfort, you will feel that you are living like a local "Lisboeta".', 'entire_place'::property_type, 'Lisbon', 'Misericrdia', '49 Demo Street, Misericrdia, Lisbon', 38.71487, -9.14752, ST_SetSRID(ST_MakePoint(-9.14561, 38.717478), 4326)::geography, 4, false, 0, 2, 3, 1.0, 147.0, 44.0, 'EUR', '2018-01-01'),
  (202, 202, 'GuestReady - Charme Rouge Lisbon', 'This one-bedroom apartment in Lisbon is perfect for guests looking to stay in the city centre. It has everything you need for a pleasant stay. The property is close to various attractions, good restaurants and shops, and the Arroios station is just 7 minutes away, so guests can easily travel and explore the city!', 'entire_place'::property_type, 'Lisbon', 'Arroios', '39 Demo Street, Arroios, Lisbon', 38.73456, -9.13793, ST_SetSRID(ST_MakePoint(-9.140746, 38.731723), 4326)::geography, 3, false, 0, 1, 2, 1.0, 120.0, 36.0, 'EUR', '2018-01-01'),
  (203, 203, 'Housy2 between Beach & Mountain', 'Ground floor House, quiet residencial area near center (3Km).
Free parking on the street .
Nice outdoor terrace.
1 suite with queen bed(160x200) and 1 suite with twin beds.
Living room with sofa bed and equipped kitchen.
