  (525, 503, 'Single Small Room Short Ride to Wembley Stadium.', NULL, 'private_room'::property_type, 'London', 'Barnet', '54 Demo Street, Barnet, London', 51.57938, -0.2363, ST_SetSRID(ST_MakePoint(-0.236977, 51.578463), 4326)::geography, 1, false, 0, 1, 1, 1.0, 40.0, 0.0, 'GBP', '2018-01-01'),
  (526, 504, 'Zen Studio w/ Spa Shower & AC', 'Serene London Zen studio in Zone 2, perfect for up to 2-5 guests. Flat is newly decorated and refubished in Mar 2026. This private, self-contained retreat offers excellent transport links, reaching central London attractions in 15 mins. Features a fully equipped kitchen, walk in shower, and private small patio for smoking, full centra heating and Air condition. Ideal for tranquil city breaks or business travelers seeking comfort and convenience in a peaceful residential neighborhood.', 'entire_place'::property_type, 'London', 'Hammersmith and Fulham', '71 Demo Street, Hammersmith and Fulham, London', 51.49853, -0.23125, ST_SetSRID(ST_MakePoint(-0.230805, 51.499605), 4326)::geography, 5, false, 0, 1, 5, 1.0, 209.0, 0.0, 'GBP', '2018-01-01'),
