  v.beds, v.bathrooms, v.price_per_night, v.cleaning_fee, v.currency, v.created_at::timestamptz
FROM (VALUES
  (701, 678, '433 West 53-Furnished Studio in Midtown West', 'Located on Hell’s Kitchen: This is a brand-new elevator building with floor-to-ceiling windows. With Columbus Circle, Whole Foods, Times Square and Central Park all within a short walk, this building is nestled in one of the most desirable residential neighborhoods New York City has to offer. Easily accessible public transportation to the 1, A, B, C, D, N, Q, R lines can take you anywhere you need to go!', 'entire_place'::property_type, 'New York City', 'Hell''s Kitchen', '79 Demo Street, Hell''s Kitchen, New York City', 40.76661, -73.99016, ST_SetSRID(ST_MakePoint(-73.988958, 40.765134), 4326)::geography, 2, true, 2, 0, 1, 1.0, 139.73, 27.0, 'USD', '2018-01-01'),
  (702, 679, 'Heavenly Home', 'Take it easy at this unique and tranquil getaway. 
Private room and sharing
bathroom 
Easy to access by the bus 21 and 31. 
Before booking we need to know the reason for your stay. No smoking allowed in the room.
$500 fee if any smoke scent detected.
$150 fee for each guest extra then the listed amount .
Sharing space 
Please no loud music or noise', 'private_room'::property_type, 'New York City', 'Claremont Village', '167 Demo Street, Claremont Village, New York City', 40.83791, -73.90089, ST_SetSRID(ST_MakePoint(-73.895909, 40.836221), 4326)::geography, 2, false, 0, 1, 1, 1.0, 97.0, 18.0, 'USD', '2018-01-01'),
  (703, 680, 'Ready to be happy and relax? We''re waiting for you', 'Your dreams will come true here! Every little space was created for your happiness and to have a relaxing experience. But if you are ready for the beach and the party, we are too! 

Perfectly located in Rockaway Beach, the transportation is super easy.
Bar, beach, BBQ, jacuzzi, yard, music, you name it! Do you want to have a party?
We can host up to 40 guests and make places to dance, eat, and have the best party ever!

Let us know what your plans are and we will make it!', 'entire_place'::property_type, 'New York City', 'Rockaway Beach', '167 Demo Street, Rockaway Beach, New York City', 40.5896172, -73.81555430000002, ST_SetSRID(ST_MakePoint(-73.818705, 40.590514), 4326)::geography, 3, true, 2, 1, 2, 1.0, 162.54, 32.0, 'USD', '2018-01-01'),
  (704, 681, 'Serene space in Bedford Stuyvesant', 'Forget your worries in this spacious and serene space.', 'private_room'::property_type, 'New York City', 'Bedford-Stuyvesant', '80 Demo Street, Bedford-Stuyvesant, New York City', 40.68723, -73.92917, ST_SetSRID(ST_MakePoint(-73.923999, 40.686866), 4326)::geography, 2, false, 0, 1, 1, 1.5, 77.6, 10.0, 'USD', '2018-01-01'),
  (705, 682, 'Safe NYC Room • Host On-Site • Near 2/5/6 Subway', 'Welcome to a fully registered hosted stay in the Bronx, offering a clean, peaceful private room in a family home. I live on-site full-time to ensure a safe, smooth, and comfortable experience for every guest.
🚇 Just a short walk (7 minutes) to the 2, 5, and 6 subway lines with direct access to Manhattan. 

Perfect for solo travelers, couples, and business guests looking for comfort, convenience, and peace of mind while visiting NYC.
NYC Short-Term Rental Registration: OSE-STRREG-0003075', 'private_room'::property_type, 'New York City', 'Parkchester', '81 Demo Street, Parkchester, New York City', 40.83753, -73.86749, ST_SetSRID(ST_MakePoint(-73.865569, 40.840898), 4326)::geography, 2, false, 0, 1, 1, 1.0, 156.0, 32.0, 'USD', '2018-01-01'),
  (706, 643, 'Room in 3BR2BA near 74th St Station with Own Bath', 'Our homes are designed for people who are starting a new chapter of life in NYC. This private room in Elmhurst is ideal as your first accommodation for your job or studies.
The room offers a dedicated workspace with a desk and fast Wi-Fi. Clean bedding is ready for your arrival, and weekly cleaning is provided to keep the shared spaces clean and organized. The kitchen is equipped with full kitchenware to prepare your own meals.', 'private_room'::property_type, 'New York City', 'Elmhurst', '90 Demo Street, Elmhurst, New York City', 40.74155, -73.88968, ST_SetSRID(ST_MakePoint(-73.885569, 40.742642), 4326)::geography, 2, false, 0, 1, 1, 1.0, 58.07, 14.0, 'USD', '2018-01-01'),
  (707, 683, '75-4C New Duplex 3BR W/D Elevator Walk to C park', 'Luxurious 3 bedroom duplex apartment located on the Upper East Side of New York City, on 75th Street and 2nd or 3rd Avenue with a balcony overlooking the street. The building has an elevator and the apartment has undergone a full renovation, including new furniture. It also includes amenities such as in-unit washer and dryer, free high-speed wireless internet. Overall, it is a brand new apartment with high-quality finishes and luxury features.', 'entire_place'::property_type, 'New York City', 'Upper East Side', '154 Demo Street, Upper East Side, New York City', 40.77077102661133, -73.95748138427734, ST_SetSRID(ST_MakePoint(-73.959523, 40.774553), 4326)::geography, 6, true, 2, 3, 3, 1.0, 359.14, 0.0, 'USD', '2018-01-01'),
  (708, 684, 'Modern Apt w/private bath- in NYC', 'Private bedroom with city views - living room offers a balcony that can be enjoyed by guests.', 'entire_place'::property_type, 'New York City', 'Astoria', '117 Demo Street, Astoria, New York City', 40.77478, -73.93345, ST_SetSRID(ST_MakePoint(-73.929127, 40.777326), 4326)::geography, 2, false, 0, 1, 1, 1.0, 304.9, 0.0, 'USD', '2018-01-01'),
  (709, 685, 'Designer Loft in Clinton Hill · Near Pratt', 'A private bedroom in a beautifully designed industrial loft in the heart of Clinton Hill, Brooklyn. Ideal for creative professionals, writers, designers, and academics on longer stays (30+ days) looking for a calm, quiet, and characterful home base in New York.', 'private_room'::property_type, 'New York City', 'Bedford-Stuyvesant', '72 Demo Street, Bedford-Stuyvesant, New York City', 40.69055, -73.95937, ST_SetSRID(ST_MakePoint(-73.9626, 40.694114), 4326)::geography, 1, false, 0, 1, 1, 1.0, 156.2, 32.0, 'USD', '2018-01-01'),
  (710, 686, 'Prime soho 2 bedroom', 'Enjoy a stylish experience at this centrally-located place. 
This apartment features all brand new appliances and fully renovated in best neighborhood of Manhattan. Located on the second floor with windows all around with lots of sunlight.', 'entire_place'::property_type, 'New York City', 'Greenwich Village', '148 Demo Street, Greenwich Village, New York City', 40.72801, -74.00113, ST_SetSRID(ST_MakePoint(-74.002871, 40.724734), 4326)::geography, 5, false, 0, 2, 2, 1.0, 945.33, 263.0, 'USD', '2018-01-01'),
  (711, 687, 'Loft studio with a Juliet Balcony & Peloton Bike', 'Gorgeous west facing huge 550 sq feet loft studio apartment, featuring floor to ceiling windows; a Juliet balcony, a welcoming entry foyer and hardwood floors and recessed lighting, a roof deck with 360 degree views.
- high speed Wi-Fi
- two grocery stores half a block away (one is open 24/7).
-15 min walk to Central Park & Randall''s island
- 5 min walk from the 4/5 or 6 subways at 125th St and 116th St stops
-easy access to the East River Shopping Plaza at 116th street', 'entire_place'::property_type, 'New York City', 'East Harlem', '146 Demo Street, East Harlem, New York City', 40.80028, -73.93647, ST_SetSRID(ST_MakePoint(-73.933553, 40.800828), 4326)::geography, 3, false, 0, 0, 2, 1.0, 214.89, 0.0, 'USD', '2018-01-01'),
  (712, 688, 'Renovated & Spacious Chelsea Studio', 'Large alcove studio in Chelsea Art Deco highrise doorman building. Clean, bright, modern and quiet. Beautifully decorated with Asian antiques, hardwood floors and renovated kitchen and bathroom. 24 hour doorman and close walk to all major subway lines and attractions', 'entire_place'::property_type, 'New York City', 'Chelsea', '142 Demo Street, Chelsea, New York City', 40.74062, -74.00009, ST_SetSRID(ST_MakePoint(-73.996212, 40.74118), 4326)::geography, 2, false, 0, 0, 1, 1.0, 249.67, 0.0, 'USD', '2018-01-01'),
  (713, 689, 'Chic Studio Apartment in Bed Stuy', 'Chic, spacious studio in the trees in a great limestone building in historic Stuy Heights. Old world charm with modern kitchen and newly remodeled bathroom. Steps from great local food (Saraghina Pizza, Casablanca Bar) and express train to the city.', 'entire_place'::property_type, 'New York City', 'Bedford-Stuyvesant', '147 Demo Street, Bedford-Stuyvesant, New York City', 40.68589, -73.93335, ST_SetSRID(ST_MakePoint(-73.937275, 40.685092), 4326)::geography, 2, false, 0, 1, 1, 1.0, 112.24, 35.0, 'USD', '2018-01-01'),
  (714, 690, 'Bright & Quiet by McCarren Park', 'Come enjoy our beautiful residential neighborhood, one minute from McCarren Park.', 'entire_place'::property_type, 'New York City', 'Greenpoint', '132 Demo Street, Greenpoint, New York City', 40.71923, -73.95126, ST_SetSRID(ST_MakePoint(-73.951723, 40.717508), 4326)::geography, 2, true, 2, 1, 1, 1.0, 328.23, 0.0, 'USD', '2018-01-01'),
  (715, 691, '138 Bowery-Modern Queen Studio', 'Located in Bowery – historically the most unique streetscape of New York with over 400 years of history and culture – this place is right around the corner of Grand St subway. Super convenient as you can be anywhere in Manhattan in just a few minutes. Steps away from SoHo, NoHo and major subway lines (6,J,Z,N,Q,B,D). Its unbeatable location puts the best of downtown.', 'entire_place'::property_type, 'New York City', 'Lower East Side', '116 Demo Street, Lower East Side, New York City', 40.71868, -73.99371, ST_SetSRID(ST_MakePoint(-73.991834, 40.720943), 4326)::geography, 2, false, 0, 0, 1, 1.0, 235.87, 30.0, 'USD', '2018-01-01'),
  (716, 692, 'TWO BEDROOMS DELUXE', 'The apartment is located in a 4 family Townhouse. We are in the center of all shopping areas and major restaurants. The apartment is a 5 minutes walking distance to groceries including a whole food market or the metro station. The neighborhood is very friendly and you will certainly enjoy your stay in Harlem USA. We are 25 minutes away from Times Square 42nd Street.', 'entire_place'::property_type, 'New York City', 'Harlem', '39 Demo Street, Harlem, New York City', 40.80663, -73.94609, ST_SetSRID(ST_MakePoint(-73.944824, 40.807416), 4326)::geography, 6, true, 2, 2, 3, 1.0, 247.22, 75.0, 'USD', '2018-01-01'),
  (717, 693, '5-star sanctuary in BEST Brooklyn neighborhood!', 'This spacious, comfortable brownstone apartment is steps from Prospect Park, subways, and loads of terrific restaurants and bars. It''s on a gorgeous, safe, quiet street that looks just as it did a century ago, now bustling with the friendly, vibrant street life that makes Brooklyn a world-class destination. Read the reviews!!', 'entire_place'::property_type, 'New York City', 'Prospect Heights', '22 Demo Street, Prospect Heights, New York City', 40.67402, -73.96343, ST_SetSRID(ST_MakePoint(-73.959872, 40.671748), 4326)::geography, 2, true, 2, 1, 1, 1.0, 215.44, 0.0, 'USD', '2018-01-01'),
  (718, 694, 'Spacious room by the prospect park', 'This is a great room to find peace and comfort for whatever your trip to brooklyn is about. My place is a sanctuary and you will feel recharged just by being here. 

It''s clean, peaceful, and more spacious than anything else you would probably find in brooklyn. 

It''s right a crossed the street from the prospect park, the botanical gardens, the brooklyn zoo, and a short walking distance to the brooklyn museum. 

Restaurants and cafes are just around the corner.', 'private_room'::property_type, 'New York City', 'Prospect-Lefferts Gardens', '91 Demo Street, Prospect-Lefferts Gardens, New York City', 40.65746, -73.96194, ST_SetSRID(ST_MakePoint(-73.966442, 40.656772), 4326)::geography, 2, false, 0, 1, 1, 1.0, 92.5, 29.0, 'USD', '2018-01-01'),
  (719, 655, 'Modern and Spacious, 2 BR apt in BK brownstone', 'This 1000 sq modern, fully renovated, lower level 2 BR apartment is in a NY brownstone located in Flatbush BK. Only 1 window in the back.

Only 2 blocks from the 5 & 3 train. Short 25min subway ride to downtown Manhattan. Brooklyns coolest attractions are just a few minutes away from the house.

The fully equipped kitchen is perfect if you don''t feel like eating out. There is a fridge, stove and all cooking essentials as well as dishes and utensils.

Hosts are available 24/7 for any requests', 'entire_place'::property_type, 'New York City', 'East Flatbush', '178 Demo Street, East Flatbush, New York City', 40.63349, -73.94547, ST_SetSRID(ST_MakePoint(-73.945547, 40.63697), 4326)::geography, 5, false, 0, 2, 2, 1.0, 113.68, 33.0, 'USD', '2018-01-01'),
  (720, 695, 'Entire 2BR Apartment near Flushing Bus 7Train LGA', 'Simple two bedroom semi-basement apartment. Near LGA, JFK Airport, Citifield and 7 Train. Location is walking distance to Q65, Q25 and Q20A Bus, which leads to Downtown Flushing with the 7-Train.

Many restaurants around area , supermarkets, 7/11 , 24 hours deli store etc all walking distance
Laundromat 2 mins walk away.
convenience to transportation . buses are located at corner , 6 mins drive to 7 Train, 10 mins to LGA airport and Citifield and 20 mins to JFK .', 'entire_place'::property_type, 'New York City', 'College Point', '171 Demo Street, College Point, New York City', 40.78092, -73.84404, ST_SetSRID(ST_MakePoint(-73.841258, 40.782152), 4326)::geography, 4, false, 0, 2, 2, 1.0, 243.6, 70.0, 'USD', '2018-01-01'),
  (721, 678, '165 East 89-Studio in Upper East Side', 'Located on Upper East Side: Steps away from Central Park- one of New York’s greatest attractions and is just three blocks to the express 4, 5 and 6 subway line. Tons of great restaurants around the area and fun activities to do such as exploring the Metropolitan Museum at of Arts and The Guggenheim.', 'entire_place'::property_type, 'New York City', 'Upper East Side', '25 Demo Street, Upper East Side, New York City', 40.7811, -73.95319, ST_SetSRID(ST_MakePoint(-73.953936, 40.779261), 4326)::geography, 2, true, 2, 0, 1, 1.0, 142.13, 19.0, 'USD', '2018-01-01'),
  (722, 696, 'Huge 5BR Townhouse - LEGAL NYC B&B!', 'Why pay a fortune for a NYC hotel you can barely turn around in when you can stay in your own 5 Bedroom - 2.5 Bath House!! 

This grand historic home features 3 floors with over 2500 sq ft of living space. Huge parlor, full kitchen, laundry, deck & free WiFi!', 'entire_place'::property_type, 'New York City', 'Harlem', '169 Demo Street, Harlem, New York City', 40.80633, -73.94585, ST_SetSRID(ST_MakePoint(-73.949855, 40.805269), 4326)::geography, 9, true, 2, 5, 6, 2.5, 806.25, 210.0, 'USD', '2018-01-01'),
  (723, 697, 'GET THE WHOLE APARTMENT - FURNISHED, CLEAN, COZY', 'Beautiful & Clean Apartment for Short and Long stays in NYC. 

Can sleep up to 4. 

Modern Building, Next to Train Station, Safe neighborhood.

Get the ENTIRE ONE-BEDROOM APARTMENT FULLY FURNISHED, including:

- Queen-Sized Bed, 2 Drawers, Paintings, Mirrors, Office Desk, Flowers, 2 Windows, Lamp, Carpet, A/C

- Modern Bath w/ Tub, Mirrors, Painting, Window

- Closet 

- Living Room w/ Large Sofa, 2 Windows, A/C, TV, Paintings

- Dining Area for 4

- Cozy Kitchen w/ Window & Modern Appliances.', 'entire_place'::property_type, 'New York City', 'Mount Eden', '65 Demo Street, Mount Eden, New York City', 40.8381, -73.91485, ST_SetSRID(ST_MakePoint(-73.916282, 40.842111), 4326)::geography, 4, false, 0, 1, 1, 1.0, 118.84, 0.0, 'USD', '2018-01-01'),
  (724, 698, 'Williamsburg, Balcony, Gym, By noomi', 'Prime Williamsburg. Newly constructed boutique elevator building with gym and rooftop. W/D in the unit. 
Lorimer L and G train stop - right on the corner and close to the Marcy J.', 'entire_place'::property_type, 'New York City', 'Williamsburg', '88 Demo Street, Williamsburg, New York City', 40.7144003, -73.9496825, ST_SetSRID(ST_MakePoint(-73.947969, 40.716813), 4326)::geography, 5, true, 2, 3, 3, 2.0, 410.53, 0.0, 'USD', '2018-01-01'),
  (725, 699, 'First floor room in Sunset Park-Brooklyn', 'Recently renovated bedroom. We are located a block away from the R train station 40 minutes to midtown manhattan. A few blocks from NYU Langone Hospital and 58 street water taxi and ferry pier.
The guests will have their own room and will be residing within my unit and all common areas (kitchen, bathroom, living room are shared with me (The Host). It will be a pleasure to have you in my apartment and get to meet you.', 'private_room'::property_type, 'New York City', 'Sunset Park', '72 Demo Street, Sunset Park, New York City', 40.646397684728136, -74.01724621653557, ST_SetSRID(ST_MakePoint(-74.019457, 40.644396), 4326)::geography, 2, false, 0, 1, 1, 1.0, 144.1, 34.0, 'USD', '2018-01-01'),
  (726, 700, 'Mitchell Manor (Cozy Vacation Retreat)', 'Cozy one bedroom suite located on the first floor of my multi level home. I live in the home however, you will have privacy as I am on the 2nd level during the renting. This is a in the heart of historical Stuyvesant Heights. Close to public transportation, shops and restaurants. An ideal Brooklyn location.', 'private_room'::property_type, 'New York City', 'Bedford-Stuyvesant', '9 Demo Street, Bedford-Stuyvesant, New York City', 40.68023, -73.93856, ST_SetSRID(ST_MakePoint(-73.935366, 40.67945), 4326)::geography, 2, false, 0, 1, 1, 1.0, 206.67, 21.0, 'USD', '2018-01-01'),
  (727, 701, 'Modern and Spacious New Construction in Park Slope', 'Modern and Spacious, this charming ‘above grade’ new construction garden apartment is airy and open with plentiful natural light. Located in prime Park Slope just minutes from 5th Avenue and the F/G/R Subway – the apartment features luxury amenities and easy access to all of Park Slope’s restaurants, nightlife and outdoor activities. 

Please reach out with any questions. We look forward to hosting you during your stay in Brooklyn!', 'entire_place'::property_type, 'New York City', 'South Slope', '77 Demo Street, South Slope, New York City', 40.66686, -73.98871, ST_SetSRID(ST_MakePoint(-73.987013, 40.668096), 4326)::geography, 3, true, 2, 1, 2, 1.0, 291.11, 0.0, 'USD', '2018-01-01'),
  (728, 702, 'Standard queen Liberty Statue', 'At Liberty View Brooklyn Hotel, we invite you to get comfortable and feel connected to the city. Each morning kicks off with an included breakfast and our fitness center keeps your routine on track. Just outside, Sunset Park serves up culture, food, and local flavor, while we give you a cozy base to return to. Please note: A $100 incidental security deposit and $20 Destination Fee / night will be collected at check-in.', 'private_room'::property_type, 'New York City', 'Sunset Park', '141 Demo Street, Sunset Park, New York City', 40.65848, -74.00053, ST_SetSRID(ST_MakePoint(-74.000443, 40.660524), 4326)::geography, 2, false, 0, 1, 1, 1.0, 439.0, 108.0, 'USD', '2018-01-01'),
  (729, 703, 'Peaceful private room in two bedroom with a garden', 'If you like mood lighting and vinyl, this is the place for you. If you like grilling and a fire pit in a private garden come stay with me. There''s outdoor cafe seating and an outdoor living room in this ground floor brown stone unit. Excellent for morning coffee and planing your day in New York. Walking distance to all the best spots in Bedstuy and the A/C.', 'private_room'::property_type, 'New York City', 'Bedford-Stuyvesant', '31 Demo Street, Bedford-Stuyvesant, New York City', 40.68475, -73.9391, ST_SetSRID(ST_MakePoint(-73.94255, 40.6842), 4326)::geography, 2, false, 0, 1, 1, 1.0, 102.5, 31.0, 'USD', '2018-01-01'),
  (730, 704, 'Luxury Apartment with Backyard Poarch', 'Our newly updated open space studio offers a feel of luxury, comfort and seamless stay. Located in East Flatbush, a centric Caribbean community in the heart of Brooklyn, you have a variety of public transportation options and many amenities in walking distance. Easy access to Downtown Brooklyn and Manhattan. Perfect for a few days stay or mid term stay. 
Close to major hospitals and medical facilities: Kings County Hospital, Kingsbrook Jewish Hospital, Brookdale, Interfaith, SUNY Downstate.', 'entire_place'::property_type, 'New York City', 'East Flatbush', '27 Demo Street, East Flatbush, New York City', 40.65086, -73.93091, ST_SetSRID(ST_MakePoint(-73.933659, 40.650369), 4326)::geography, 4, false, 0, 0, 1, 1.0, 115.54, 24.0, 'USD', '2018-01-01'),
  (731, 705, 'Apartment in Bedford Stuyvesant Brooklyn', 'Stay in a newly renovated private suite. The space features a thoughtfully decorated living room, dining area, kitchen, bathroom and a comfortable queen bedroom. Plus there is a convenient workspace. Located in the heart of Bedford-Stuyvesant and steps from several subway lines that connect you to Manhattan and nearby Brooklyn neighborhoods.

*This unit adheres to NYC laws and regulations. I am available at all times, but respect your privacy and available when needed.', 'private_room'::property_type, 'New York City', 'Bedford-Stuyvesant', '74 Demo Street, Bedford-Stuyvesant, New York City', 40.682026, -73.915649, ST_SetSRID(ST_MakePoint(-73.916804, 40.681002), 4326)::geography, 2, false, 0, 1, 1, 1.0, 344.9, 73.0, 'USD', '2018-01-01'),
  (732, 706, 'Huge Triplex + Movie Theater', 'Discover the allure of Manhattan from our exquisite apartment, nestled in the city''s pulsating heart. Indulge in a unique blend of modern elegance and classic New York charm, with a well-appointed kitchen and a serene living space. Savor stunning cityscapes, and immerse yourself in the vibrant culture and entertainment right outside your door. Ideal for both leisure and business travelers seeking a memorable NYC experience', 'entire_place'::property_type, 'New York City', 'Murray Hill', '45 Demo Street, Murray Hill, New York City', 40.74947, -73.9793, ST_SetSRID(ST_MakePoint(-73.978092, 40.75048), 4326)::geography, 7, false, 0, 3, 3, 2.5, 1738.53, 428.0, 'USD', '2018-01-01'),
  (733, 707, 'Charming 2-Queen Suite, JFK/LaGuardia: Sleeps 4', 'Welcome to your inviting Queens retreat!

This cozy suite offers the ideal foundation for an effortless New York stay, whether you need a smooth layover near JFK or LaGuardia airports or a well-located launchpad for exploring the city. Thoughtfully prepared to accommodate up to 4 guests, your stay features a hotel-style layout with an attached private full bathroom. Please note that this is a private basement suite, and accessing the unit requires climbing a set of steps.', 'private_room'::property_type, 'New York City', 'Fresh Meadows', '144 Demo Street, Fresh Meadows, New York City', 40.7417, -73.78719, ST_SetSRID(ST_MakePoint(-73.786613, 40.743007), 4326)::geography, 4, false, 0, 1, 2, 1.0, 274.0, 57.0, 'USD', '2018-01-01'),
  (734, 708, 'Modern Condo Next To Domino Park, City Views', 'The closest condo you can get to Domino Park, with scenic views of water and Manhattan. This two-bedroom, two-bathroom gem has loft-style charm with an exposed spiral staircase, cement walls, and tall ceilings.

The master bedroom has a luxurious king-sized bed + ensuite bathroom. The second bedroom has a queen-sized bed and desk.

Enjoy our large private deck area that includes comfortable seating, gas firepit and views the Empire State Building/Manhattan.', 'entire_place'::property_type, 'New York City', 'Williamsburg', '149 Demo Street, Williamsburg, New York City', 40.7148, -73.96546, ST_SetSRID(ST_MakePoint(-73.965483, 40.716354), 4326)::geography, 5, true, 2, 2, 2, 2.0, 438.08, 100.0, 'USD', '2018-01-01'),
  (735, 709, '2 BR Brownstone Retreat, 3rd Fl.', 'The ''White House'' awaits your presence. Enjoy all that Brooklyn has to offer. This 2 bedroom brownstone apartment on the 3rd floor is centrally located to all amenities and gets you into Manhattan via public transportation in less than 30 minutes!', 'shared_room'::property_type, 'New York City', 'Bedford-Stuyvesant', '163 Demo Street, Bedford-Stuyvesant, New York City', 40.6864, -73.94076, ST_SetSRID(ST_MakePoint(-73.938807, 40.687561), 4326)::geography, 2, false, 0, 2, 3, 1.0, 186.0, 56.0, 'USD', '2018-01-01'),
  (736, 710, 'Huge gorgeous Loft in the LES/Chinatown!', 'CAN RENT SHORT TERM-JUST SEND ME A MESSAGE!

About this space: This beautiful open loft lies at the lowest point of the Lower East Side (currently referred to as the ''Low Low''). The area is alive with restaurants, art galleries, record shops, cafes, bars, and nightlife. Truly the best part of all of NYC! 

Gut renovated, stunning new hardwood floors and recessed lighting. Double pane windows that keep apartment quiet and peaceful. Safe, central, and a fascinating area.

Subways very close.', 'entire_place'::property_type, 'New York City', 'Chinatown', '149 Demo Street, Chinatown, New York City', 40.71393, -73.99519, ST_SetSRID(ST_MakePoint(-73.994006, 40.714525), 4326)::geography, 5, false, 0, 1, 2, 1.0, 198.19, 0.0, 'USD', '2018-01-01'),
  (737, 711, 'Essex House - Studio', 'This elegant studio apartment on the hotel''s 29th floor boasts impressive views of Manhattan''s skyline. Immaculately furnished in a sophisticated, modern style, the unit features exquisite detailing, stylish built-ins, ample storage space, a luxurious, hotel-quality bathroom, and a gracious entrance hall. Experience the heart of Manhattan in comfort and class.', 'entire_place'::property_type, 'New York City', 'Midtown', '44 Demo Street, Midtown, New York City', 40.76493, -73.97814, ST_SetSRID(ST_MakePoint(-73.9807, 40.768147), 4326)::geography, 2, true, 2, 1, 1, 1.0, 324.13, 34.0, 'USD', '2018-01-01'),
  (738, 675, 'Tranquil Bay Ridge Nook: Studio w/ Verrazano View', 'This studio offers unbeatable convenience and comfort, just steps from subway access, local restaurants, and shopping. Perfect for solo travelers or couples, it provides a peaceful retreat while also immersing you in the lively, vibrant atmosphere of the neighborhood.', 'entire_place'::property_type, 'New York City', 'Fort Hamilton', '147 Demo Street, Fort Hamilton, New York City', 40.61881, -74.03238, ST_SetSRID(ST_MakePoint(-74.034635, 40.615297), 4326)::geography, 2, true, 2, 0, 1, 1.0, 203.0, 63.0, 'USD', '2018-01-01'),
  (739, 712, 'The Bold Look 3BR Apt Near JFK/LGA/LIRR Free WIFI', 'Completely renovated (3) Three bedroom (1) Bathroom apartment. 

The kitchen includes a refrigerator, stove, microwave, coffee maker, tea kettle & and silverwar. 

Each Bedroom is fully furnished with HVAC Central AC, A Full Size Bed & 32"TV''s with streaming access, to multiple streaming platforms. Towels & Washcloths are in every bedroom.

The bathroom has various essentials and more, from shampoo to conditioner, hand soaps.
All beds are Full size.', 'entire_place'::property_type, 'New York City', 'Springfield Gardens', '111 Demo Street, Springfield Gardens, New York City', 40.66022, -73.76563, ST_SetSRID(ST_MakePoint(-73.763327, 40.660649), 4326)::geography, 6, false, 0, 3, 1, 1.0, 168.02, 48.0, 'USD', '2018-01-01'),
  (740, 713, 'Unique room in upper west side', 'This unique room in a shared apartment located on the upper west side. In a very convenient location near public transportation’s, restaurant’s, and New York Presbyterian hospital.
 Nearest train lines are only a three minute walk to the A,C,and 1 line. The A Train is only 5 stops away from Times Square that’s only is a 15 to 20 minute ride from Times Square and the 1 Train which is a local line that travels all of Manhattan.

 Free Common area cleaning, service every day of the week.', 'private_room'::property_type, 'New York City', 'Washington Heights', '122 Demo Street, Washington Heights, New York City', 40.83751, -73.94003, ST_SetSRID(ST_MakePoint(-73.941002, 40.836967), 4326)::geography, 1, false, 0, 1, 1, 1.0, 54.04, 0.0, 'USD', '2018-01-01'),
  (741, 714, 'Charming First Floor Village Apt off Bleecker', 'PLEASE SCROLL way down and click on "contact host" button. Let me know you read through whole listing. I''ll send some info and make sure you know what you are booking before offering a stay.

This is an extremely well located apartment with a very hands-on owner who lives upstairs. It''s simple and vintage, with everything you need!

Our price includes a voucher for 10% off breakfast/lunch or a free coffee/tea with any food purchase at a cute restaurant on our block called Foursome.', 'entire_place'::property_type, 'New York City', 'West Village', '84 Demo Street, West Village, New York City', 40.73277, -74.00267, ST_SetSRID(ST_MakePoint(-74.001697, 40.731987), 4326)::geography, 4, false, 0, 1, 3, 1.0, 320.67, 95.0, 'USD', '2018-01-01'),
  (742, 715, 'A Cozy Bedroom in 2 Bedroom Apt', 'Apt next to the subway
Organic shop and bank in the building
Elevator building 
Laundry room in the building
WiFi
Gyrotonic Machine
A/C units in every room
Hardwood Floors', 'private_room'::property_type, 'New York City', 'Harlem', '13 Demo Street, Harlem, New York City', 40.80283, -73.95741, ST_SetSRID(ST_MakePoint(-73.958494, 40.805682), 4326)::geography, 1, false, 0, 2, 1, 1.0, 77.92, 15.0, 'USD', '2018-01-01'),
  (743, 716, 'Private Brownstone - Studio Apartment 3F in Harlem', 'Clean cozy private walkup apartment on 3rd floor, kitchen, television and internet access. Walking distance to the Apollo Theatre, Abyssinian & Canaan Baptist Church, and near by Central Park. Partake in the many cultural cuisines at nearby restaurants and bars. Subway stations and bus stops are accessible to airports and other NYC attractions, Broadway Theatres, Times Square, Lincoln Center, World Trade Memorial, Statue of Liberty and shopping.', 'entire_place'::property_type, 'New York City', 'Harlem', '99 Demo Street, Harlem, New York City', 40.80467987060547, -73.94985961914062, ST_SetSRID(ST_MakePoint(-73.947224, 40.801226), 4326)::geography, 2, false, 0, 1, 2, 1.0, 135.1, 18.0, 'USD', '2018-01-01'),
  (744, 717, 'Lovely studio rental in Midtown West', 'Cozy studio in midtown steps from Broadway, Times Square, night life, and great restaurants. Perfect sized apartment for two with comfortable queen and fully equipped kitchen. Futon couch can be used for additional guest. Across the street from Target for all your trip essentials. Just a couple blocks away, jump on the subway at 42nd street and reach every corner of the city. Freshly painted, clean, and recently renovated- this is your perfect home away from home for your NYC stay.', 'entire_place'::property_type, 'New York City', 'Hell''s Kitchen', '29 Demo Street, Hell''s Kitchen, New York City', 40.76137, -73.99391, ST_SetSRID(ST_MakePoint(-73.995587, 40.761606), 4326)::geography, 3, false, 0, 1, 1, 1.0, 240.88, 41.0, 'USD', '2018-01-01'),
  (745, 718, '5 min Subway Sunlit King Master LGBTQ+ Friendly', '• LGBTQ friendly & safe space
• Central A/C
• Early luggage drop-off & post-checkout luggage storage
• King Master Room, not like other NYC small room
• Breville espresso machine & variety tea selection
• Feel free to cook in the kitchen! You can use all seasoning and equipment
• Samsung washer & dryer in the basement! (We provide detergent)
• 5 min walk to Subway (L and 3 trains) to reach Manhattan in 30 minutes
• 1 GB WiFi for your remote work
• Solar Powered House with lots of indoor plants!', 'private_room'::property_type, 'New York City', 'Brownsville', '33 Demo Street, Brownsville, New York City', 40.6555, -73.90648, ST_SetSRID(ST_MakePoint(-73.901883, 40.655542), 4326)::geography, 2, false, 0, 1, 1, 1.5, 631.0, 208.0, 'USD', '2018-01-01'),
  (746, 719, 'Worldclass Casa - Sun Rm w/AC- 5 min to JFK', 'Your second home! Relax, unwind and enjoy a clean and comfortable stay. Recently renovated with all new furniture and amenities.

Good for couples, families, business travelers and layovers. Clean and safe place to stay.

5 minutes from: JFK ( Free airport pickup w/ 7 night stay); Belmont Racetrack; UBS arena, restaurants, pharmacies
10 minutes from: E/F/J/Z Subway (train), Long Island Rail Road (LIRR)
15 minutes from: LGA; Resorts World Casino
30 - 40 minutes from Times Square - Manhattan', 'private_room'::property_type, 'New York City', 'Springfield Gardens', '53 Demo Street, Springfield Gardens, New York City', 40.6908, -73.747, ST_SetSRID(ST_MakePoint(-73.747475, 40.688107), 4326)::geography, 2, false, 0, 1, 1, 1.0, 80.68, 20.0, 'USD', '2018-01-01'),
  (747, 720, 'High-Line Haven: Urban Elegance', 'Brand new and fully renovated, this bright studio features modern and sleek finishes from its beautiful hardwood floors to stainless steel appliances/marble-tiled bathrooms. This sleek and contemporary urban haven is designed to offer you the epitome of style and comfort for your New York City stay.

Located in the very heart of Chelsea, the unit is steps away from world-class art galleries to trendy boutiques and renowned dining establishments.', 'entire_place'::property_type, 'New York City', 'Chelsea', '169 Demo Street, Chelsea, New York City', 40.74434, -74.00487, ST_SetSRID(ST_MakePoint(-74.001851, 40.742983), 4326)::geography, 2, true, 2, 1, 1, 1.0, 202.66, 42.0, 'USD', '2018-01-01'),
  (748, 721, 'NewlyRenovated 2 bedroom,20 min from Manhattan,LGA', 'You will be close to everything when you stay at this centrally-located place. Close to Manhattan, Brooklyn, trains, 24hr grocery, restaurants, nightlife. Message for one parking spot availability', 'private_room'::property_type, 'New York City', 'Long Island City', '125 Demo Street, Long Island City, New York City', 40.76455, -73.93712, ST_SetSRID(ST_MakePoint(-73.932842, 40.762924), 4326)::geography, 4, false, 0, 1, 2, 1.0, 334.0, 108.0, 'USD', '2018-01-01'),
  (749, 722, 'Unique modern apartment & private entrance & deck', 'Beautiful views of the east river, a 1 minute walk to the newly opened domino park. The park has a restaurant, playground lounge chairs and a sand volleyball court.

Williamsburg is a really fun neighborhood with tons of awesome restaurants, and trendy shops.
It is also a great place for a family or companies traveling to the city for work.
We do not allow any parties or events on this property.
The house is a 10 minute walk to the L train and a 15 minute walk to the JMZ or the G train.', 'entire_place'::property_type, 'New York City', 'Williamsburg', '23 Demo Street, Williamsburg, New York City', 40.71682, -73.96493, ST_SetSRID(ST_MakePoint(-73.964642, 40.715758), 4326)::geography, 5, false, 0, 3, 3, 2.0, 570.5, 150.0, 'USD', '2018-01-01'),
  (750, 723, 'Your home in Brooklyn near JFK', 'Located 20min away from JFK, express bus to manhattan at the corner, 15min away from the L train, 30min away from the Barclays center. This home is great for couples, friends, families and solo travelers, who need a spacious and comfortable home in NYC. This is a shared space so common areas such as main entrance will be shared. The host will be in the unit. Guests will have their own private entrance. There are tons of attractions in the neighborhood such as Canarsie park and restaurants', 'private_room'::property_type, 'New York City', 'Canarsie', '160 Demo Street, Canarsie, New York City', 40.63064, -73.90415, ST_SetSRID(ST_MakePoint(-73.907043, 40.633773), 4326)::geography, 4, false, 0, 2, 2, 1.0, 190.0, 29.0, 'USD', '2018-01-01')
) AS v(id, host_id, title, description, property_type, city, neighborhood, address, latitude,
  longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds, bathrooms,
  price_per_night, cleaning_fee, currency, created_at)
JOIN cities c ON c.name = v.city;

INSERT INTO listings (id, host_id, title, description, property_type, city_id, neighborhood, address,
  latitude, longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds,
  bathrooms, price_per_night, cleaning_fee, currency, created_at)
OVERRIDING SYSTEM VALUE
SELECT v.id, v.host_id, v.title, v.description, v.property_type, c.id, v.neighborhood, v.address,
  v.latitude, v.longitude, v.public_location, v.max_guests, v.pets_allowed, v.max_pets, v.bedrooms,
  v.beds, v.bathrooms, v.price_per_night, v.cleaning_fee, v.currency, v.created_at::timestamptz
FROM (VALUES
  (751, 2004, 'آپارتمان دنج نزدیک بازار تجریش', 'آپارتمان ۷۵ متری در طبقه‌ی سوم، ۵ دقیقه پیاده تا بازار تجریش و ایستگاه مترو. آشپزخانه کامل است و Wi-Fi با سرعت 50Mbps دارد. هوای این محله خنک‌تر از مرکز شهر است، پس تابستان هم بدون کولر قابل‌تحمل است.', 'entire_place'::property_type, 'Tehran', 'تجریش', 'پلاک 8، کوچه‌ی نمونه، تجریش، تهران', 35.8042, 51.4331, ST_SetSRID(ST_MakePoint(51.435022, 35.808032), 4326)::geography, 3, false, 0, 1, 2, 1.0, 32500000.0, 2500000.0, 'IRR', '2023-01-02'),
  (752, 2005, 'سوئیت مدرن با ویوی کوه در زعفرانیه', 'سوئیت نوساز با پنجره‌ی رو به البرز. پارکینگ اختصاصی، آسانسور و ورود بدون کلید (Self check-in) دارد. برای سفر کاری مناسب است: میز کار، صندلی ارگونومیک و اینترنت فیبر.', 'entire_place'::property_type, 'Tehran', 'زعفرانیه', 'پلاک 12، کوچه‌ی نمونه، زعفرانیه، تهران', 35.7951, 51.4132, ST_SetSRID(ST_MakePoint(51.408322, 35.796157), 4326)::geography, 2, false, 0, 1, 1, 1.0, 60000000.0, 5000000.0, 'IRR', '2019-06-20'),
  (753, 2006, 'اتاق خصوصی در خانه‌ی خانوادگی، یوسف‌آباد', 'یک اتاق آفتابی با تخت دونفره در خانه‌ای که خودمان هم در آن زندگی می‌کنیم. صبحانه‌ی ایرانی (نان، پنیر، گردو و چای) با ما. پارک لاله با تاکسی ۱۰ دقیقه است.', 'private_room'::property_type, 'Tehran', 'یوسف‌آباد', 'پلاک 51، کوچه‌ی نمونه، یوسف‌آباد، تهران', 35.7312, 51.4028, ST_SetSRID(ST_MakePoint(51.404451, 35.733582), 4326)::geography, 2, false, 0, 1, 1, 1.0, 6400000.0, 0.0, 'IRR', '2019-12-07'),
  (754, 2007, 'خانه‌ی باغ‌دار در نیاوران', 'خانه‌ی دوطبقه با حیاط و درخت‌های چنار، مناسب خانواده. ۳ اتاق خواب، آشپزخانه‌ی کامل و باربیکیو در حیاط. کاخ نیاوران پیاده ۱۵ دقیقه است. حیوان خانگی کوچک پذیرفته می‌شود.', 'entire_place'::property_type, 'Tehran', 'نیاوران', 'پلاک 89، کوچه‌ی نمونه، نیاوران، تهران', 35.8103, 51.4702, ST_SetSRID(ST_MakePoint(51.46612, 35.811701), 4326)::geography, 7, true, 1, 3, 4, 2.0, 100000000.0, 7500000.0, 'IRR', '2023-11-08'),
  (755, 2008, 'استودیوی مینیمال نزدیک میدان ونک', 'استودیو ۴۰ متری، دقیقاً وسط شهر. مترو و BRT دو دقیقه پیاده است. برای یک یا دو نفر که بیشتر بیرون‌اند و فقط جای خواب تمیز می‌خواهند.', 'entire_place'::property_type, 'Tehran', 'ونک', 'پلاک 67، کوچه‌ی نمونه، ونک، تهران', 35.7593, 51.4101, ST_SetSRID(ST_MakePoint(51.409387, 35.76275), 4326)::geography, 2, false, 0, 0, 1, 1.0, 25000000.0, 2000000.0, 'IRR', '2020-04-10'),
  (756, 2009, 'آپارتمان دوخوابه‌ی آرام در شهرک غرب', 'آپارتمان ۱۱۰ متری با دو اتاق خواب در خیابانی آرام، نزدیک بازار میوه و تره‌بار و پارک. ماشین لباسشویی، ظرفشویی و پارکینگ دارد.', 'entire_place'::property_type, 'Tehran', 'شهرک غرب', 'پلاک 1، کوچه‌ی نمونه، شهرک غرب، تهران', 35.7584, 51.3711, ST_SetSRID(ST_MakePoint(51.370939, 35.756642), 4326)::geography, 4, false, 0, 2, 3, 1.5, 45000000.0, 4000000.0, 'IRR', '2022-03-02'),
  (757, 2010, 'پنت‌هاوس با تراس در الهیه', 'طبقه‌ی آخر با تراس ۳۰ متری و ویوی شهر در شب. برای مهمانی و عکاسی مناسب نیست؛ ساختمان مسکونی است و ساعت ۲۲ به بعد سکوت لازم است.', 'entire_place'::property_type, 'Tehran', 'الهیه', 'پلاک 75، کوچه‌ی نمونه، الهیه، تهران', 35.7872, 51.4254, ST_SetSRID(ST_MakePoint(51.424061, 35.78964), 4326)::geography, 4, false, 0, 2, 2, 2.0, 90000000.0, 7500000.0, 'IRR', '2023-04-03'),
  (758, 2011, 'کلبه‌ی کوچک کنار مسیر کوه‌نوردی دربند', 'اتاق مستقل با در جدا در پایین مسیر دربند. صبح زود می‌شود کوه رفت و ظهر برگشت. تختخواب، بخاری و یک آشپزخانه‌ی کوچک دارد.', 'entire_place'::property_type, 'Tehran', 'دربند', 'پلاک 25، کوچه‌ی نمونه، دربند، تهران', 35.8221, 51.4253, ST_SetSRID(ST_MakePoint(51.423494, 35.818184), 4326)::geography, 2, true, 1, 1, 1, 1.0, 22500000.0, 1500000.0, 'IRR', '2023-03-24'),
  (759, 2012, 'آپارتمان خانوادگی نزدیک پارک ملت', '۳ خوابه، ۱۴۰ متر، مناسب خانواده‌ی ۶ نفره. فروشگاه بزرگ و رستوران‌ها پیاده در دسترس‌اند. پارکینگ دو ماشین.', 'entire_place'::property_type, 'Tehran', 'سعادت‌آباد', 'پلاک 36، کوچه‌ی نمونه، سعادت‌آباد، تهران', 35.7843, 51.3782, ST_SetSRID(ST_MakePoint(51.374625, 35.78231), 4326)::geography, 6, false, 0, 3, 4, 2.0, 55000000.0, 5000000.0, 'IRR', '2021-04-11'),
  (760, 2013, 'اتاق خصوصی دانشجویی، نزدیک دانشگاه', 'اتاق ساده با یک تخت یک‌نفره و میز مطالعه. آشپزخانه و حمام مشترک با یک هم‌خانه‌ی دیگر است. مناسب آزمون، کنفرانس یا سفر کوتاه.', 'private_room'::property_type, 'Tehran', 'گیشا', 'پلاک 11، کوچه‌ی نمونه، گیشا، تهران', 35.7331, 51.3852, ST_SetSRID(ST_MakePoint(51.385678, 35.734249), 4326)::geography, 1, false, 0, 1, 1, 1.0, 5000000.0, 0.0, 'IRR', '2022-06-19'),
  (761, 2014, 'آپارتمان قدیمی بازسازی‌شده در کریم‌خان', 'ساختمان دهه‌ی ۵۰ با سقف بلند و پنجره‌های چوبی، که از داخل کامل نو شده. کافه‌ها و کتاب‌فروشی‌های کریم‌خان سر کوچه‌اند.', 'entire_place'::property_type, 'Tehran', 'کریم‌خان', 'پلاک 39، کوچه‌ی نمونه، کریم‌خان، تهران', 35.7163, 51.4148, ST_SetSRID(ST_MakePoint(51.416188, 35.712998), 4326)::geography, 3, false, 0, 1, 2, 1.0, 37500000.0, 3000000.0, 'IRR', '2019-08-29'),
  (762, 2015, 'اتاق در خانه‌ی قاجاری عودلاجان', 'اتاقی با ارسی و شیشه‌های رنگی در یکی از خانه‌های قدیمی محله‌ی عودلاجان. بازار بزرگ و کاخ گلستان پیاده در دسترس است.', 'private_room'::property_type, 'Tehran', 'عودلاجان', 'پلاک 48، کوچه‌ی نمونه، عودلاجان، تهران', 35.6802, 51.4253, ST_SetSRID(ST_MakePoint(51.426633, 35.6789), 4326)::geography, 2, false, 0, 1, 1, 1.0, 8000000.0, 0.0, 'IRR', '2019-02-02'),
  (763, 2016, 'سوئیت با حیاط کوچک در پاسداران', 'سوئیت همکف با در مستقل و حیاط کوچک. برای دو نفر، با پارکینگ و ورود بدون کلید.', 'entire_place'::property_type, 'Tehran', 'پاسداران', 'پلاک 87، کوچه‌ی نمونه، پاسداران، تهران', 35.7702, 51.4651, ST_SetSRID(ST_MakePoint(51.466144, 35.771204), 4326)::geography, 2, true, 1, 1, 1, 1.0, 30000000.0, 2500000.0, 'IRR', '2020-03-07'),
  (764, 2017, 'آپارتمان روشن با بالکن در دروس', 'دو اتاق خواب، بالکن رو به حیاط مشجر، و آشپزخانه‌ای که هر چیزی برای پخت غذای ایرانی دارد (حتی پلوپز!).', 'entire_place'::property_type, 'Tehran', 'دروس', 'پلاک 66، کوچه‌ی نمونه، دروس، تهران', 35.7761, 51.4482, ST_SetSRID(ST_MakePoint(51.445874, 35.772571), 4326)::geography, 4, false, 0, 2, 2, 1.0, 42500000.0, 3500000.0, 'IRR', '2020-10-24'),
  (765, 2018, 'اتاق اشتراکی ارزان برای مسافران کوله‌گرد', 'خوابگاه ۴ تخته‌ی مختلط با کمد قفل‌دار برای هر تخت. آشپزخانه و فضای نشیمن مشترک. فقط بزرگسالان.', 'shared_room'::property_type, 'Tehran', 'امیرآباد', 'پلاک 15، کوچه‌ی نمونه، امیرآباد، تهران', 35.7351, 51.3922, ST_SetSRID(ST_MakePoint(51.389137, 35.737856), 4326)::geography, 1, false, 0, 1, 4, 2.0, 5000000.0, 0.0, 'IRR', '2020-06-26'),
  (766, 2019, 'آپارتمان لوکس کاری در خیابان آفریقا', 'مناسب مدیران و سفر کاری: ۱ خوابه، میز کار بزرگ، پرینتر، قهوه‌ساز و اینترنت 100Mbps. لابی ۲۴ ساعته و پارکینگ.', 'entire_place'::property_type, 'Tehran', 'جردن', 'پلاک 56، کوچه‌ی نمونه، جردن، تهران', 35.7702, 51.4183, ST_SetSRID(ST_MakePoint(51.419702, 35.769023), 4326)::geography, 2, false, 0, 1, 1, 1.5, 75000000.0, 6000000.0, 'IRR', '2023-08-26'),
  (767, 2020, 'خانه‌ی سنتی با حوض و ایوان در محله‌ی جلفا', 'این خانه در یکی از کوچه‌های آرام محله‌ی جلفا است، چند دقیقه پیاده تا کلیسای وانک و خیابان نظر با کافه‌های کوچکش. ساختمان حدود ۱۲۰ سال پیش ساخته شده و حیاط مرکزی با حوض فیروزه‌ای، باغچه‌ی نارنج و ایوانی رو به جنوب دارد. ما خانه را با همان آجر و گچ‌بری‌های قدیمی بازسازی کرده‌ایم، ولی امکانات امروزی را هم کنار گذاشته‌ایم: گرمایش از کف در زمستان، کولر گازی در تابستان، اینترنت فیبر (حدود 80Mbps) و آشپزخانه‌ای کامل با یخچال، اجاق، مایکروفر و ظرفشویی. سه اتاق خواب دور حیاط هستند: اتاق «ارسی» با پنجره‌های رنگی و تخت دونفره، اتاق «شاه‌نشین» با دو تخت یک‌نفره و رخت‌خواب سنتی برای یک نفر دیگر، و اتاق کوچک‌تر کنار مطبخ قدیم که برای بچه‌ها مناسب است. دو حمام داریم که یکی وان دارد. صبحانه‌ی محلی (نان سنگک، پنیر، خرما، گردو و مربای بهارنارنج) را اگر بخواهید با هزینه‌ی جدا آماده می‌کنیم. ورود از ساعت 14:00 و خروج تا 11:00 است؛ اگر زودتر برسید، چمدان را نگه می‌داریم. لطفاً توجه کنید که خانه پله‌های قدیمی و حوض بدون حفاظ دارد، پس با کودک خردسال مراقب باشید. پارک کردن در کوچه آسان نیست، ولی خیابان اصلی ۲ دقیقه فاصله دارد و تاکسی اینترنتی تا جلوی در می‌آید. در شب‌های تابستان، نشستن کنار حوض با چای و صدای فواره بهترین بخش این خانه است.', 'entire_place'::property_type, 'Isfahan', 'جلفا', 'پلاک 63، کوچه‌ی نمونه، جلفا، اصفهان', 32.6331, 51.6562, ST_SetSRID(ST_MakePoint(51.652975, 32.631512), 4326)::geography, 7, false, 0, 3, 5, 2.0, 64000000.0, 6000000.0, 'IRR', '2021-10-23'),
  (768, 2021, 'آپارتمان نزدیک چهارباغ و سی‌وسه‌پل', 'دو خوابه در طبقه‌ی دوم، ۱۰ دقیقه پیاده تا سی‌وسه‌پل. برای دیدن شهر بدون ماشین مناسب است.', 'entire_place'::property_type, 'Isfahan', 'چهارباغ', 'پلاک 85، کوچه‌ی نمونه، چهارباغ، اصفهان', 32.6472, 51.6681, ST_SetSRID(ST_MakePoint(51.669413, 32.647489), 4326)::geography, 4, false, 0, 2, 3, 1.0, 28000000.0, 2000000.0, 'IRR', '2020-05-22'),
  (769, 2022, 'اتاق خصوصی با پنجره رو به میدان نقش جهان', 'اتاقی کوچک در ساختمانی قدیمی، با پنجره‌ای که از آن گنبد مسجد شیخ لطف‌الله پیداست. حمام اختصاصی دارد.', 'private_room'::property_type, 'Isfahan', 'نقش جهان', 'پلاک 47، کوچه‌ی نمونه، نقش جهان، اصفهان', 32.6574, 51.6772, ST_SetSRID(ST_MakePoint(51.677634, 32.656136), 4326)::geography, 2, false, 0, 1, 1, 1.0, 10000000.0, 0.0, 'IRR', '2020-07-04'),
  (770, 2023, 'اقامتگاه بوم‌گردی در محله‌ی قدیمی جوباره', 'خانه‌ای خشتی با چهار اتاق دور حیاط. صاحبخانه‌ها در خانه‌ی کناری زندگی می‌کنند و آشپزی محلی (بریانی، گز خانگی) یاد می‌دهند.', 'entire_place'::property_type, 'Isfahan', 'جوباره', 'پلاک 8، کوچه‌ی نمونه، جوباره، اصفهان', 32.6662, 51.6843, ST_SetSRID(ST_MakePoint(51.687946, 32.667777), 4326)::geography, 8, false, 0, 4, 6, 2.0, 52000000.0, 4000000.0, 'IRR', '2021-03-15'),
  (771, 2024, 'سوئیت آرام کنار باغ هشت بهشت', 'سوئیت یک‌خوابه در کوچه‌ای ساکت، پیاده ۵ دقیقه تا باغ هشت بهشت و ۱۵ دقیقه تا میدان.', 'entire_place'::property_type, 'Isfahan', 'هشت بهشت', 'پلاک 67، کوچه‌ی نمونه، هشت بهشت، اصفهان', 32.6521, 51.6702, ST_SetSRID(ST_MakePoint(51.668501, 32.654768), 4326)::geography, 2, false, 0, 1, 1, 1.0, 22000000.0, 1600000.0, 'IRR', '2023-02-08'),
  (772, 2025, 'آپارتمان خانوادگی در مرداویج', 'سه خوابه با پارکینگ و آسانسور، مناسب خانواده‌ای که با ماشین سفر می‌کند. تا مرکز شهر ۱۵ دقیقه رانندگی.', 'entire_place'::property_type, 'Isfahan', 'مرداویج', 'پلاک 76، کوچه‌ی نمونه، مرداویج، اصفهان', 32.6121, 51.6683, ST_SetSRID(ST_MakePoint(51.668132, 32.613208), 4326)::geography, 6, true, 1, 3, 4, 2.0, 38000000.0, 3200000.0, 'IRR', '2020-03-16'),
  (773, 2026, 'اتاق خصوصی ساده برای مسافر تنها', 'اتاق یک‌نفره با میز کار در آپارتمانی که با یک زوج جوان شریک می‌شوید.', 'private_room'::property_type, 'Isfahan', 'شیخ بهایی', 'پلاک 27، کوچه‌ی نمونه، شیخ بهایی، اصفهان', 32.6402, 51.6401, ST_SetSRID(ST_MakePoint(51.639099, 32.638331), 4326)::geography, 1, false, 0, 1, 1, 1.0, 5200000.0, 0.0, 'IRR', '2022-04-15'),
  (774, 2027, 'استودیوی هنری در خیابان نظر', 'استودیویی که صاحبش نقاش است؛ دیوارها پر از تابلوهای خودش است. نور شمالی خوبی برای کار هنری دارد.', 'entire_place'::property_type, 'Isfahan', 'نظر', 'پلاک 11، کوچه‌ی نمونه، نظر، اصفهان', 32.6373, 51.6602, ST_SetSRID(ST_MakePoint(51.660847, 32.640012), 4326)::geography, 2, false, 0, 0, 1, 1.0, 20000000.0, 1200000.0, 'IRR', '2021-04-10'),
  (775, 2028, 'ویلای کوچک با استخر در حاشیه‌ی شهر', 'ویلا با حیاط، استخر و جکوزی (Hot tub) برای تعطیلات آخر هفته. بیرون از شلوغی، ۲۰ دقیقه تا مرکز.', 'entire_place'::property_type, 'Isfahan', 'خرازی', 'پلاک 9، کوچه‌ی نمونه، خرازی، اصفهان', 32.6302, 51.6903, ST_SetSRID(ST_MakePoint(51.691153, 32.628891), 4326)::geography, 8, true, 1, 3, 5, 2.0, 80000000.0, 6000000.0, 'IRR', '2021-02-14'),
  (776, 2029, 'آپارتمان مرکزی نزدیک مترو دروازه دولت', 'یک‌خوابه‌ی تمیز با دسترسی عالی به مترو. طبقه‌ی پنجم با آسانسور.', 'entire_place'::property_type, 'Isfahan', 'دروازه دولت', 'پلاک 71، کوچه‌ی نمونه، دروازه دولت، اصفهان', 32.6603, 51.6704, ST_SetSRID(ST_MakePoint(51.671405, 32.66074), 4326)::geography, 3, false, 0, 1, 2, 1.0, 23200000.0, 1600000.0, 'IRR', '2020-12-13'),
  (777, 2030, 'خوابگاه سنتی (اتاق اشتراکی) در عباس‌آباد', 'تخت در اتاق ۶ نفره‌ی مختلط در یک کاروانسرای بازسازی‌شده. حیاط مشترک و چای رایگان.', 'shared_room'::property_type, 'Isfahan', 'عباس‌آباد', 'پلاک 72، کوچه‌ی نمونه، عباس‌آباد، اصفهان', 32.6482, 51.6603, ST_SetSRID(ST_MakePoint(51.663957, 32.64887), 4326)::geography, 1, false, 0, 1, 6, 2.0, 5000000.0, 0.0, 'IRR', '2020-12-11'),
  (778, 2031, 'آپارتمان نزدیک باغ ارم', 'دو خوابه با بالکن، ۱۰ دقیقه پیاده تا باغ ارم. اردیبهشت که بیایید، بوی بهارنارنج همه‌ی خیابان را گرفته است.', 'entire_place'::property_type, 'Shiraz', 'ارم', 'پلاک 41، کوچه‌ی نمونه، ارم، شیراز', 29.6362, 52.5231, ST_SetSRID(ST_MakePoint(52.521347, 29.638759), 4326)::geography, 4, false, 0, 2, 3, 1.0, 30000000.0, 2400000.0, 'IRR', '2021-04-20'),
  (779, 2032, 'سوئیت مرکزی در خیابان زند', 'سوئیت یک‌خوابه، نزدیک ارگ کریم‌خان و بازار وکیل. برای گشتن در شهر قدیم بهترین نقطه است.', 'entire_place'::property_type, 'Shiraz', 'زند', 'پلاک 5، کوچه‌ی نمونه، زند، شیراز', 29.6172, 52.5402, ST_SetSRID(ST_MakePoint(52.540059, 29.620336), 4326)::geography, 2, false, 0, 1, 1, 1.0, 22000000.0, 1600000.0, 'IRR', '2021-05-31'),
  (780, 2033, 'خانه‌ی حیاط‌دار با درخت نارنج در قصردشت', 'خانه‌ی یک‌طبقه با حیاط، درخت‌های نارنج و تخت چوبی برای عصرانه. سه اتاق خواب و پارکینگ.', 'entire_place'::property_type, 'Shiraz', 'قصردشت', 'پلاک 23، کوچه‌ی نمونه، قصردشت، شیراز', 29.6403, 52.5002, ST_SetSRID(ST_MakePoint(52.496575, 29.641368), 4326)::geography, 6, true, 1, 3, 4, 2.0, 48000000.0, 4000000.0, 'IRR', '2022-05-31'),
  (781, 2034, 'اتاق در خانه‌ی تاریخی محله‌ی سنگ سیاه', 'اتاقی با طاق ضربی در خانه‌ای قدیمی در بافت تاریخی شیراز. مسجد نصیرالملک پیاده ۸ دقیقه است؛ ساعت ۸ صبح بروید تا نور شیشه‌ها را ببینید.', 'private_room'::property_type, 'Shiraz', 'سنگ سیاه', 'پلاک 85، کوچه‌ی نمونه، سنگ سیاه، شیراز', 29.6073, 52.5481, ST_SetSRID(ST_MakePoint(52.548769, 29.606188), 4326)::geography, 2, false, 0, 1, 1, 1.0, 8400000.0, 0.0, 'IRR', '2023-07-18'),
  (782, 2035, 'آپارتمان روشن نزدیک حافظیه', 'یک‌خوابه با پنجره‌های بزرگ، پیاده تا آرامگاه حافظ. شب‌ها حافظیه شلوغ و دیدنی است.', 'entire_place'::property_type, 'Shiraz', 'حافظیه', 'پلاک 56، کوچه‌ی نمونه، حافظیه، شیراز', 29.6232, 52.5582, ST_SetSRID(ST_MakePoint(52.555908, 29.624143), 4326)::geography, 3, false, 0, 1, 2, 1.0, 24000000.0, 2000000.0, 'IRR', '2020-05-14'),
  (783, 2036, 'آپارتمان مدرن با پارکینگ در معالی‌آباد', 'دو خوابه، نوساز، با آسانسور و پارکینگ. رستوران‌ها و فروشگاه‌ها در همان خیابان‌اند.', 'entire_place'::property_type, 'Shiraz', 'معالی‌آباد', 'پلاک 75، کوچه‌ی نمونه، معالی‌آباد، شیراز', 29.6482, 52.4953, ST_SetSRID(ST_MakePoint(52.49764, 29.651158), 4326)::geography, 4, false, 0, 2, 2, 2.0, 36000000.0, 2800000.0, 'IRR', '2021-10-26'),
  (784, 2037, 'سوئیت با ویوی کوه در بلوار چمران', 'سوئیت طبقه‌ی هفتم با منظره‌ی کوه‌های شمال شیراز. بلوار چمران پر از رستوران و فضای سبز است.', 'entire_place'::property_type, 'Shiraz', 'چمران', 'پلاک 73، کوچه‌ی نمونه، چمران، شیراز', 29.6603, 52.5152, ST_SetSRID(ST_MakePoint(52.512353, 29.661682), 4326)::geography, 2, false, 0, 1, 1, 1.0, 32000000.0, 2400000.0, 'IRR', '2023-11-09'),
  (785, 2038, 'اتاق خصوصی آرام نزدیک سعدیه', 'اتاقی با تخت دونفره در خانه‌ای با حیاط، نزدیک آرامگاه سعدی. صبحانه‌ی خانگی با ما.', 'private_room'::property_type, 'Shiraz', 'سعدی', 'پلاک 36، کوچه‌ی نمونه، سعدی، شیراز', 29.6223, 52.5853, ST_SetSRID(ST_MakePoint(52.583431, 29.620488), 4326)::geography, 2, false, 0, 1, 1, 1.0, 7000000.0, 0.0, 'IRR', '2020-02-24'),
  (786, 2039, 'آپارتمان سنتی نزدیک نارنجستان قوام', 'دو اتاق با گچ‌بری و آینه‌کاری در یک خانه‌ی قدیمی بازسازی‌شده، چند قدمی باغ نارنجستان.', 'entire_place'::property_type, 'Shiraz', 'نارنجستان', 'پلاک 74، کوچه‌ی نمونه، نارنجستان، شیراز', 29.6092, 52.5453, ST_SetSRID(ST_MakePoint(52.543153, 29.608846), 4326)::geography, 4, false, 0, 2, 3, 1.0, 40000000.0, 3200000.0, 'IRR', '2023-06-02'),
  (787, 2040, 'ویلای خانوادگی در شهرک گلستان', 'ویلا با حیاط بزرگ، استخر و باربیکیو. مناسب جمع‌های خانوادگی تا ۸ نفر.', 'entire_place'::property_type, 'Shiraz', 'گلستان', 'پلاک 89، کوچه‌ی نمونه، گلستان، شیراز', 29.6552, 52.4703, ST_SetSRID(ST_MakePoint(52.468842, 29.653847), 4326)::geography, 8, true, 1, 4, 6, 3.0, 74000000.0, 6000000.0, 'IRR', '2019-03-12'),
  (788, 2041, 'استودیوی کوچک کنار دروازه قرآن', 'استودیو برای یک یا دو نفر، شروع مسیر پیاده‌روی کوه‌های بابا کوهی.', 'entire_place'::property_type, 'Shiraz', 'دروازه قرآن', 'پلاک 53، کوچه‌ی نمونه، دروازه قرآن، شیراز', 29.6322, 52.5652, ST_SetSRID(ST_MakePoint(52.562901, 29.632004), 4326)::geography, 2, false, 0, 0, 1, 1.0, 18000000.0, 1200000.0, 'IRR', '2019-08-25'),
  (789, 2042, 'اتاق اشتراکی در هاستل زرهی', 'تخت در اتاق ۴ نفره‌ی زنانه. آشپزخانه‌ی مشترک، لاکر و Wi-Fi. تورهای تخت جمشید از همین‌جا حرکت می‌کنند.', 'shared_room'::property_type, 'Shiraz', 'زرهی', 'پلاک 56، کوچه‌ی نمونه، زرهی، شیراز', 29.6262, 52.5302, ST_SetSRID(ST_MakePoint(52.52805, 29.627596), 4326)::geography, 1, false, 0, 1, 4, 2.0, 5000000.0, 0.0, 'IRR', '2019-01-29'),
  (790, 2043, 'آپارتمان دوخوابه نزدیک خیابان ملاصدرا', 'آپارتمان ۹۰ متری با دو اتاق خواب، مناسب دو زوج یا خانواده‌ی کوچک.', 'entire_place'::property_type, 'Shiraz', 'ملاصدرا', 'پلاک 81، کوچه‌ی نمونه، ملاصدرا، شیراز', 29.6302, 52.5252, ST_SetSRID(ST_MakePoint(52.529871, 29.629796), 4326)::geography, 4, false, 0, 2, 2, 1.0, 28000000.0, 2000000.0, 'IRR', '2022-10-28')
) AS v(id, host_id, title, description, property_type, city, neighborhood, address, latitude,
  longitude, public_location, max_guests, pets_allowed, max_pets, bedrooms, beds, bathrooms,
  price_per_night, cleaning_fee, currency, created_at)
JOIN cities c ON c.name = v.city;

